import java.lang.management.MemoryUsage;
import java.lang.management.OperatingSystemMXBean;
import java.lang.management.RuntimeMXBean;
import java.util.HashMap;
import java.util.Map;

/**
 * Provides a simple system health monitor.
 */
public class SystemHealthMonitor {

    /**
     * Returns a map containing system health metrics.
     *
     * <p>The map contains the following keys:</p>
     * <ul>
     *   <li><b>status</b> – a {@code String}, always {@code "HEALTHY"}</li>
     *   <li><b>heapMemoryUsage</b> – a {@code Long}, current heap memory usage in bytes</li>
     *   <li><b>nonHeapMemoryUsage</b> – a {@code Long}, current non‑heap memory usage in bytes</li>
     *   <li><b>systemLoadAverage</b> – a {@code Double}, system load average (may be {@code -1.0} if unavailable)</li>
     *   <li><b>availableProcessors</b> – an {@code Integer}, number of available processors (must be positive)</li>
     *   <li><b>uptime</b> – a {@code Long}, JVM uptime in milliseconds</li>
     *   <li><b>totalMemory</b> – a {@code Long}, total memory available to the JVM in bytes</li>
     *   <li><b>freeMemory</b> – a {@code Long}, free memory available to the JVM in bytes</li>
     *   <li><b>threadCount</b> – an {@code Integer}, current number of active threads (at least 1)</li>
     * </ul>
     *
     * @return a {@link Map} with the above metrics
     * @throws IllegalStateException if any required key is missing or has an unexpected type
     */
    public Map<String, Object> getSystemHealth() {
        Map<String, Object> healthMetrics = new HashMap<>();

        // Basic status
        healthMetrics.put("status", "HEALTHY");

        // Memory metrics
        MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();

        MemoryUsage heapUsage = memoryBean.getHeapMemoryUsage();
        long heapUsed = heapUsage.getUsed();

        MemoryUsage nonHeapUsage = memoryBean.getNonHeapMemoryUsage();
        long nonHeapUsed = nonHeapUsage.getUsed();

        healthMetrics.put("heapMemoryUsage", Long.valueOf(heapUsed));
        healthMetrics.put("nonHeapMemoryUsage", Long.valueOf(nonHeapUsed));

        // Operating system metrics
        OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();

        double loadAverage = osBean.getSystemLoadAverage(); // may be -1.0 if unavailable
        int availableProcessors = osBean.getAvailableProcessors(); // must be positive

        healthMetrics.put("systemLoadAverage", loadAverage);
        healthMetrics.put("availableProcessors", availableProcessors);

        // Runtime metrics
        RuntimeMXBean runtimeBean = ManagementFactory.getRuntimeMXBean();
        long uptime = runtimeBean.getUptime(); // JVM uptime in milliseconds

        Runtime runtime = Runtime.getRuntime();
        long totalMemory = runtime.totalMemory(); // total memory in bytes
        long freeMemory = runtime.freeMemory();   // free memory in bytes

        healthMetrics.put("uptime", Long.valueOf(uptime));
        healthMetrics.put("totalMemory", Long.valueOf(totalMemory));
        healthMetrics.put("freeMemory", Long.valueOf(freeMemory));

        // Thread metrics
        int threadCount = Thread.activeCount();
        if (threadCount < 1) {
            threadCount = 1; // ensure at least 1
        }
        healthMetrics.put("threadCount", Integer.valueOf(threadCount));

        // Validate the map before returning
        validateHealthMetrics(healthMetrics);

        return healthMetrics;
    }

    /**
     * Validates that the health metrics map contains all required keys with the expected types.
     *
     * @param metrics the map to validate
     * @throws IllegalStateException if validation fails
     */
    private void validateHealthMetrics(Map<String, Object> metrics) {
        if (!metrics.containsKey("status") || !(metrics.get("status") instanceof String)) {
            throw new IllegalStateException("Missing or invalid 'status' key");
        }
        if (!metrics.containsKey("heapMemoryUsage") || !(metrics.get("heapMemoryUsage") instanceof Long)) {
            throw new IllegalStateException("Missing or invalid 'heapMemoryUsage' key");
        }
        if (!metrics.containsKey("nonHeapMemoryUsage") || !(metrics.get("nonHeapMemoryUsage") instanceof Long)) {
            throw new IllegalStateException("Missing or invalid 'nonHeapMemoryUsage' key");
        }
        if (!metrics.containsKey("systemLoadAverage") || !(metrics.get("systemLoadAverage") instanceof Double)) {
            throw new IllegalStateException("Missing or invalid 'systemLoadAverage' key");
        }
        if (!metrics.containsKey("availableProcessors") || !(metrics.get("availableProcessors") instanceof Integer)) {
            throw new IllegalStateException("Missing or invalid 'availableProcessors' key");
        }
        if (!metrics.containsKey("uptime") || !(metrics.get("uptime") instanceof Long)) {
            throw new IllegalStateException("Missing or invalid 'uptime' key");
        }
        if (!metrics.containsKey("totalMemory") || !(metrics.get("totalMemory") instanceof Long)) {
            throw new IllegalStateException("Missing or invalid 'totalMemory' key");
        }
        if (!metrics.containsKey("freeMemory") || !(metrics.get("freeMemory") instanceof Long)) {
            throw new IllegalStateException("Missing or invalid 'freeMemory' key");
        }
        if (!metrics.containsKey("threadCount") || !(metrics.get("threadCount") instanceof Integer)) {
            throw new IllegalStateException("Missing or invalid 'threadCount' key");
        }

        // Additional logical checks
        int availableProcessors = (Integer) metrics.get("availableProcessors");
        if (availableProcessors <= 0) {
            throw new IllegalStateException("'availableProcessors' must be positive");
        }

        int threadCount = (Integer) metrics.get("threadCount");
        if (threadCount < 1) {
            throw new IllegalStateException("'threadCount' must be at least 1");
        }
    }
}

