class AdvancedBufferOperations {
    public String performAdvancedBufferOperations(int bufferSize, int[] writeValues) {
        if (bufferSize <= 0) {
            throw new IllegalArgumentException("bufferSize must be positive");
        }
        if (writeValues == null) {
            throw new IllegalArgumentException("writeValues cannot be null");
        }

        StringBuilder result = new StringBuilder();
        IntBuffer intBuffer = IntBuffer.allocate(bufferSize);

        // Write values into buffer, respecting buffer capacity
        for (int value : writeValues) {
            if (!intBuffer.hasRemaining()) {
                break; // buffer full
            }
            intBuffer.put(value);
        }

        // Prepare buffer for reading
        intBuffer.flip();

        result.append("Buffer contents: ");
        while (intBuffer.hasRemaining()) {
            result.append(intBuffer.get()).append(" ");
        }
        result.append("\n");

        return result.toString();
    }
}

