import java.nio.ByteBuffer;
import java.nio.BufferOverflowException;

class AdvancedBufferOperations {
    public String performAdvancedBufferOperations(int bufferSize, int[] writeValues) {
        if (bufferSize <= 0) {
            throw new IllegalArgumentException("bufferSize must be positive");
        }
        if (writeValues == null) {
            throw new IllegalArgumentException("writeValues cannot be null");
        }

        StringBuilder result = new StringBuilder();
        IntBuffer intBuffer = IntBuffer.allocate(bufferSize);

        // Write values into the buffer, handling overflow
        try {
            for (int value : writeValues) {
                intBuffer.put(value); // may throw BufferOverflowException
            }
        } catch (BufferOverflowException e) {
            return "Error: Attempted to write beyond buffer capacity";
        }

        // Prepare buffer for reading
        intBuffer.flip();

        // Read and record the full buffer content
        result.append("Buffer contents: ");
        while (intBuffer.hasRemaining()) {
            result.append(intBuffer.get()).append(" ");
        }
        result.append("\n");

        // Reset buffer for partial read
        intBuffer.rewind();                     // position = 0, limit = capacity
        intBuffer.position(1);                  // set position to 1
        intBuffer.limit(Math.min(3, bufferSize)); // set limit to 3 (or capacity if smaller)

        // Read and record the partial buffer content
        result.append("Partial buffer content (position 1, limit 3): ");
        while (intBuffer.hasRemaining()) {
            result.append(intBuffer.get()).append(" ");
        }
        result.append("\n");

        // ---------- ByteBuffer operations ----------
        // Allocate a ByteBuffer with enough capacity for an int, double, and char
        ByteBuffer byteBuffer = ByteBuffer.allocate(16); // 4 + 8 + 2 = 14 bytes, 16 for alignment

        // Write an int (100), a double (3.14159), and a char ('A')
        byteBuffer.putInt(100);
        byteBuffer.putDouble(3.14159);
        byteBuffer.putChar('A');

        // Prepare for reading
        byteBuffer.flip();

        // Read back the values and append to the result
        int readInt = byteBuffer.getInt();
        double readDouble = byteBuffer.getDouble();
        char readChar = byteBuffer.getChar();

        result.append("Read int: ").append(readInt).append("\n");
