        player.setPosition(startX, startY);
    }

    /**
     * Moves the player one unit in the specified direction.
     *
     * @param dir the direction to move
     * @return the new position of the player as an int array [x, y]
     */
    public int[] handlePlayerMovement(Direction dir) {
        int dx = 0, dy = 0;
        switch (dir) {
            case UP:
                dy = 1;
                break;
            case DOWN:
                dy = -1;
                break;
            case LEFT:
                dx = -1;
                break;
            case RIGHT:
                dx = 1;
                break;
        }
        player.move(dx, dy);
        return player.getPosition();
    }

    public int[] getPlayerPosition() {
        return player.getPosition();
    }
}

