import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

class DateUtil {

    /**
     * Returns a two‑digit string representation of the given number.
     * The number must be between 1 and 31 (inclusive).
     *
     * @param number the number to format
     * @return a two‑digit string
     * @throws IllegalArgumentException if number is not in [1, 31]
     */
    public String getStrNumber(int number) {
        if (number < 1 || number > 31) {
            throw new IllegalArgumentException("Number must be between 1 and 31");
        }
        return String.format("%02d", number);
    }

    /**
     * Parses {@code inputDate} using {@code inputFormat} and returns the date
     * formatted according to {@code outputFormat}.
     *
     * @param inputDate    the date string to parse
     * @param inputFormat  the pattern of the input date
     * @param outputFormat the pattern for the output date
     * @return the formatted date string
     * @throws DateTimeParseException if the input date does not match the input format
     */
    public String formatDate(String inputDate, String inputFormat, String outputFormat) {
        DateTimeFormatter inputFormatter = DateTimeFormatter.ofPattern(inputFormat);
        LocalDate date = LocalDate.parse(inputDate, inputFormatter);
        DateTimeFormatter outputFormatter = DateTimeFormatter.ofPattern(outputFormat);
        return date.format(outputFormatter);
    }
}

