import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;

public class PathAnalyzer {

    /**
     * Analyzes the given file path and returns a map containing the filename,
     * its extension, the parent directory path in normalized form, and the depth
     * (number of directory levels). The filename is not counted in the depth.
     *
     * @param filePath the file path to analyze
     * @return a map with four entries:
     *         - "filename"  -> the filename component of the path
     *         - "extension" -> the file extension (empty string if none)
     *         - "parentDir" -> the normalized parent directory path
     *                         (empty string if there is no parent)
     *         - "depth"     -> the number of directory levels in the path
     * @throws IllegalArgumentException if filePath is null or empty
     */
    public static Map<String, Object> analyzePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("Input filePath cannot be null or empty");
        }

        Path originalPath = Paths.get(filePath);
        Path normalizedPath = originalPath.normalize();

        // Filename
        String filename = normalizedPath.getFileName() != null
                ? normalizedPath.getFileName().toString()
                : "";

        // Extension
        String extension = "";
        int lastDot = filename.lastIndexOf('.');
        if (lastDot > 0 && lastDot < filename.length() - 1) {
            extension = filename.substring(lastDot + 1);
        }

        // Parent directory (normalized)
        String parentDir = "";
        Path parent = normalizedPath.getParent();
        if (parent != null) {
            parentDir = parent.toString();
        }

        // Depth: number of directory levels (exclude filename if it has an extension)
        int nameCount = normalizedPath.getNameCount();
        int depth = nameCount;
        if (!extension.isEmpty() && nameCount > 0) {
            depth = nameCount - 1;
        }

        Map<String, Object> result = new HashMap<>();
        result.put("filename", filename);
        result.put("extension", extension);
        result.put("parentDir", parentDir);
        result.put("depth", depth);
        return result;
    }
}

