import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;

public class PathAnalyzer {

    /**
     * Analyzes the given file path and returns a map containing:
     * <ul>
     *   <li>filename   – the file name component</li>
     *   <li>extension  – the file extension (empty if none)</li>
     *   <li>parentDir  – the normalized parent directory path (empty if none)</li>
     *   <li>depth      – number of directory levels in the path (filename not counted)</li>
     *   <li>isValid    – true if the original path has no spaces and is ≤ 260 characters</li>
     * </ul>
     *
     * @param filePath the file path to analyze
     * @return a map with the above entries
     * @throws IllegalArgumentException if filePath is null or empty
     */
    public static Map<String, Object> analyzePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("Input filePath cannot be null or empty");
        }

        // Validation based on the original input string
        boolean isValid = !filePath.contains(" ") && filePath.length() <= 260;

        // Normalized path for further analysis
        Path originalPath = Paths.get(filePath);
        Path normalizedPath = originalPath.normalize();

        // Filename
        String filename = normalizedPath.getFileName() != null
                ? normalizedPath.getFileName().toString()
                : "";

        // Extension
        String extension = "";
        int lastDot = filename.lastIndexOf('.');
        if (lastDot > 0 && lastDot < filename.length() - 1) {
            extension = filename.substring(lastDot + 1);
        }

        // Parent directory (normalized)
        String parentDir = "";
        Path parent = normalizedPath.getParent();
        if (parent != null) {
            parentDir = parent.toString();
        }

        // Depth: number of directory levels (exclude filename)
        int nameCount = normalizedPath.getNameCount();
        int depth = nameCount > 0 ? nameCount - 1 : 0;

        Map<String, Object> result = new HashMap<>();
        result.put("filename", filename);
        result.put("extension", extension);
        result.put("parentDir", parentDir);
        result.put("depth", depth);
        result.put("isValid", isValid);

        return result;
    }
}

