import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Collectors;

public class AdvancedFileProcessor {
    private final Path directory;

    public AdvancedFileProcessor(String dirPath) {
        Path p = Paths.get(dirPath);
        if (!Files.isDirectory(p)) {
            throw new IllegalArgumentException("Provided path is not a directory: " + dirPath);
        }
        this.directory = p;
    }

    public Map<String, Object> processFiles() {
        int fileCount = 0;
        long totalSize = 0L;
        long largestSize = -1L;
        String largestFileName = "N/A";
        Map<String, Integer> wordFrequency = new HashMap<>();

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directory)) {
            for (Path entry : stream) {
                if (Files.isRegularFile(entry)) {
                    fileCount++;
                    long size = Files.size(entry);
                    totalSize += size;

                    if (size > largestSize) {
                        largestSize = size;
                        largestFileName = entry.getFileName().toString();
                    }

                    // Update word frequency for this file
                    processFileContent(entry, wordFrequency);
                }
            }
        } catch (IOException e) {
            // In a real application you might want to handle this differently.
            // For now we simply leave the counts at zero.
        }

        // Sort the word frequency map by value in descending order
        Map<String, Integer> sortedWordFrequency = sortByValue(wordFrequency);

        Map<String, Object> stats = new HashMap<>();
        stats.put("fileCount", fileCount);
        stats.put("totalSize", totalSize);
        stats.put("largestFile", largestFileName);
        stats.put("wordFrequency", sortedWordFrequency);

        return stats;
    }

    /**
     * Reads the content of the given file, splits it into words, normalizes them,
     * and updates the provided word frequency map.
     *
     * @param file          the file to read
     * @param wordFrequency the map to update with word counts
     */
    private void processFileContent(Path file, Map<String, Integer> wordFrequency) {
        try {
            // Read all lines from the file using UTF-8 encoding
            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                // Split the line into words based on whitespace
                String[] words = line.split("\\s+");
                for (String word : words) {
                    // Remove non‑alphabetic characters and convert to lowercase
                    String cleaned = word.replaceAll("[^A-Za-z]", "").toLowerCase();
                    if (!cleaned.isEmpty()) {
                        wordFrequency.merge(cleaned, 1, Integer::sum);
                    }
                }
            }
        } catch (IOException e) {
            // If a file cannot be read, we simply skip it.
            // In a production system you might log this event.
        }
    }

    /**
     * Returns a new LinkedHashMap containing the entries of the given map
     * sorted by their integer values in descending order.
     *
     * @param map the map to sort
     * @return a LinkedHashMap sorted by value descending
     */
    private Map<String, Integer> sortByValue(Map<String, Integer> map) {
        return map.entrySet()
                  .stream()
                  .sorted((e1, e2) -> {
                      int cmp = e2.getValue().compareTo(e1.getValue());
                      if (cmp == 0) {
                          // If values are equal, sort by key to have deterministic order
                          return e1.getKey().compareTo(e2.getKey());
                      }
                      return cmp;
                  })
                  .collect(Collectors.toMap(
                          Map.Entry::getKey,
                          Map.Entry::getValue,
                          (oldValue, newValue) -> oldValue,
                          LinkedHashMap::new));
    }
}

