/**
 * Represents a single policy with previous and current risk information
 * and the premium amount.
 */
class PolicyData {
    private final String previousRiskCode;
    private final String previousRiskName;
    private final String currentRiskCode;
    private final String currentRiskName;
    private final double premium;

    public PolicyData(String previousRiskCode, String previousRiskName,
                      String currentRiskCode, String currentRiskName,
                      double premium) {
        this.previousRiskCode = previousRiskCode;
        this.previousRiskName = previousRiskName;
        this.currentRiskCode = currentRiskCode;
        this.currentRiskName = currentRiskName;
        this.premium = premium;
    }

    public String getPreviousRiskCode() { return previousRiskCode; }
    public String getPreviousRiskName() { return previousRiskName; }
    public String getCurrentRiskCode() { return currentRiskCode; }
    public String getCurrentRiskName() { return currentRiskName; }
    public double getPremium() { return premium; }
}

/**
 * Analyzes financial data for a list of policies and produces
 * summaries for previous and current risk categories.
 */
public class FinancialReportAnalyzer {

    /**
     * Inner class that keeps a running total of premiums and policy counts
     * for a particular risk category.
     */
    public static class RiskSummary {
        private final String riskName;
        private double totalPremium;
        private int policyCount;

        public RiskSummary(String riskName) {
            this.riskName = riskName;
            this.totalPremium = 0.0;
            this.policyCount = 0;
        }

        public void addPolicy(double premium) {
            this.totalPremium += premium;
            this.policyCount++;
        }

        public String getRiskName() { return riskName; }
        public double getTotalPremium() { return totalPremium; }
        public int getPolicyCount() { return policyCount; }
    }

    /**
     * Generates separate summaries for previous and current risk categories.
     *
     * @param policies list of PolicyData objects
     * @return a map containing two keys:
     *         "preRiskSummary" -> List of maps for previous risks
     *         "curRiskSummary" -> List of maps for current risks
     *         Each map in the lists contains:
     *         - riskCode (String)
     *         - riskName (String)
     *         - premium (String, formatted to 2 decimal places)
     *         - policyCount (Integer)
     */
    public Map<String, List<Map<String, Object>>> analyzeFinancialData(List<PolicyData> policies) {
        // Maps to accumulate summaries keyed by risk code
        Map<String, RiskSummary> preMap = new HashMap<>();
        Map<String, RiskSummary> curMap = new HashMap<>();

        // Accumulate data
        for (PolicyData policy : policies) {
            // Previous risk
            String preCode = policy.getPreviousRiskCode();
            String preName = policy.getPreviousRiskName();
            preMap.computeIfAbsent(preCode, k -> new RiskSummary(preName))
                  .addPolicy(policy.getPremium());

            // Current risk
            String curCode = policy.getCurrentRiskCode();
            String curName = policy.getCurrentRiskName();
            curMap.computeIfAbsent(curCode, k -> new RiskSummary(curName))
                  .addPolicy(policy.getPremium());
        }

        // Convert maps to lists of maps
        List<Map<String, Object>> preRiskSummary = new ArrayList<>();
        for (Map.Entry<String, RiskSummary> entry : preMap.entrySet()) {
            Map<String, Object> map = new HashMap<>();
            map.put("riskCode", entry.getKey());
            map.put("riskName", entry.getValue().getRiskName());
            map.put("premium", String.format("%.2f", entry.getValue().getTotalPremium()));
            map.put("policyCount", entry.getValue().getPolicyCount());
            preRiskSummary.add(map);
        }

        List<Map<String, Object>> curRiskSummary = new ArrayList<>();
        for (Map.Entry<String, RiskSummary> entry : curMap.entrySet()) {
            Map<String, Object> map = new HashMap<>();
            map.put("riskCode", entry.getKey());
            map.put("riskName", entry.getValue().getRiskName());
            map.put("premium", String.format("%.2f", entry.getValue().getTotalPremium()));
            map.put("policyCount", entry.getValue().getPolicyCount());
            curRiskSummary.add(map);
        }

        // Prepare result
        Map<String, List<Map<String, Object>>> result = new HashMap<>();
        result.put("preRiskSummary", preRiskSummary);
        result.put("curRiskSummary", curRiskSummary);
        return result;
    }
}

