            head = tail = newNode;
        } else {                     // append after tail
            tail.next = newNode;
            newNode.prev = tail;
            tail = newNode;
        }
        size++;
    }

    /**
     * Removes and returns the last element of the list.
     *
     * @return the data of the removed element
     * @throws NoSuchElementException if the list is empty
     */
    public D remove() {
