     * @throws IndexOutOfBoundsException if the index is out of range
     */
    public D get(int index) {
        Node node = getNode(index);
        return node.data;
    }

    /**
     * Checks whether the list contains the specified element.
     *
     * @param data the element to search for
     * @return true if the element is found
     */
    public boolean contains(D data) {
        Node current = head;
        while (current != null) {
            if (data == null) {
                if (current.data == null) {
                    return true;
                }
            } else if (data.equals(current.data)) {
                return true;
            }
            current = current.next;
        }
        return false;
    }

    /**
     * Efficiently retrieves the node at the specified index.
     * Traverses from the head if the index is in the first half,
     * otherwise traverses from the tail.
     *
     * @param index the position of the node to retrieve
     * @return the node at the given index
     * @throws IndexOutOfBoundsException if the index is out of range
     */
    private Node getNode(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException(
                "Index: " + index + ", Size: " + size);
        }

        Node current;
        if (index < size / 2) {          // closer to head
            current = head;
            for (int i = 0; i < index; i++) {
                current = current.next;
            }
        } else {                         // closer to tail
            current = tail;
            for (int i = size - 1; i > index; i--) {
                current = current.prev;
            }
        }
        return current;
    }

    /** String representation of the list: [elem1, elem2, ...] */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        Node current = head;
        while (current != null) {
            sb.append(current.data);
            current = current.next;
            if (current != null) sb.append(", ");
        }
        sb.append("]");
        return sb.toString();
    }

