        // Add elements
        list.add(10);
        list.add(20);
        list.add(30);
        System.out.println("Initial list: " + list);          // [10, 20, 30]

        // Insert at various positions
        list.add(0, 5);   // beginning
        list.add(2, 15);  // middle
        list.add(list.size(), 35); // end
        System.out.println("After insertions: " + list);     // [5, 10, 15, 20, 30, 35]

        // Remove by index
        int removed = list.remove(3); // remove element at index 3 (20)
        System.out.println("Removed at index 3: " + removed); // 20
        System.out.println("After removal: " + list);          // [5, 10, 15, 30, 35]

        // Remove last element
        int last = list.remove();
        System.out.println("Removed last: " + last);          // 35
        System.out.println("After removing last: " + list);   // [5, 10, 15, 30]

        // Contains
