        System.out.println("Contains 100? " + list.contains(100)); // false

        // isEmpty and clear
        System.out.println("Is empty? " + list.isEmpty()); // false
        list.clear();
        System.out.println("After clear: " + list);        // []
        System.out.println("Is empty? " + list.isEmpty()); // true
    }
