        System.out.println("Current tag: " + fm.getCurrentFragmentTag());

        fm.switchFragment("settings");
        System.out.println("Current fragment: " + fm.getCurrentFragment());
        System.out.println("Current tag: " + fm.getCurrentFragmentTag());

        // Switching to the same fragment again
        boolean sameSwitch = fm.switchFragment("settings");
        System.out.println("Switching to the same fragment returned: " + sameSwitch);
        System.out.println("Current fragment after same switch: " + fm.getCurrentFragment());

        // Attempt to switch to a non‑existent fragment
        boolean success = fm.switchFragment("profile");
        System.out.println("Switch to 'profile' successful? " + success);
        System.out.println("Current after failed switch: " + fm.getCurrentFragment());
    }
