class FragmentManager {
    private final Map<String, Fragment> fragments = new HashMap<>();
    private Fragment currentFragment = null;
    private String currentTag = null;

    public void addFragment(String tag, Fragment fragment) {
        if (tag == null || fragment == null) {
            throw new IllegalArgumentException("Tag and fragment cannot be null");
        }
        fragments.put(tag, fragment);
    }

    /**
     * Switches to the fragment identified by {@code tag}.
     *
     * @param tag the tag of the fragment to switch to
     * @return {@code true} if the fragment exists and the switch was performed
     *         (or if it is already the current fragment), {@code false}
     *         otherwise (no change to the current fragment)
     */
    public boolean switchFragment(String tag) {
        if (tag == null) {
            return false;
        }

        // If the requested fragment is already current, just return true
        if (tag.equals(currentTag)) {
            return true;
        }

        Fragment f = fragments.get(tag);
        if (f == null) {
            return false;
        }

        currentFragment = f;
        currentTag = tag;
        return true;
    }

    public Fragment getCurrentFragment() {
        return currentFragment;
    }

    public String getCurrentFragmentTag() {
        return currentTag;
    }
}

