        // Create a deep copy of the original matrix
        int[][] originalCopy = deepCopy(matrix);

        // Create a copy of the original matrix to apply modifications
        int[][] result = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            System.arraycopy(matrix[r], 0, result[r], 0, cols);
