import java.util.*;

public class AdditionChainFinder {

    /**
     * Finds the shortest addition chain that starts with 1 and ends with the given target.
     *
     * @param target the target number (must be >= 1)
     * @return a list of integers representing the shortest addition chain
     */
    public List<Integer> findShortestAdditionChain(int target) {
        if (target <= 1) {
            return Collections.singletonList(1);
        }

        List<Integer> chain = new ArrayList<>();
        chain.add(1);

        // Iterative deepening: try increasing chain lengths until a solution is found
        for (int maxDepth = 1; ; maxDepth++) {
            if (dfs(chain, 0, maxDepth, target)) {
                return new ArrayList<>(chain);
            }
        }
    }

    /**
     * Depth‑first search with pruning to build an addition chain.
     *
     * @param chain    current chain (mutable)
     * @param depth    current depth (number of steps taken after the initial 1)
     * @param maxDepth maximum allowed depth for this search
     * @param target   target number to reach
     * @return true if a valid chain ending at target is found
     */
    private boolean dfs(List<Integer> chain, int depth, int maxDepth, int target) {
        if (depth == maxDepth) {
            return chain.get(chain.size() - 1) == target;
        }

        int currentMax = chain.get(chain.size() - 1);
        int remaining = maxDepth - depth;

        // Prune if even doubling the current maximum each remaining step cannot reach target
        long maxPossible = (long) currentMax << remaining;
        if (maxPossible < target) {
            return false;
        }

        // Generate all possible next numbers in descending order to reach target faster
        Set<Integer> candidates = new TreeSet<>(Collections.reverseOrder());
        int size = chain.size();
        for (int i = size - 1; i >= 0; i--) {
            for (int j = i; j >= 0; j--) {
                int sum = chain.get(i) + chain.get(j);
                if (sum > currentMax && sum <= target) {
                    candidates.add(sum);
                }
            }
        }

        for (int next : candidates) {
            chain.add(next);
            if (dfs(chain, depth + 1, maxDepth, target)) {
                return true;
            }
            chain.remove(chain.size() - 1);
        }

        return false;
    }
}

