    /**
     * Returns the in-order successor of the given node in a binary tree that
     * contains parent pointers.
     *
     * <ul>
     *   <li>If the node has a right child, the successor is the leftmost node
     *   in the right subtree.</li>
     *   <li>Otherwise, the successor is the first ancestor for which the node
     *   lies in the left subtree. If no such ancestor exists, the node is the
     *   rightmost node and the method returns {@code null}.</li>
     * </ul>
     *
     * @param node the node whose successor is to be found
     * @return the in-order successor or {@code null} if none exists
     * @throws IllegalArgumentException if {@code node} is {@code null}
     */
    public static BinaryTreeNode findNextNode(BinaryTreeNode node) {
        if (node == null) {
            throw new IllegalArgumentException("Input node cannot be null");
        }

        // Case 1: node has a right child – successor is leftmost node in right subtree
        if (node.right != null) {
            BinaryTreeNode current = node.right;
            while (current.left != null) {
                current = current.left;
            }
            return current;
        }

        // Case 2: node has no right child – climb up using parent pointers
        BinaryTreeNode ancestor = node.parent;
        BinaryTreeNode child = node;
        while (ancestor != null && child == ancestor.right) {
            child = ancestor;
            ancestor = ancestor.parent;
