import java.util.HashMap;
import java.util.Map;

class FileUploadUtil {

    /**
     * Extracts the filename from a Content-Disposition header.
     *
     * @param contentDisposition the header string, e.g. "form-data; name=\"file\"; filename=\"example.txt\""
     * @return the filename without surrounding quotes, or {@code null} if none found
     */
    public static String getFilename(String contentDisposition) {
        if (contentDisposition == null) {
            return null;
        }

        // Search for the first occurrence of "filename=" (case‑insensitive)
        String lower = contentDisposition.toLowerCase();
        int idx = lower.indexOf("filename=");
        if (idx == -1) {
            return null;
        }

        // Position after "filename="
        int start = idx + "filename=".length();

        // Skip any leading whitespace
        while (start < contentDisposition.length()
                && Character.isWhitespace(contentDisposition.charAt(start))) {
            start++;
        }

        if (start >= contentDisposition.length()) {
            return null;
        }

        char firstChar = contentDisposition.charAt(start);
        if (firstChar == '"' || firstChar == '\'') {
            // Quoted filename
            int end = contentDisposition.indexOf(firstChar, start + 1);
            if (end == -1) {
                return null; // malformed header
            }
            return contentDisposition.substring(start + 1, end);
        } else {
            // Unquoted filename – read until a delimiter
            int end = start;
            while (end < contentDisposition.length()
                    && contentDisposition.charAt(end) != ';'
                    && !Character.isWhitespace(contentDisposition.charAt(end))) {
                end++;
            }
            return contentDisposition.substring(start, end);
        }
    }
}

