import java.io.UnsupportedEncodingException;
import java.net.URLDecoder;

class FileUploadUtil {

    /**
     * Extracts the filename from a Content-Disposition header.
     * Handles both {@code filename} and {@code filename*} parameters,
     * supports quoted values, single quotes, and percent‑encoded values.
     *
     * @param contentDisposition the header string, e.g.
     *        {@code "form-data; name=\"file\"; filename=\"example.txt\""}
     * @return the decoded filename, or {@code null} if none found
     */
    public static String getFilename(String contentDisposition) {
        if (contentDisposition == null) {
            return null;
        }

        String filenameStar = null;
        String filename = null;

        // Split the header into individual parameters
        String[] parts = contentDisposition.split(";");
        for (String part : parts) {
            part = part.trim();
            String lower = part.toLowerCase();

            if (lower.startsWith("filename*=")) {
                filenameStar = part.substring("filename*=".length()).trim();
            } else if (lower.startsWith("filename=")) {
                filename = part.substring("filename=".length()).trim();
            }
        }

        // RFC 5987 says filename* takes precedence over filename
        if (filenameStar != null) {
            return decodeFilenameStar(filenameStar);
        } else if (filename != null) {
            return decodeFilename(filename);
        }

        return null;
    }

    /** Decode a {@code filename*} value (RFC 5987). */
    private static String decodeFilenameStar(String value) {
        // Remove surrounding quotes if present
        if ((value.startsWith("\"") && value.endsWith("\"")) ||
            (value.startsWith("'") && value.endsWith("'"))) {
            value = value.substring(1, value.length() - 1);
        }

        // RFC 5987 format: charset'lang'value
        int firstQuote = value.indexOf('\'');
        if (firstQuote != -1) {
            int secondQuote = value.indexOf('\'', firstQuote + 1);
            if (secondQuote != -1) {
                String charset = value.substring(0, firstQuote);
                // String lang = value.substring(firstQuote + 1, secondQuote); // ignored
                String encoded = value.substring(secondQuote + 1);
                try {
                    return URLDecoder.decode(encoded, charset);
                } catch (UnsupportedEncodingException e) {
                    // Fallback to UTF-8 if the charset is unknown
                    try {
                        return URLDecoder.decode(encoded, "UTF-8");
                    } catch (UnsupportedEncodingException ex) {
                        // Should never happen – return raw value
                        return encoded;
                    }
                }
            }
        }

        // No charset specified – treat as percent‑encoded UTF‑8
        try {
            return URLDecoder.decode(value, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            return value;
        }
    }

    /** Decode a simple {@code filename} value. */
    private static String decodeFilename(String value) {
        // Remove surrounding quotes if present
        if ((value.startsWith("\"") && value.endsWith("\"")) ||
            (value.startsWith("'") && value.endsWith("'"))) {
            value = value.substring(1, value.length() - 1);
        }
        return value;
    }
}

