            return true;
        }
        return false;
    }

    /**
     * Sets the current octave to the specified value, clamping it to the allowed range
     * and notifying listeners of the change.
     *
     * @param newOctave the octave to set
     */
    public void setOctave(int newOctave) {
        int clamped = Math.max(minOctave, Math.min(maxOctave, newOctave));
        setCurrentOctave(clamped);
    }

    /**
     * Private helper that updates the current octave and notifies listeners.
     *
     * @param newOctave the new octave value
     */
    private void setCurrentOctave(int newOctave) {
        int oldOctave = currentOctave;
        if (oldOctave != newOctave) {
            currentOctave = newOctave;
            notifyListeners(oldOctave, newOctave);
        }
    }

    /**
     * Notifies all registered listeners of an octave change.
     *
     * @param oldOctave the previous octave value
     * @param newOctave the new octave value
     */
    private void notifyListeners(int oldOctave, int newOctave) {
        for (PianoOctaveChangeListener listener : listeners) {
            listener.onOctaveChanged(oldOctave, newOctave);
        }
    }

    /**
     * Listener interface for octave change events.
     */
    public interface PianoOctaveChangeListener {
        void onOctaveChanged(int oldOctave, int newOctave);
    }

