import java.util.*;

public class DataMatcher {

    /**
     * Performs an enhanced match between two datasets based on the specified key indices.
     *
     * @param dataset1     the first dataset, a list of string arrays
     * @param dataset2     the second dataset, a list of string arrays
     * @param matchStrategy the matching strategy (currently only 1 = exact match is supported)
     * @param keyIndices   the indices of the fields to use for matching
     * @return a map containing three entries:
     *         "matched"   -> list of concatenated matched records
     *         "unmatched1" -> list of records from dataset1 that had no match
     *         "unmatched2" -> list of records from dataset2 that had no match
     */
    public Map<String, List<String[]>> enhancedMatch(
            List<String[]> dataset1,
            List<String[]> dataset2,
            int matchStrategy,
            int[] keyIndices) {

        List<String[]> matched = new ArrayList<>();
        List<String[]> unmatched1 = new ArrayList<>();
        List<String[]> unmatched2 = new ArrayList<>();

        // If the strategy is not exact match, simply return all as unmatched
        if (matchStrategy != 1) {
            unmatched1.addAll(dataset1);
            unmatched2.addAll(dataset2);
            return buildResultMap(matched, unmatched1, unmatched2);
        }

        // Create a mutable copy of dataset2 for removal of matched records
        List<String[]> remainingDataset2 = new ArrayList<>(dataset2);

        for (String[] record1 : dataset1) {
            String key1 = buildKey(record1, keyIndices);
            boolean foundMatch = false;

            Iterator<String[]> iter = remainingDataset2.iterator();
            while (iter.hasNext()) {
                String[] record2 = iter.next();
                String key2 = buildKey(record2, keyIndices);

                if (key1.equals(key2)) {
                    // Combine the two records
                    String[] combined = concatenate(record1, record2);
                    matched.add(combined);
                    iter.remove(); // remove matched record from dataset2
                    foundMatch = true;
                    break; // stop after first match
                }
            }

            if (!foundMatch) {
                unmatched1.add(record1);
            }
        }

        // Remaining records in dataset2 are unmatched
        unmatched2.addAll(remainingDataset2);

        return buildResultMap(matched, unmatched1, unmatched2);
    }

    /**
     * Builds a concatenated key string from the specified indices of a record.
     * Each value is trimmed before concatenation.
     */
    private String buildKey(String[] record, int[] keyIndices) {
        StringBuilder sb = new StringBuilder();
        for (int idx : keyIndices) {
            if (idx >= 0 && idx < record.length) {
                sb.append(record[idx].trim());
            } else {
                sb.append(""); // treat out-of-bounds as empty string
            }
            sb.append("|"); // delimiter to avoid accidental merges
        }
        return sb.toString();
    }

    /**
     * Concatenates two string arrays into a new array.
     */
    private String[] concatenate(String[] a, String[] b) {
        String[] result = new String[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }

    /**
     * Builds the result map with the specified lists.
     */
    private Map<String, List<String[]>> buildResultMap(
            List<String[]> matched,
            List<String[]> unmatched1,
            List<String[]> unmatched2) {

        Map<String, List<String[]>> result = new HashMap<>();
        result.put("matched", matched);
        result.put("unmatched1", unmatched1);
        result.put("unmatched2", unmatched2);
        return result;
    }
}

