        int maxLen1 = 0;
        for (String[] rec : dataset1) {
            if (rec != null && rec.length > maxLen1) {
                maxLen1 = rec.length;
            }
        }
        int maxLen2 = 0;
        for (String[] rec : dataset2) {
            if (rec != null && rec.length > maxLen2) {
                maxLen2 = rec.length;
            }
        }

        // Filter out records with out‑of‑bounds key indices
        List<String[]> validDataset1 = filterValidRecords(dataset1, keyIndices);
        List<String[]> validDataset2 = filterValidRecords(dataset2, keyIndices);

        List<String[]> matched = new ArrayList<>();
        List<String[]> unmatched1 = new ArrayList<>();
        List<String[]> unmatched2 = new ArrayList<>();

        // Create a mutable copy of dataset2 for removal of matched records
        List<String[]> remainingDataset2 = new ArrayList<>(validDataset2);

        for (String[] record1 : validDataset1) {
            String key1 = buildKey(record1, keyIndices);
            boolean foundMatch = false;

            Iterator<String[]> iter = remainingDataset2.iterator();
            while (iter.hasNext()) {
                String[] record2 = iter.next();
                String key2 = buildKey(record2, keyIndices);

                boolean match = false;
                switch (matchStrategy) {
                    case 1: // exact match
                        match = key1.equals(key2);
                        break;
                    case 2: // contains match (case‑sensitive)
                        match = key1.contains(key2) || key2.contains(key1);
                        break;
