        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }

    /**
     * Pads each record in the list to the specified target length with empty strings.
     */
    private void padRecords(List<String[]> records, int targetLength) {
        for (int i = 0; i < records.size(); i++) {
            String[] rec = records.get(i);
            if (rec.length < targetLength) {
                String[] padded = new String[targetLength];
                System.arraycopy(rec, 0, padded, 0, rec.length);
                // Remaining positions are already null; replace with empty string
                for (int j = rec.length; j < targetLength; j++) {
