import java.util.List;
import java.util.ArrayList;

public class PaginationManager {

    /**
     * Calculates pagination details based on total items, page size, and current page.
     *
     * @param totalItems  the total number of items (must be non‑negative)
     * @param pageSize    the number of items per page (must be > 0)
     * @param currentPage the requested page number (1‑based, must be > 0)
     * @return a PaginationResult containing all pagination information
     * @throws IllegalArgumentException if any argument is invalid
     */
    public PaginationResult calculatePagination(int totalItems, int pageSize, int currentPage) {
        if (totalItems < 0) {
            throw new IllegalArgumentException("totalItems must be non‑negative");
        }
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be greater than 0");
        }
        if (currentPage <= 0) {
            throw new IllegalArgumentException("currentPage must be greater than 0");
        }

        // Compute total number of pages
        int totalPages = (totalItems == 0) ? 0 : (int) Math.ceil((double) totalItems / pageSize);

        // Cap currentPage at totalPages if it exceeds
        int current = currentPage;
        if (totalPages == 0) {
            current = 0;
        } else if (current > totalPages) {
            current = totalPages;
        }

        // Determine start and end item indices (1‑based)
        int startItem = 0;
        int endItem = 0;
        if (totalItems > 0 && current > 0) {
            startItem = (current - 1) * pageSize + 1;
            endItem = Math.min(startItem + pageSize - 1, totalItems);
        }

        // Build list of visible page numbers
        List<Integer> visiblePages = calculateVisiblePages(totalPages, current);

        return new PaginationResult(
                totalItems,
                pageSize,
                current,
                totalPages,
                startItem,
                endItem,
                visiblePages
        );
    }

    /**
     * Builds a list of visible page numbers according to the following rules:
     * <ul>
     *   <li>Show only 2 pages before and after the current page.</li>
     *   <li>Always include the first and last pages when appropriate.</li>
     *   <li>Use -1 to represent ellipses when pages are skipped.</li>
     *   <li>Do not show consecutive ellipses.</li>
     *   <li>Only include ellipses when there is a gap between the first/last pages and the current page range.</li>
     * </ul>
     *
     * @param totalPages the total number of pages
     * @param current    the current page (1‑based, may be 0 if totalPages is 0)
     * @return a list of page numbers and -1 for ellipses
     */
    private List<Integer> calculateVisiblePages(int totalPages, int current) {
        List<Integer> visible = new ArrayList<>();
        if (totalPages == 0) {
            return visible;
        }

        int startRange = Math.max(1, current - 2);
        int endRange = Math.min(totalPages, current + 2);

        // Add first page
        visible.add(1);

        // Ellipsis after first page if needed
        if (startRange > 2) {
            visible.add(-1);
        }

        // Add range pages (excluding first and last to avoid duplicates)
        for (int i = startRange; i <= endRange; i++) {
            if (i != 1 && i != totalPages) {
                visible.add(i);
            }
        }

        // Ellipsis before last page if needed
        if (endRange < totalPages - 1) {
            visible.add(-1);
        }

        // Add last page if there is more than one page
        if (totalPages > 1) {
            visible.add(totalPages);
        }

        return visible;
    }
}

