    /* ------------------------------------------------------------------ */
    public TreeNode deleteNode(TreeNode root, int key) {
        if (root == null) return null;

        if (key < root.val) {
            root.left = deleteNode(root.left, key);
        } else if (key > root.val) {
            root.right = deleteNode(root.right, key);
        } else { // Found the node to delete
            // Case 1: No child or only one child
            if (root.left == null) return root.right;
            if (root.right == null) return root.left;

            // Case 2: Two children
            TreeNode successor = minValueNode(root.right);
            root.val = successor.val;
            root.right = deleteNode(root.right, successor.val);
        }
        return root;
    }

    /* ------------------------------------------------------------------ */
    /*  Helper to find the node with the minimum value in a subtree      */
    /* ------------------------------------------------------------------ */
    private TreeNode minValueNode(TreeNode node) {
        while (node.left != null) {
            node = node.left;
        }
        return node;
    }

    /* ------------------------------------------------------------------ */
    /*  New helper requested by the problem statement                     */
    /* ------------------------------------------------------------------ */
    private int minValue(TreeNode root) {
        TreeNode current = root;
        while (current.left != null) {
            current = current.left;
        }
        return current.val;
    }

    /* ------------------------------------------------------------------ */
    /*  Level‑order traversal (BFS) with null placeholders                */
    /* ------------------------------------------------------------------ */
    public String levelOrder(TreeNode root) {
        if (root == null) return "[]";

        Queue<TreeNode> queue = new LinkedList<>();
        List<String> result = new ArrayList<>();

        queue.add(root);
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node != null) {
                result.add(String.valueOf(node.val));
                queue.add(node.left);
                queue.add(node.right);
            } else {
                result.add("null");
            }
        }

        // Remove trailing "null" entries
        int i = result.size() - 1;
        while (i >= 0 && result.get(i).equals("null")) {
            i--;
        }
        result = result.subList(0, i + 1);

        return "[" + String.join(",", result) + "]";
    }
}

