    //     PathFinder finder = new PathFinder();
    //     int[][] grid = new int[3][3]; // 3x3 grid
    //     PathResult result = finder.findUniquePathsWithAnalysis(grid);
    //     System.out.println(result); // Should print 6
    // }
}

