 * to the bottom-right corner of a rectangular grid, where movement is
 * restricted to right or down steps. The grid may contain obstacles
 * (cells with value 1). The class also provides detailed analysis of
 * the paths, including the total number of paths, the maximum and
 * minimum path lengths, and a sample path expressed as a list of
 * coordinates.
 */
public class PathFinder {

    /**
     * Inner class that holds detailed analysis of the paths.
     */
    public static class PathAnalysis {
        public final long totalPaths;
        public final int maxPathLength;
        public final int minPathLength;
        public final List<String> samplePath;

        public PathAnalysis(long totalPaths, int maxPathLength, int minPathLength,
                            List<String> samplePath) {
            this.totalPaths = totalPaths;
            this.maxPathLength = maxPathLength;
            this.minPathLength = minPathLength;
            this.samplePath = new ArrayList<>(samplePath);
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append("Total Paths: ").append(totalPaths).append('\n');
            sb.append("Max Path Length: ").append(maxPathLength).append('\n');
            sb.append("Min Path Length: ").append(minPathLength).append('\n');
            sb.append("Sample Path: ").append(samplePath);
            return sb.toString();
        }
    }

    /**
     * Computes the unique path analysis for the given grid, taking obstacles
     * into account. A value of 1 in the grid represents an obstacle that
     * cannot be traversed.
     *
     * @param grid a 2D integer array representing the grid (dimensions m x n)
     * @return a PathAnalysis object containing total paths, path lengths,
     *         and a sample path expressed as coordinates
     */
    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, Collections.emptyList());
        }

        int m = grid.length;        // number of rows
        int n = grid[0].length;     // number of columns

        // DP table for counting paths; dp[i][j] = number of ways to reach (i,j)
        long[][] dp = new long[m][n];

        // Starting cell
        if (grid[0][0] == 0) {
            dp[0][0] = 1;
        } else {
            dp[0][0] = 0; // obstacle at start -> no paths
        }

        // First row
        for (int j = 1; j < n; j++) {
            if (grid[0][j] == 0) {
                dp[0][j] = dp[0][j - 1];
            } else {
                dp[0][j] = 0; // obstacle blocks the row
            }
        }

        // First column
        for (int i = 1; i < m; i++) {
            if (grid[i][0] == 0) {
                dp[i][0] = dp[i - 1][0];
            } else {
                dp[i][0] = 0; // obstacle blocks the column
            }
        }

        // Remaining cells
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (grid[i][j] == 0) {
                    dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
                } else {
                    dp[i][j] = 0; // obstacle
                }
            }
        }

        long totalPaths = dp[m - 1][n - 1];
        if (totalPaths == 0) {
            // No valid path exists
            return new PathAnalysis(0, 0, 0, Collections.emptyList());
        }

        // Reconstruct a sample path by backtracking from the destination
        List<String> samplePath = new ArrayList<>();
        int i = m - 1;
        int j = n - 1;
        while (!(i == 0 && j == 0)) {
            samplePath.add("(" + i + "," + j + ")");
            // Prefer moving up if a path exists; otherwise move left
            if (i > 0 && dp[i - 1][j] > 0) {
                i--;
            } else if (j > 0 && dp[i][j - 1] > 0) {
                j--;
            } else {
                // This should not happen because dp guarantees a path
                break;
            }
        }
        samplePath.add("(0,0)");
        Collections.reverse(samplePath);

        int pathLength = samplePath.size() - 1; // number of steps
        // For grids without obstacles, pathLength equals (m-1)+(n-1).
        // With obstacles, the path may be longer; we report the actual length.
        return new PathAnalysis(totalPaths, pathLength, pathLength, samplePath);
    }

    // Example usage (uncomment to test)
    // public static void main(String[] args) {
