import java.util.regex.Pattern;

public class EmployeeValidator {

    // Regex for a standard email format
    private static final Pattern EMAIL_PATTERN =
            Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$");

    /**
     * Validates the employee data.
     *
     * @param email    the employee's email address
     * @param password the employee's password
     * @param fcmToken the employee's FCM token
     * @throws IllegalArgumentException if any validation rule is violated
     */
    public static void validateEmployee(String email, String password, String fcmToken) {
        // 1. Null or empty checks
        if (email == null || email.isEmpty()
                || password == null || password.isEmpty()
                || fcmToken == null || fcmToken.isEmpty()) {
            throw new IllegalArgumentException("Invalid employee data");
        }

        // 2. Email length check
        if (email.length() > 30) {
            throw new IllegalArgumentException("Email must be 30 characters or less");
        }

        // 3. Email format check
        if (!EMAIL_PATTERN.matcher(email).matches()) {
            throw new IllegalArgumentException("Invalid email format");
        }

        // 4. Password length checks
        if (password.length() < 8) {
            throw new IllegalArgumentException("Password must be at least 8 characters long");
        }
        if (password.length() > 255) {
            throw new IllegalArgumentException("Password must be at most 255 characters long");
        }

        // 5. Password composition checks
        if (!password.matches(".*[A-Z].*")) {
            throw new IllegalArgumentException("Password must contain at least one uppercase letter");
        }
        if (!password.matches(".*[a-z].*")) {
            throw new IllegalArgumentException("Password must contain at least one lowercase letter");
        }
        if (!password.matches(".*\\d.*")) {
            throw new IllegalArgumentException("Password must contain at least one digit");
        }
        if (!password.matches(".*[!@#$%^&*()].*")) {
            throw new IllegalArgumentException("Password must contain at least one special character (!@#$%^&*())");
        }
    }
}

