import java.util.*;

class AdvancedFlagProcessor {
    private final Set<String> validFlags;

    public AdvancedFlagProcessor(Set<String> validFlags) {
        this.validFlags = new HashSet<>(validFlags);
    }

    public Set<String> processFlags(String flagString) {
        Set<String> result = new HashSet<>();

        // Handle null or empty input
        if (flagString == null || flagString.trim().isEmpty()) {
            for (String flag : validFlags) {
                result.add("|" + flag);
            }
            return result;
        }

        // Normalize base string: trim whitespace
        String base = flagString.trim();

        // Remove trailing '|' if present
        if (base.endsWith("|")) {
            base = base.substring(0, base.length() - 1);
        }

        // Parse existing flags
        Set<String> existing = new HashSet<>();
        String[] tokens = base.split("\\|");
        for (String token : tokens) {
            String trimmed = token.trim();
            if (!trimmed.isEmpty() && validFlags.contains(trimmed)) {
                existing.add(trimmed);
            }
        }

        // Generate new combinations by adding one more valid flag
        for (String flag : validFlags) {
            if (!existing.contains(flag)) {
                String newCombination;
                if (base.isEmpty()) {
                    newCombination = "|" + flag;
                } else {
                    newCombination = base + "|" + flag;
                }
                result.add(newCombination);
            }
        }

        return result;
    }
}

