import java.util.ArrayList;
import java.util.List;

class SubsetGenerator {
    public List<List<Integer>> generateSubsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> lastIndex = new ArrayList<>();

        // Start with the empty subset
        result.add(new ArrayList<>());
        lastIndex.add(-1); // indicates no element used

        for (int i = 0; i < nums.length; i++) {
            int currentSize = result.size(); // subsets before adding new ones

            // Create new subsets by appending nums[i] to each previous subset
            // that ends before position i
            for (int j = 0; j < currentSize; j++) {
                if (lastIndex.get(j) < i) {
                    List<Integer> newSubset = new ArrayList<>(result.get(j));
                    newSubset.add(nums[i]);
                    result.add(newSubset);
                    lastIndex.add(i);
                }
            }

            // Add the single‑element subset [nums[i]]
            List<Integer> single = new ArrayList<>();
            single.add(nums[i]);
            result.add(single);
            lastIndex.add(i);
        }

        return result;
    }
}

