import java.util.*;

class GraphAnalyzer {
    private Map<String, List<Edge>> adjacencyList;
    private boolean directed;
    private boolean weighted;

    public GraphAnalyzer(boolean directed, boolean weighted) {
        this.directed = directed;
        this.weighted = weighted;
        this.adjacencyList = new HashMap<>();
    }

    public void addNode(String node) {
        adjacencyList.putIfAbsent(node, new ArrayList<>());
    }

    public void addEdge(String from, String to, int weight) {
        // If the graph is unweighted, ignore the provided weight and use 1
        if (!weighted) {
            weight = 1;
        }

        // Ensure both nodes exist in the graph
        addNode(from);
        addNode(to);

        // Add edge from 'from' to 'to'
        adjacencyList.get(from).add(new Edge(to, weight));

        // For undirected graphs, add the reverse edge as well
        if (!directed) {
            adjacencyList.get(to).add(new Edge(from, weight));
        }
    }

    // Optional: method to retrieve adjacency list for external use
    public Map<String, List<Edge>> getAdjacencyList() {
        return adjacencyList;
    }

    // Optional: pretty print the graph
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, List<Edge>> entry : adjacencyList.entrySet()) {
            sb.append(entry.getKey()).append(" -> ");
            List<Edge> edges = entry.getValue();
            for (int i = 0; i < edges.size(); i++) {
                Edge e = edges.get(i);
                sb.append(e.destination);
                if (weighted) {
                    sb.append(" (").append(e.weight).append(")");
                }
                if (i < edges.size() - 1) sb.append(", ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }

    static class Edge {
        private final String destination;
        private final int weight;

        public Edge(String destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }

        public String getDestination() {
            return destination;
        }

        public int getWeight() {
            return weight;
        }
    }
}

