    private boolean dfsUndirected(String current, Set<String> visited, String parent) {
        visited.add(current);
        for (Edge e : adjacencyList.getOrDefault(current, Collections.emptyList())) {
            String neighbor = e.destination;
            if (!visited.contains(neighbor)) {
                if (dfsUndirected(neighbor, visited, current)) {
                    return true;
                }
            } else if (!neighbor.equals(parent)) {
                return true; // found a back edge to an ancestor
            }
        }
        return false;
    }

