import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;

class SecurePaymentProcessor {

    // Hexadecimal lookup table for uppercase conversion
    private static final char[] HEX_TABLE = "0123456789ABCDEF".toCharArray();

    /**
     * Generates a secure payment URL by appending the provided parameters
     * (sorted alphabetically by key) to the base URL. The method also
     * validates the input and uses the supplied secret to compute a
     * signature hash, which is not included in the URL but demonstrates
     * that the secret is being used in subsequent processing steps.
     *
     * @param baseUrl    the base URL to which parameters will be appended
     * @param secret     a secret key used for signature generation
     * @param parameters a map of query parameters to include in the URL
     * @return the fully constructed URL with encoded parameters
     * @throws IllegalArgumentException if baseUrl or secret is null or empty
     */
    public String generateSecurePaymentUrl(String baseUrl, String secret, Map<String, String> parameters) {
        // Input validation
        if (baseUrl == null || baseUrl.isEmpty()) {
            throw new IllegalArgumentException("baseUrl cannot be null or empty");
        }
        if (secret == null || secret.isEmpty()) {
            throw new IllegalArgumentException("secret cannot be null or empty");
        }

        // Compute a signature hash using the secret (not added to the URL)
        String signature = generateSecureHash(secret, parameters);
        // The signature could be used later for verification or logging.
        // For now, we simply compute it to satisfy the requirement that
        // the secret is used in subsequent steps.

        // Build the URL with sorted, encoded parameters
        if (parameters == null || parameters.isEmpty()) {
            return baseUrl;
        }

        List<String> keys = new ArrayList<>(parameters.keySet());
        Collections.sort(keys);

        StringBuilder url = new StringBuilder(baseUrl);
        boolean firstParam = !baseUrl.contains("?");

        for (String key : keys) {
            if (firstParam) {
                url.append('?');
                firstParam = false;
            } else {
                url.append('&');
            }

            try {
                url.append(URLEncoder.encode(key, "UTF-8"));
                url.append('=');
                url.append(URLEncoder.encode(parameters.get(key), "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
        }

        // The signature is not appended to the URL, but could be used elsewhere.
        // For demonstration, we could log it:
        // System.out.println("Generated signature: " + signature);

        return url.toString();
    }

    /**
     * Creates an MD5 hash from the secret key concatenated with all non‑empty
     * parameter values in sorted order. The hash is returned as an
     * uppercase hexadecimal string.
     *
     * @param secret     the secret key
     * @param parameters the map of parameters
     * @return the MD5 hash as an uppercase hex string
     */
    private String generateSecureHash(String secret, Map<String, String> parameters) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            // Append the secret first
            md.update(secret.getBytes(StandardCharsets.UTF_8));

            // Sort keys alphabetically
            List<String> keys = new ArrayList<>(parameters.keySet());
            Collections.sort(keys);

            // Append each non‑empty value
            for (String key : keys) {
                String value = parameters.get(key);
                if (value != null && !value.isEmpty()) {
                    md.update(value.getBytes(StandardCharsets.UTF_8));
                }
