import java.util.*;
import java.net.URLEncoder;
import java.io.UnsupportedEncodingException;
import java.security.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;

class SecurePaymentProcessor {

    /**
     * Generates a secure payment URL by appending the provided parameters
     * (sorted alphabetically by key) to the base URL. The method also
     * validates the input and uses the supplied secret to compute a
     * HMAC‑SHA256 hash over the sorted query string. The hash is added
     * as a parameter named {@code vpc_SecureHash}. Parameters with
     * {@code null} or empty values are omitted from both the hash
     * calculation and the final URL.
     *
     * @param baseUrl the base URL to which parameters will be appended
     * @param params  a map of request parameters (excluding the hash)
     * @param secret  the secret key used for HMAC‑SHA256 hash generation
     * @return the fully constructed URL with encoded parameters
     * @throws IllegalArgumentException if the secret is {@code null} or empty
     * @throws RuntimeException         if hash computation fails
     */
    public String generateSecurePaymentUrl(String baseUrl,
                                           Map<String, String> params,
                                           String secret) {
        // Validate secret
        if (secret == null || secret.isEmpty()) {
            throw new IllegalArgumentException("Secret key must not be null or empty");
        }

        // Filter out null or empty values and sort parameters alphabetically
        TreeMap<String, String> sortedParams = new TreeMap<>();
        if (params != null) {
            for (Map.Entry<String, String> entry : params.entrySet()) {
                String value = entry.getValue();
                if (value != null && !value.isEmpty()) {
                    sortedParams.put(entry.getKey(), value);
                }
            }
        }

        // Build the query string for hash calculation (not URL‑encoded)
        StringBuilder queryString = new StringBuilder();
        for (Map.Entry<String, String> entry : sortedParams.entrySet()) {
            if (queryString.length() > 0) {
                queryString.append('&');
            }
            queryString.append(entry.getKey()).append('=').append(entry.getValue());
        }

        // Compute HMAC‑SHA256 hash
        String hashHex;
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(keySpec);
            byte[] hashBytes = mac.doFinal(queryString.toString().getBytes(StandardCharsets.UTF_8));
            hashHex = bytesToHex(hashBytes);
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate secure hash: " + e.getMessage(), e);
        }

        // Add the hash to the parameters
        sortedParams.put("vpc_SecureHash", hashHex);

        // Build the final URL with URL‑encoded parameters
        StringBuilder finalUrl = new StringBuilder(baseUrl);
        boolean firstParam = !baseUrl.contains("?");

        for (Map.Entry<String, String> entry : sortedParams.entrySet()) {
            if (firstParam) {
                finalUrl.append('?');
                firstParam = false;
            } else {
                finalUrl.append('&');
            }
            try {
                finalUrl.append(URLEncoder.encode(entry.getKey(), "UTF-8"))
                        .append('=')
                        .append(URLEncoder.encode(entry.getValue(), "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                // UTF‑8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException("Failed to encode URL parameter: " + e.getMessage(), e);
            }
        }

        return finalUrl.toString();
    }

    /**
     * Converts a byte array to an uppercase hexadecimal string.
     *
     * @param bytes the byte array to convert
     * @return the resulting hexadecimal string
     */
    private String bytesToHex(byte[] bytes) {
        char[] hexArray = "0123456789ABCDEF".toCharArray();
        char[] hexChars = new char[bytes.length * 2];
        for (int j = 0; j < bytes.length; j++) {
            int v = bytes[j] & 0xFF;
            hexChars[j * 2] = hexArray[v >>> 4];
