import java.util.ArrayList;
import java.util.Collections;

class PatternGenerator {
    public static List<String> generateSandClock(int size, boolean reverse, boolean useLetters) {
        if (size <= 0) {
            throw new IllegalArgumentException("Size must be positive");
        }

        List<String> pattern = new ArrayList<>();

        // Build the upper half (including the middle line)
        for (int i = 1; i <= size; i++) {
            pattern.add(buildLine(i, size, useLetters));
        }

        // Build the lower half (excluding the middle line)
        for (int i = size - 1; i >= 1; i--) {
            pattern.add(buildLine(i, size, useLetters));
        }

        if (reverse) {
            Collections.reverse(pattern);
        }

        return pattern;
    }

    private static String buildLine(int lineNumber, int size, boolean useLetters) {
        int count = size - lineNumber + 1; // number of symbols in this line
        StringBuilder sb = new StringBuilder();

        char symbol;
        if (useLetters) {
            symbol = (char) ('A' + lineNumber - 1);
        } else {
            symbol = '*';
        }

        for (int i = 0; i < count; i++) {
            sb.append(symbol);
            if (i < count - 1) {
                sb.append(' ');
            }
        }

        return sb.toString();
    }
}

