import org.json.JSONObject;

class AdvancedNotificationHandler {

    public static JSONObject generateSecureNotification(
            String title,
            String body,
            String encryptedData,
            boolean useBiometric,
            String signature,
            String registrationKey,
            String priority,
            long ttl,
            String collapseKey) {

        try {
            // Root payload
            JSONObject payload = new JSONObject();
            payload.put("to", registrationKey);

            // Optional collapse key
            if (collapseKey != null && !collapseKey.isEmpty()) {
                payload.put("collapse_key", collapseKey);
            }

            // Data section (contains title, body and optional secure fields)
            JSONObject data = new JSONObject();
            data.put("title", title);
            data.put("body", body);
            // Include secure fields if provided
            if (encryptedData != null) {
                data.put("encryptedData", encryptedData);
            }
            data.put("useBiometric", useBiometric);
            if (signature != null) {
                data.put("signature", signature);
            }
            payload.put("data", data);

            // Notification section (title and body)
            JSONObject notification = new JSONObject();
            notification.put("title", title);
            notification.put("body", body);
            payload.put("notification", notification);

            // Android configuration
            JSONObject android = new JSONObject();
            android.put("ttl", ttl + "s");   // TTL in seconds
            android.put("priority", priority);
            payload.put("android", android);

            return payload;
        } catch (Exception e) {
            // Wrap any JSON exception into a runtime exception
            throw new RuntimeException("Failed to build notification payload", e);
        }
    }
}

