     * Retrieves a bean by its name and casts it to the desired type.
     *
     * @param name the name of the bean to retrieve
     * @param <T>  the expected type of the bean
     * @return the bean instance cast to type T, or null if no bean is registered under that name
     * @throws ClassCastException if the bean cannot be cast to the requested type
     */
    @SuppressWarnings("unchecked")
    public <T> T getBean(String name, Class<T> type) {
        Object bean = beanRegistry.get(name);
        if (bean == null) {
            return null;
        }
        return (T) bean;
    }
}
