     *   <li>If {@code allowedRoles} is empty, access is granted by default
     *       (unless a disallowed role was found above).</li>
     *   <li>Otherwise, access is granted only if the user has at least one
     *       role in {@code allowedRoles}.</li>
     * </ul>
     */
    public boolean isAccessAllowed(Set<String> userRoles) {
        // Deny immediately if any disallowed role is present
        for (String role : disallowedRoles) {
            if (userRoles.contains(role)) {
                return false;
            }
        }

        // If no allowed roles are specified, grant access by default
        if (allowedRoles.isEmpty()) {
            return true;
        }

        // Grant access if any allowed role is present
        for (String role : allowedRoles) {
            if (userRoles.contains(role)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Sets the list of allowed roles from a comma‑separated string.
     * In strict mode, all roles must be valid; otherwise an exception is thrown.
     */
    public void setAllowedRoles(String roles) {
        List<String> list = stringToList(roles);
