import java.util.List;
import java.util.Map;

public class DataProcessor {

    /**
     * Processes a list of items according to the provided configuration.
     *
     * @param items  List of items, each represented as a Map<String, String>.
     * @param config Configuration map that may contain the key "mergeFields" with a Boolean value.
     * @return A map containing the processed items and various statistics.
     */
    public Map<String, Object> processData(List<Map<String, String>> items, Map<String, Object> config) {
        List<Map<String, String>> processedItems = new ArrayList<>();
        int transformedCount = 0;

        boolean mergeFields = Boolean.TRUE.equals(config.get("mergeFields"));

        for (Map<String, String> item : items) {
            // Create a copy to avoid mutating the original map
            Map<String, String> processedItem = new HashMap<>(item);

            if (mergeFields && processedItem.containsKey("code") && processedItem.containsKey("name")) {
                String code = processedItem.get("code");
                String name = processedItem.get("name");
                processedItem.put("merged", code + " - " + name);
                transformedCount++;
            }

            processedItems.add(processedItem);
        }

        Map<String, Object> result = new HashMap<>();
        result.put("processedItems", processedItems);
        result.put("totalItems", items.size());
        result.put("emptyFieldCount", 0);
        result.put("transformedCount", transformedCount);
        result.put("specialCaseCount", 0);

        return result;
    }
}

