        int transformedCount = 0;
        int emptyFieldCount = 0;

        boolean mergeFields = Boolean.TRUE.equals(config.get("mergeFields"));
        boolean countEmpty = Boolean.TRUE.equals(config.get("countEmpty"));

        // Separator for merging
        String separator = " - ";
        Object sepObj = config.get("mergeSeparator");
        if (sepObj instanceof String) {
            separator = (String) sepObj;
        }

        // Max length for merged value
        int maxLength = -1; // -1 means no limit
        Object maxObj = config.get("maxLength");
        if (maxObj instanceof Integer) {
            maxLength = (Integer) maxObj;
        }

        for (Map<String, String> item : items) {
            // Create a copy to avoid mutating the original map
            Map<String, String> processedItem = new HashMap<>(item);

            // Count empty or null fields if requested
