public class PermissionValidator {
    /**
     * Checks if the request URI and method match any permission in the list.
     * Supports the {@code {*}} wildcard in permission URIs, which matches exactly
     * one non‑empty alphanumeric segment, and prefix matching when the permission
     * URI is a full prefix followed by a segment boundary.
     *
     * @param permissions   list of permissions to validate against (may be null or empty)
     * @param requestUri    the request URI to check
     * @param requestMethod the request HTTP method to check
     * @return true if any permission matches the URI and method (method comparison is case‑insensitive),
     *         false otherwise or if the list is null/empty
     */
    public boolean hasPermission(List<PermissionInfo> permissions, String requestUri, String requestMethod) {
        if (permissions == null || permissions.isEmpty() || requestUri == null || requestMethod == null) {
            return false;
        }

        for (PermissionInfo permission : permissions) {
            if (permission == null) {
                continue;
            }

            String permUri = permission.getUri();
            String permMethod = permission.getMethod();

            if (permUri == null || permMethod == null) {
                continue;
            }

            // Method must match case‑insensitively
            if (!permMethod.equalsIgnoreCase(requestMethod)) {
                continue;
            }

            // 1. Exact match with wildcard support
            if (matchesWithWildcard(permUri, requestUri)) {
                return true;
            }

            // 2. Prefix match (only if no wildcard present)
            if (!permUri.contains("{*}") && isPrefixMatch(permUri, requestUri)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Checks if the permission URI matches the request URI exactly,
     * supporting the {@code {*}} wildcard which matches exactly one
     * non‑empty alphanumeric segment.
     */
    private boolean matchesWithWildcard(String permUri, String requestUri) {
        String[] permSegments = permUri.split("/", -1);
        String[] reqSegments = requestUri.split("/", -1);

        if (permSegments.length != reqSegments.length) {
            return false;
        }

        for (int i = 0; i < permSegments.length; i++) {
            String permSeg = permSegments[i];
            String reqSeg = reqSegments[i];

            if ("{*}".equals(permSeg)) {
                if (reqSeg == null || reqSeg.isEmpty() || !reqSeg.matches("[A-Za-z0-9]+")) {
                    return false;
                }
            } else {
                if (!permSeg.equals(reqSeg)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the permission URI is a full prefix of the request URI
     * followed by a segment boundary (i.e., the next character is '/').
     * Prefix matching is only considered when the permission URI does not
     * contain a wildcard.
     */
    private boolean isPrefixMatch(String permUri, String requestUri) {
        if (!requestUri.startsWith(permUri)) {
            return false;
        }
        if (requestUri.length() == permUri.length()) {
            // Exact match already handled; do not grant prefix match
            return false;
        }
        // Ensure the next character is a '/' to respect segment boundary
        return requestUri.charAt(permUri.length()) == '/';
    }
}

