    }

    /* ----------------- Routing rules ----------------- */
    public void addRoutingRule(String pattern, String handlerKey) {
        if (pattern == null || handlerKey == null) {
            throw new IllegalArgumentException("Pattern and handlerKey must not be null");
        }
        String[] segments = parseSegments(pattern);
        routingRules.add(new RoutingRule(segments, handlerKey));
    }

    public String findHandlerKey(String path) {
        if (path == null) {
            return null;
        }
        String[] pathSegments = parseSegments(path);
        for (RoutingRule rule : routingRules) {
            if (match(rule.patternSegments, 0, pathSegments, 0)) {
                return rule.handlerKey;
            }
        }
        return null;
    }

    /* ----------------- Queue-based processing ----------------- */
    public void enqueueMessage(String messageId, String messageType, String content) {
        String formatted = String.join("|", messageId, messageType, content);
        messageQueue.offer(formatted);
    }

    public Map<String, String> processQueue() {
        Map<String, String> results = new LinkedHashMap<>();
        while (!messageQueue.isEmpty()) {
            String msg = messageQueue.poll();
            String[] parts = msg.split("\\|", 3);
            String messageId = parts.length > 0 ? parts[0] : null;
            String messageType = parts.length > 1 ? parts[1] : null;
            String content = parts.length > 2 ? parts[2] : null;
            String result = processMessage(messageId, messageType, content);
            results.put(messageId, result);
        }
        return results;
    }

    /* ----------------- Helper methods ----------------- */
    private String[] parseSegments(String s) {
        if (s.isEmpty()) {
            return new String[0];
        }
        String[] raw = s.split("/");
        List<String> segs = new ArrayList<>();
        for (String seg : raw) {
            if (!seg.isEmpty()) {
                segs.add(seg);
            }
        }
        return segs.toArray(new String[0]);
    }

    private boolean match(String[] pattern, int pi, String[] path, int si) {
        if (pi == pattern.length) {
            return si == path.length;
        }
        if (si > path.length) {
            return false;
        }

        if (pattern[pi].equals("#")) {
            // '#' must match at least one segment
            for (int k = si + 1; k <= path.length; k++) {
                if (match(pattern, pi + 1, path, k)) {
                    return true;
                }
            }
            return false;
        } else {
            if (si >= path.length) {
                return false;
            }
            if (pattern[pi].contains("*")) {
                if (!segmentMatches(pattern[pi], path[si])) {
                    return false;
                }
            } else {
                if (!pattern[pi].equals(path[si])) {
                    return false;
                }
            }
            return match(pattern, pi + 1, path, si + 1);
        }
    }

    /**
     * Matches a single path segment against a pattern segment that may contain '*'.
     * '*' matches any sequence of non-dot characters (including the empty sequence).
     */
    private boolean segmentMatches(String patternSeg, String pathSeg) {
        String regex = patternSeg.replace(".", "\\\\.").replace("*", "[^.]*");
        return pathSeg.matches(regex);
    }

    /* ----------------- Routing rule container ----------------- */
    private static class RoutingRule {
        final String[] patternSegments;
        final String handlerKey;

        RoutingRule(String[] patternSegments, String handlerKey) {
            this.patternSegments = patternSegments;
            this.handlerKey = handlerKey;
        }
    }
}
