import java.util.*;

public class BracketValidator {

    /**
     * Validates whether the brackets in the input string are balanced.
     * The result map contains:
     * - "balanced"   : Boolean indicating if brackets are balanced.
     * - "errorPosition" : Index of the first error (mismatch or unclosed), -1 if none.
     * - "errorType"  : "mismatch", "unclosed", or empty string if balanced.
     *
     * @param input the string to validate
     * @return a map with the validation results
     */
    public static Map<String, Object> validateBrackets(String input) {
        Map<String, Object> result = new HashMap<>();

        if (input == null) {
            result.put("balanced", false);
            result.put("errorPosition", -1);
            result.put("errorType", "");
            return result;
        }

        Deque<BracketInfo> stack = new ArrayDeque<>();

        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            switch (ch) {
                case '(':
                case '[':
                case '{':
                    stack.push(new BracketInfo(ch, i));
                    break;

                case ')':
                case ']':
                case '}':
                    if (stack.isEmpty()) {
                        result.put("balanced", false);
                        result.put("errorPosition", i);
                        result.put("errorType", "mismatch");
                        return result;
                    }
                    BracketInfo top = stack.pop();
                    if (!matches(top.bracket, ch)) {
                        result.put("balanced", false);
                        result.put("errorPosition", i);
                        result.put("errorType", "mismatch");
                        return result;
                    }
                    break;

                default:
                    // Ignore non-bracket characters
                    break;
            }
        }

        if (!stack.isEmpty()) {
            // Unclosed opening brackets remain
            Iterator<BracketInfo> it = stack.iterator();
            BracketInfo firstUnclosed = null;
            while (it.hasNext()) {
                firstUnclosed = it.next(); // last element visited is the oldest unmatched
            }
            result.put("balanced", false);
            result.put("errorPosition", firstUnclosed.index);
            result.put("errorType", "unclosed");
            return result;
        }

        // All brackets matched correctly
        result.put("balanced", true);
        result.put("errorPosition", -1);
        result.put("errorType", "");
        return result;
    }

    /**
     * Checks if an opening bracket matches a closing bracket.
     */
    private static boolean matches(char open, char close) {
        return (open == '(' && close == ')')
                || (open == '[' && close == ']')
                || (open == '{' && close == '}');
    }

    /**
     * Helper class to store bracket character and its position.
     */
    private static class BracketInfo {
        final char bracket;
        final int index;

        BracketInfo(char bracket, int index) {
            this.bracket = bracket;
            this.index = index;
        }
    }
}

