class LinkedListNode {
    int data;
    LinkedListNode next;
    LinkedListNode(int data) { this.data = data; }
}

class LinkedListSwapper {

    // Swaps the first two nodes of the list (positions 0 and 1)
    static LinkedListNode swapNodes(LinkedListNode head) {
        if (head == null || head.next == null) return head; // no swap needed
        LinkedListNode second = head.next;
        head.next = second.next;
        second.next = head;
        return second; // new head after swap
    }

    // Creates a linked list from a List<Integer>
    static LinkedListNode createLinkedList(List<Integer> values) {
        if (values.isEmpty()) return null;
        LinkedListNode head = new LinkedListNode(values.get(0));
        LinkedListNode current = head;
        for (int i = 1; i < values.size(); i++) {
            current.next = new LinkedListNode(values.get(i));
            current = current.next;
        }
        return head;
    }

    // Converts a linked list back to a List<Integer>
    static List<Integer> linkedListToList(LinkedListNode head) {
        List<Integer> result = new ArrayList<>();
        LinkedListNode current = head;
        while (current != null) {
            result.add(current.data);
            current = current.next;
        }
        return result;
    }
}

