import java.util.*;

class LinkedListNode {
    int data;
    LinkedListNode next;
    LinkedListNode(int data) { this.data = data; }
}

class LinkedListSwapper {

    /**
     * Swaps the nodes at positions i and j (0‑based) in a singly linked list.
     * Assumes i and j are valid, distinct indices and the list has enough nodes.
     *
     * @param head the original head of the list
     * @param i    first index
     * @param j    second index
     * @return the new head of the list after swapping
     */
    static LinkedListNode swapNodes(LinkedListNode head, int i, int j) {
        if (i == j) return head;          // nothing to do
        if (i > j) {                      // keep i < j for easier logic
            int temp = i; i = j; j = temp;
        }

        LinkedListNode prevI = null, nodeI = head;
        for (int idx = 0; idx < i; idx++) {
            prevI = nodeI;
            nodeI = nodeI.next;
        }

        LinkedListNode prevJ = null, nodeJ = head;
        for (int idx = 0; idx < j; idx++) {
            prevJ = nodeJ;
            nodeJ = nodeJ.next;
        }

        // Adjacent nodes (nodeI immediately before nodeJ)
        if (nodeI.next == nodeJ) {
            if (prevI != null) prevI.next = nodeJ;
            else head = nodeJ;

            nodeI.next = nodeJ.next;
            nodeJ.next = nodeI;
            return head;
        }

        // Non‑adjacent nodes
        if (prevI != null) prevI.next = nodeJ;
        else head = nodeJ;

        if (prevJ != null) prevJ.next = nodeI;
        else head = nodeI;

        // Swap next pointers
        LinkedListNode temp = nodeI.next;
        nodeI.next = nodeJ.next;
        nodeJ.next = temp;

        return head;
    }

    /**
     * Creates a singly linked list from a List of integers.
     *
     * @param values the list of integer values
     * @return the head of the created linked list
     */
    static LinkedListNode createLinkedList(List<Integer> values) {
        if (values.isEmpty()) return null;
        LinkedListNode head = new LinkedListNode(values.get(0));
        LinkedListNode current = head;
        for (int idx = 1; idx < values.size(); idx++) {
            current.next = new LinkedListNode(values.get(idx));
            current = current.next;
        }
        return head;
    }

    /**
     * Converts a singly linked list back into a List of integers.
     *
     * @param head the head of the linked list
     * @return a List containing the data from the linked list
     */
    static List<Integer> linkedListToList(LinkedListNode head) {
        List<Integer> result = new ArrayList<>();
        LinkedListNode current = head;
        while (current != null) {
            result.add(current.data);
            current = current.next;
        }
        return result;
    }
}

