import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class ThreadSynchronizer {
    private final ReentrantLock lock;
    private final Condition condition;
    private boolean isSignalled;

    public ThreadSynchronizer() {
        this.lock = new ReentrantLock();
        this.condition = lock.newCondition();
        this.isSignalled = false;
    }

    /**
     * Waits for the specified number of seconds. The wait does not take into account
     * any notifications or deadlines; it simply blocks for the given time or until
     * the thread is interrupted.
     *
     * @param waitSeconds the number of seconds to wait
     * @return true if the wait completed normally, false if the thread was interrupted
     */
    public boolean waitWithDeadline(int waitSeconds) {
        lock.lock();
        try {
            condition.await(waitSeconds, TimeUnit.SECONDS);
            return true;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } finally {
            lock.unlock();
        }
    }

    /**
     * Notifies all threads that are waiting on this synchronizer.
     */
    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
}

