public class ClassAnalyzer {

    /**
     * Analyzes the specified class and returns a report containing its fully qualified name,
     * public constructors, and all declared constructors.
     *
     * @param className the fully qualified name of the class to analyze
     * @return a string report with the class name and constructor information,
     *         or an error message if the class cannot be loaded
     */
    public static String analyzeClass(String className) {
        try {
            Class<?> clazz = Class.forName(className);
            StringBuilder report = new StringBuilder();

            // Class name
            report.append("Class: ").append(clazz.getName()).append("\n\n");

            // Public constructors
            Constructor<?>[] publicConstructors = clazz.getConstructors();
            report.append("Public Constructors:\n");
            if (publicConstructors.length == 0) {
                report.append("  None\n");
            } else {
                for (Constructor<?> ctor : publicConstructors) {
                    report.append("  ").append(ctor.toString()).append("\n");
                }
            }
            report.append("\n");

            // Declared constructors
            Constructor<?>[] declaredConstructors = clazz.getDeclaredConstructors();
            report.append("Declared Constructors:\n");
            if (declaredConstructors.length == 0) {
                report.append("  None\n");
            } else {
                for (Constructor<?> ctor : declaredConstructors) {
                    report.append("  ").append(ctor.toString()).append("\n");
                }
