            if (emailValid && passwordValid) {
                response.put("success", true);
                response.put("userEmail", email);
                response.put("authMethod", "email");
            } else {
                response.put("success", false);
                response.put("message", "Invalid email or password");
            }
            return response;
        }

        // 3. At this point, email and password are both null. Attempt Google token authentication.
        if (googleToken != null && googleToken.startsWith("google_")) {
            String localPart = googleToken.substring("google_".length());
            String userEmail = localPart + "@gmail.com";

            response.put("success", true);
            response.put("userEmail", userEmail);
            response.put("authMethod", "google");
        } else {
            response.put("success", false);
            response.put("message", "Google authentication failed");
        }

        return response;
    }
