import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import java.util.function.Function;
import java.util.concurrent.TimeoutException;

class AsyncOperationManager {

    // Shared scheduler for timeout tasks
    private static final ScheduledExecutorService scheduler =
            Executors.newScheduledThreadPool(1);

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return attempt(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, 0);
    }

    private <T> CompletableFuture<T> attempt(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries,
            int attempt) {

        // Run the task asynchronously
        CompletableFuture<T> taskFuture = CompletableFuture.supplyAsync(taskSupplier);

        // Future that will complete exceptionally on timeout
        CompletableFuture<T> timeoutFuture = new CompletableFuture<>();
        ScheduledFuture<?> timeoutHandle = scheduler.schedule(
                () -> timeoutFuture.completeExceptionally(new TimeoutException()),
                timeout,
                timeUnit);

        // Result will be whichever completes first: task or timeout
        CompletableFuture<T> resultFuture = taskFuture.applyToEither(timeoutFuture, Function.identity());

        // Cancel the timeout when the result is ready
        resultFuture.whenComplete((res, ex) -> timeoutHandle.cancel(true));

        // Handle completion, retrying if necessary
        return resultFuture.handle((res, ex) -> {
            if (ex == null) {
                // Successful completion
                return CompletableFuture.completedFuture(res);
            } else {
                // Failure: decide whether to retry
                if (attempt < maxRetries) {
                    try {
                        Thread.sleep(500); // 500 ms delay between retries
                    } catch (InterruptedException ie) {
                        return failedFuture(ie);
                    }
                    // Retry with incremented attempt count
                    return attempt(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, attempt + 1);
                } else {
                    // Max retries reached
                    if (ex instanceof TimeoutException) {
                        // Timeout after all retries: return fallback
                        return CompletableFuture.completedFuture(fallbackValue);
                    } else {
                        // Other exception: propagate it
                        return failedFuture(ex);
                    }
                }
            }
        }).thenCompose(Function.identity());
    }

    // Helper to create a CompletableFuture that completes exceptionally
    private static <T> CompletableFuture<T> failedFuture(Throwable ex) {
        CompletableFuture<T> future = new CompletableFuture<>();
        future.completeExceptionally(ex);
        return future;
    }
}

