    public static int getDecimalPlaces(String code) {
        return DECIMAL_PLACES.getOrDefault(code, 2);
    }

    /**
     * Returns the exchange rate for the specified currency relative to USD.
     *
     * @param code the currency code
     * @return the exchange rate, or 1 if the code is unsupported
     */
    public static BigDecimal getExchangeRate(String code) {
        return EXCHANGE_RATES.getOrDefault(code, BigDecimal.ONE);
    }

    /**
     * Converts an amount from one currency to another using exchange rates.
     * <p>
     * Validation:
     * <ul>
     *   <li>Throws {@code IllegalArgumentException} if either {@code fromCurrency}
     *   or {@code toCurrency} is not present in {@link #EXCHANGE_RATES}.</li>
     * </ul>
     * <p>
     * Conversion steps:
     * <ol>
     *   <li>Convert the source amount to USD by dividing by the source currency's
     *   exchange rate (units per USD). The division uses a scale of 10 and
     *   {@link RoundingMode#HALF_UP} to preserve precision.</li>
     *   <li>Convert the USD amount to the target currency by multiplying by the
     *   target currency's exchange rate.</li>
     *   <li>Round the final result to the number of decimal places specified by
     *   the target currency's entry in {@link #DECIMAL_PLACES}, using
     *   {@link RoundingMode#HALF_UP}.</li>
     * </ol>
     *
     * @param amount       the amount to convert
     * @param fromCurrency the currency code of the source amount
     * @param toCurrency   the currency code of the target amount
     * @return the converted amount, rounded to the target currency's precision
     * @throws IllegalArgumentException if either currency code is unsupported
     */
    public static BigDecimal convertCurrency(BigDecimal amount, String fromCurrency, String toCurrency) {
        if (amount == null || fromCurrency == null || toCurrency == null) {
            return BigDecimal.ZERO;
        }

        // Validate that both currencies are supported
        if (!EXCHANGE_RATES.containsKey(fromCurrency)) {
            throw new IllegalArgumentException("Unsupported source currency: " + fromCurrency);
        }
        if (!EXCHANGE_RATES.containsKey(toCurrency)) {
            throw new IllegalArgumentException("Unsupported target currency: " + toCurrency);
        }

        BigDecimal rateFrom = EXCHANGE_RATES.get(fromCurrency);
        BigDecimal rateTo = EXCHANGE_RATES.get(toCurrency);

        // Step 1: Convert source amount to USD
        BigDecimal amountInUSD = amount.divide(rateFrom, 10, RoundingMode.HALF_UP);

        // Step 2: Convert USD amount to target currency
        BigDecimal result = amountInUSD.multiply(rateTo);

        // Step 3: Round to target currency's decimal places
        int scale = DECIMAL_PLACES.getOrDefault(toCurrency, 2);
        result = result.setScale(scale, RoundingMode.HALF_UP);

        return result;
    }
}
