import java.util.Date;
import java.util.HashMap;
import java.util.Map;

/**
 * Simple in‑memory authentication token validator.
 */
class AuthTokenValidator {

    /** In‑memory token store. */
    private final Map<String, Token> tokenDatabase;
    /** In‑memory user store. */
    private final Map<String, User> userDatabase;

    /**
     * Initializes the validator with a sample token and user.
     */
    public AuthTokenValidator() {
        tokenDatabase = new HashMap<>();
        userDatabase = new HashMap<>();

        // Sample user
        User user = new User("user123", "192.168.1.1");
        userDatabase.put(user.getId(), user);

        // Sample token: "user" + IP
        String tokenString = "user192.168.1.1";
        Token token = new Token(
                tokenString,
                new Date(System.currentTimeMillis() + 3600_000), // expires in 1 hour
                1,                                            // active status
                user.getId()
        );
        tokenDatabase.put(tokenString, token);
    }

    /**
     * Validates a token against the in‑memory databases.
     *
     * @param token    the token string
     * @param clientIp the IP address of the client
     * @return a map containing validation results
     */
    public Map<String, Object> validateToken(String token, String clientIp) {
        Map<String, Object> result = new HashMap<>();

        // 1. Null or empty token
        if (token == null || token.isEmpty()) {
            result.put("valid", false);
            result.put("message", "Token is empty");
            return result;
        }

        // 2. Token must contain the substring "user"
        if (!token.contains("user")) {
            result.put("valid", false);
            result.put("message", "Token format invalid");
            return result;
        }

        // 3. Token existence
        Token storedToken = tokenDatabase.get(token);
        if (storedToken == null) {
            result.put("valid", false);
            result.put("message", "Token not found");
            return result;
        }

        // 4. Expiration check
        if (storedToken.getExpiration().before(new Date())) {
            result.put("valid", false);
            result.put("message", "Token expired");
            return result;
        }

        // 5. Status check
        if (storedToken.getStatus() != 1) {
            result.put("valid", false);
            result.put("message", "Token invalid");
            return result;
        }

        // 6. User existence
        User user = userDatabase.get(storedToken.getUserId());
        if (user == null) {
            result.put("valid", false);
            result.put("message", "User not found");
            return result;
        }

        // 7. IP extraction and comparison
        int userIndex = token.indexOf("user");
        String ipInToken = token.substring(userIndex + "user".length());
        if (!ipInToken.equals(clientIp)) {
            result.put("valid", false);
            result.put("message", "IP address mismatch");
            return result;
        }

        // 8. All checks passed
        result.put("valid", true);
        result.put("message", "Validation successful");
        result.put("user", user);
        return result;
    }

    /* --------------------------------------------------------------------- */
    /* Inner classes representing Token and User entities.                    */
    /* --------------------------------------------------------------------- */

    /**
     * Represents an authentication token.
     */
    private static class Token {
        private final String tokenString;
        private final Date expiration;
        private final int status;
        private final String userId;

        public Token(String tokenString, Date expiration, int status, String userId) {
            this.tokenString = tokenString;
            this.expiration = expiration;
            this.status = status;
            this.userId = userId;
        }

        public String getTokenString() {
            return tokenString;
        }

        public Date getExpiration() {
            return expiration;
        }

        public int getStatus() {
            return status;
        }

        public String getUserId() {
            return userId;
        }
    }

    /**
     * Represents a user.
     */
    private static class User {
        private final String id;
        private final String ip;

        public User(String id, String ip) {
            this.id = id;
            this.ip = ip;
        }

        public String getId() {
            return id;
        }

        public String getIp() {
            return ip;
        }

        @Override
        public String toString() {
            return "User{id='" + id + "', ip='" + ip + "'}";
        }
    }
}

