class TicTacToeGame {
    private final char[][] board;
    private char currentPlayer;
    private boolean gameOver;
    private char winner; // 'X', 'O', 'D' (draw), or '-' (no winner yet)

    public TicTacToeGame(int size) {
        board = new char[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                board[i][j] = '-';
            }
        }
        currentPlayer = 'X';
        gameOver = false;
        winner = '-';
    }

    /**
     * Attempts to place the current player's mark at the specified position.
     *
     * @param row the row index (0‑based)
     * @param col the column index (0‑based)
     * @return true if the move was successful; false if the move is out of bounds,
     *         the cell is already occupied, or the game is over.
     */
    public boolean makeMove(int row, int col) {
        if (gameOver) {
            return false;
        }

        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length) {
            return false;
        }

        if (board[row][col] != '-') {
            return false;
        }

        // Place the mark
        board[row][col] = currentPlayer;

        // Check for win in the row
        boolean win = true;
        for (int j = 0; j < board.length; j++) {
            if (board[row][j] != currentPlayer) {
                win = false;
                break;
            }
        }

        // Check for win in the column if row check failed
        if (!win) {
            win = true;
            for (int i = 0; i < board.length; i++) {
                if (board[i][col] != currentPlayer) {
                    win = false;
                    break;
                }
            }
        }

        // Check main diagonal if the move lies on it
        if (!win && row == col) {
            win = true;
            for (int i = 0; i < board.length; i++) {
                if (board[i][i] != currentPlayer) {
                    win = false;
                    break;
                }
            }
        }

        // Check anti-diagonal if the move lies on it
        if (!win && row + col == board.length - 1) {
            win = true;
            for (int i = 0; i < board.length; i++) {
                if (board[i][board.length - 1 - i] != currentPlayer) {
                    win = false;
                    break;
                }
            }
        }

        if (win) {
            gameOver = true;
            winner = currentPlayer;
        } else {
            // Check for draw: board full and no winner
            if (isBoardFull()) {
                gameOver = true;
                winner = 'D'; // draw
            } else {
                // Switch player only if the game is not over
                currentPlayer = (currentPlayer == 'X') ? 'O' : 'X';
            }
        }

        return true;
    }

    /**
     * Returns a list of strings representing the current board state.
     * Each string corresponds to one row of the board.
     */
    public List<String> getBoardState() {
        List<String> state = new ArrayList<>();
        for (char[] row : board) {
            state.add(new String(row));
        }
        return state;
    }

    /**
     * Returns the player whose turn it is to move next.
     */
    public char getCurrentPlayer() {
        return currentPlayer;
    }

    /**
     * Returns true if the game has ended (either by win or by draw).
     */
    public boolean isGameOver() {
        return gameOver;
    }

    /**
     * Returns the winner ('X' or 'O') if there is one; 'D' for draw; otherwise '-'.
     */
    public char getWinner() {
        return winner;
    }

    // Helper method to determine if the board is full
    private boolean isBoardFull() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '-') {
                    return false;
                }
