        public double magnitude() {
            return Math.sqrt(x * x + y * y);
        }

        public Vector normalize() {
            double mag = magnitude();
            if (mag == 0) {
                return new Vector(0, 0);
            }
            return new Vector(x / mag, y / mag);
        }
    }

    /* ---------- Celestial class ---------- */
    public static class Celestial {
        public String name;
        public double mass;
        public Vector position;
        public Vector velocity;
        public Vector acceleration;

        public Celestial(String name, double mass, Vector position,
                         Vector velocity, Vector acceleration) {
            this.name = name;
            this.mass = mass;
            this.position = position;
            this.velocity = velocity;
            this.acceleration = acceleration;
        }

        /**
         * Update the position and velocity of this celestial body using the
         * equations:
         *   v = v0 + a * dt
         *   x = x0 + v0 * dt
         *
         * @param dt the time step
         */
        public void update(double dt) {
            Vector oldVelocity = new Vector(this.velocity.x, this.velocity.y);
            this.velocity = this.velocity.add(this.acceleration.multiply(dt));
            this.position = this.position.add(oldVelocity.multiply(dt));
        }

        /**
         * Compute the gravitational force vector exerted by another celestial body.
         *
         * @param other the other celestial body
         * @return the force vector acting on this body due to {@code other}
         */
        public Vector calculateGravityForce(Celestial other) {
            final double G = 6.67430e-11;
            final double EPSILON = 1e-10; // threshold to avoid division by zero

            Vector r = other.position.subtract(this.position);
            double distance = r.magnitude();

            if (distance < EPSILON) {
                // Bodies are extremely close; return zero force to avoid numerical instability
                return new Vector(0, 0);
            }

            double forceMagnitude = G * this.mass * other.mass / (distance * distance);
            Vector forceDirection = r.normalize();
            return forceDirection.multiply(forceMagnitude);
        }
    }

    /* ---------- Simulation method ---------- */
    public static List<List<Celestial>> simulate(List<Celestial> bodies,
                                                 double dt, int steps) {
        List<List<Celestial>> history = new ArrayList<>();

        // Store initial state
        history.add(copyState(bodies));

        for (int step = 0; step < steps; step++) {
            // Reset accelerations
            for (Celestial body : bodies) {
                body.acceleration = new Vector(0, 0);
            }

            // Compute gravitational forces between all pairs
            int n = bodies.size();
            for (int i = 0; i < n; i++) {
                Celestial bi = bodies.get(i);
                for (int j = i + 1; j < n; j++) {
                    Celestial bj = bodies.get(j);

                    // Force on bi due to bj
                    Vector forceOnBi = bi.calculateGravityForce(bj);
                    // Force on bj due to bi (Newton's third law)
                    Vector forceOnBj = bj.calculateGravityForce(bi).multiply(-1);

                    // Update accelerations
                    bi.acceleration = bi.acceleration.add(forceOnBi.multiply(1 / bi.mass));
                    bj.acceleration = bj.acceleration.add(forceOnBj.multiply(1 / bj.mass));
                }
            }

            // Update each body's velocity and position
            for (Celestial body : bodies) {
                body.update(dt);
            }

            // Store deep copy of the current state
            history.add(copyState(bodies));
        }

        return history;
    }

    /* ---------- Deep copy helper ---------- */
    private static List<Celestial> copyState(List<Celestial> bodies) {
        List<Celestial> copy = new ArrayList<>();
        for (Celestial b : bodies) {
            Vector pos = new Vector(b.position.x, b.position.y);
            Vector vel = new Vector(b.velocity.x, b.velocity.y);
            Vector acc = new Vector(b.acceleration.x, b.acceleration.y);
            copy.add(new Celestial(b.name, b.mass, pos, vel, acc));
        }
        return copy;
    }

    /* ---------- Solar system factory ---------- */
    /**
     * Creates a simple solar system containing the Sun, Earth, and Mars.
     * Positions are given in meters, velocities in meters per second.
     *
     * @return a list of Celestial objects representing the solar system
     */
    public static List<Celestial> createSolarSystem() {
        final double AU = 1.496e11;          // Astronomical unit in meters
        final double G = 6.67430e-11;        // Gravitational constant

        // Masses (kg)
        double massSun   = 1.9885e30;
        double massEarth = 5.972e24;
        double massMars  = 6.417e23;

        // Sun at origin, stationary
        Celestial sun = new Celestial(
                "Sun",
                massSun,
                new Vector(0, 0),
                new Vector(0, 0),
                new Vector(0, 0)
        );

        // Earth at 1 AU on x-axis, velocity in +y direction
        Celestial earth = new Celestial(
                "Earth",
                massEarth,
                new Vector(AU, 0),
                new Vector(0, 29_780),   // ~29.78 km/s
                new Vector(0, 0)
        );

        // Mars at 1.524 AU on x-axis, velocity in +y direction
        Celestial mars = new Celestial(
                "Mars",
                massMars,
                new Vector(1.524 * AU, 0),
                new Vector(0, 24_077),   // ~24.077 km/s
                new Vector(0, 0)
        );

        return Arrays.asList(sun, earth, mars);
    }
}
