        // If the input list is null or empty, return an error map
        if (logs == null || logs.isEmpty()) {
            Map<String, Object> errorMap = new HashMap<>();
            errorMap.put("error", "No logs provided for analysis");
            return errorMap;
        }

        // Result map
        Map<String, Object> result = new HashMap<>();

        // 1. Total number of logs
        result.put("totalLogs", logs.size());

        // 2. User frequency
        Map<String, Long> userFrequency = logs.stream()
                .collect(Collectors.groupingBy(SysLog::getUsername, Collectors.counting()));
        result.put("userFrequency", userFrequency);

        // 3. Most active user
        String mostActiveUser = userFrequency.entrySet().stream()
                .max(Comparator.comparingLong(Map.Entry::getValue))
                .map(Map.Entry::getKey)
                .orElse(null); // never null because logs is non‑empty
        result.put("mostActiveUser", mostActiveUser);

        // 4. Time‑based statistics
