import java.util.*;

public class CategoryManager {
    private final Map<String, List<Note>> categories = new LinkedHashMap<>();
    private String currentCategory;

    public CategoryManager() {
        // Initialize default category named '生活'
        categories.put("生活", new ArrayList<>());
        currentCategory = "生活";
    }

    /**
     * Adds a new category to the system.
     *
     * @param categoryName the name of the category to add
     * @return true if the category was added, false if it already existed
     */
    public boolean addCategory(String categoryName) {
        if (categories.containsKey(categoryName)) {
            return false;
        }
        categories.put(categoryName, new ArrayList<>());
        return true;
    }

    /**
     * Adds a note to the specified category. If the category does not exist,
     * it will be created automatically.
     *
     * @param category the category name
     * @param title    the note title
     * @param content  the note content
     */
    public void addNote(String category, String title, String content) {
        Note note = new Note(title, content);
        categories.computeIfAbsent(category, k -> new ArrayList<>()).add(note);
    }

    /**
     * Retrieves all notes in the specified category.
     *
     * @param category the category name
     * @return a list of notes; empty list if the category does not exist
     */
    public List<Note> getNotes(String category) {
        return categories.getOrDefault(category, Collections.emptyList());
    }

    /**
     * Removes a category by name.
     *
     * @param categoryName the name of the category to remove
     * @return the list of notes that were in the removed category,
     *         or null if the category does not exist
     */
    public List<Note> removeCategory(String categoryName) {
        List<Note> removedNotes = categories.remove(categoryName);
        if (removedNotes == null) {
            return null; // Category did not exist
        }

        // If the removed category was the current one, update currentCategory
        if (categoryName.equals(currentCategory)) {
            if (!categories.isEmpty()) {
                // Set to the first available category (in insertion order)
                currentCategory = categories.keySet().iterator().next();
            } else {
                currentCategory = "";
            }
        }
        return removedNotes;
