import java.util.List;
import java.util.Map;
import java.util.ArrayList;

/**
 * Utility class that processes a batch of HTTP requests sequentially.
 */
public class BatchProcessor {

    private final HttpRequestSimulator simulator = new HttpRequestSimulator();

    /**
     * Processes a list of request maps sequentially and returns a list of response maps.
     *
     * @param requests List of request maps. Each map must contain the keys:
     *                 "url" (String), "method" (String), "params" (Map<String,String>),
     *                 and optionally "headers" (Map<String,String>).
     * @return List of response maps produced by {@link HttpRequestSimulator#simulateHttpRequest}.
     * @throws IllegalArgumentException if any request map is missing required keys or contains invalid values.
     */
    public List<Map<String, Object>> processBatchRequests(List<Map<String, Object>> requests) {
        List<Map<String, Object>> responses = new ArrayList<>();

        for (Map<String, Object> request : requests) {
            // Extract required fields with type checks
            String url = (String) request.get("url");
            String method = (String) request.get("method");
            @SuppressWarnings("unchecked")
            Map<String, String> params = (Map<String, String>) request.get("params");
            @SuppressWarnings("unchecked")
            Map<String, String> headers = (Map<String, String>) request.get("headers");

            // Delegate to the simulator
            Map<String, Object> response = simulator.simulateHttpRequest(url, method, params, headers);
            responses.add(response);
        }

        return responses;
    }
}

