import java.util.*;
import java.util.function.*;

class WebSocketMessageHandler {
    private final Map<String, Consumer<Map<String, Object>>> messageHandlers;
    private final BiConsumer<String, String> errorLogger;
    private final RateLimiter rateLimiter;

    public WebSocketMessageHandler(BiConsumer<String, String> errorLogger) {
        this.messageHandlers = new HashMap<>();
        this.errorLogger = errorLogger;
        this.rateLimiter = new RateLimiter(100, 1000); // 100 msgs per 1000 ms
    }

    public void addMessageHandler(String messageType, Consumer<Map<String, Object>> handler) {
        messageHandlers.put(messageType, handler);
    }

    public boolean processMessage(String messageType, Map<String, Object> messageData) {
        // Rate limiting
        if (!rateLimiter.allow()) {
            errorLogger.accept("rate_limit", "Message rate limit exceeded");
            return false;
        }

        // Validation
        if (messageType == null || messageType.isEmpty()) {
            errorLogger.accept("validation_error", "messageType is null or empty");
            return false;
        }
        if (messageData == null) {
            errorLogger.accept("validation_error", "messageData is null");
            return false;
        }

        Consumer<Map<String, Object>> handler = messageHandlers.get(messageType);
        if (handler != null) {
            try {
                handler.accept(messageData);
                return true;
            } catch (Exception e) {
                errorLogger.accept("handler_error", e.getMessage());
                return false;
            }
        } else {
            errorLogger.accept("unknown_type", "No handler for message type: " + messageType);
            return false;
        }
    }

    /**
     * Simple sliding‑window rate limiter.
     * Allows up to {@code maxRequests} within {@code windowMs} milliseconds.
     */
    private static class RateLimiter {
        private final int maxRequests;
        private final long windowMs;
        private final Deque<Long> timestamps = new ArrayDeque<>();

        RateLimiter(int maxRequests, long windowMs) {
            this.maxRequests = maxRequests;
            this.windowMs = windowMs;
        }

        synchronized boolean allow() {
            long now = System.currentTimeMillis();
            long threshold = now - windowMs;

            // Remove timestamps older than the window
            while (!timestamps.isEmpty() && timestamps.peekFirst() < threshold) {
                timestamps.pollFirst();
            }

            if (timestamps.size() >= maxRequests) {
                return false; // limit exceeded
            }

            timestamps.addLast(now);
            return true;
        }
    }

    // Example usage
    public static void main(String[] args) throws InterruptedException {
        WebSocketMessageHandler handler = new WebSocketMessageHandler((level, msg) -> {
            System.err.println("[" + level + "] " + msg);
        });

        handler.addMessageHandler("chat", data -> {
            System.out.println("Chat message: " + data.get("text"));
        });

        handler.addMessageHandler("notification", data -> {
            System.out.println("Notification: " + data.get("title"));
        });

        Map<String, Object> chatMsg = new HashMap<>();
        chatMsg.put("text", "Hello, world!");

        // Send 101 messages quickly to trigger rate limiting
        for (int i = 0; i < 101; i++) {
            boolean ok = handler.processMessage("chat", chatMsg);
            if (!ok) {
                System.out.println("Message " + i + " rejected due to rate limit");
            }
        }

        // Wait for the window to reset
        Thread.sleep(1100);

        // Now it should succeed
        handler.processMessage("chat", chatMsg);
    }
}

