import java.util.concurrent.*;

public class ThreadExecutor {

    /**
     * Executes the given task in a separate thread and returns its result.
     * If the task does not complete within the specified timeout, a
     * TimeoutException with a specific message is thrown and the worker
     * thread is interrupted.
     *
     * @param task       the task to execute
     * @param timeoutMs  maximum time to wait for the task to finish, in milliseconds
     * @param <T>        the type of the task's result
     * @return the result of the task
     * @throws Exception if the task throws an exception or the timeout expires
     */
    public static <T> T executeTaskWithTimeout(Callable<T> task, long timeoutMs) throws Exception {
        FutureTask<T> futureTask = new FutureTask<>(task);
        Thread worker = new Thread(futureTask);
        worker.start();

        try {
            return futureTask.get(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            // Interrupt the worker thread to allow it to clean up
            worker.interrupt();
            throw new TimeoutException("The task does not complete within the specified timeout period.");
        } catch (ExecutionException e) {
            // Propagate the original exception thrown by the task
            Throwable cause = e.getCause();
            if (cause instanceof Exception) {
                throw (Exception) cause;
            } else {
                throw new RuntimeException(cause);
            }
        } catch (InterruptedException e) {
            // Preserve interrupt status and rethrow
            Thread.currentThread().interrupt();
            throw e;
        } finally {
            // Ensure the worker thread has finished before returning
            try {
                worker.join();
            } catch (InterruptedException ignored) {
            }
        }
    }
}

