import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class EnhancedFileOperations {

    /**
     * Static inner class that holds statistics about a file.
     */
    public static class FileStats {
        public final int lineCount;
        public final int wordCount;
        public final int characterCount;
        public final double averageWordsPerLine;

        public FileStats(int lineCount, int wordCount, int characterCount, double averageWordsPerLine) {
            this.lineCount = lineCount;
            this.wordCount = wordCount;
            this.characterCount = characterCount;
            this.averageWordsPerLine = averageWordsPerLine;
        }

        @Override
        public String toString() {
            return String.format(
                "File Statistics:%n" +
                "  Lines: %d%n" +
                "  Words: %d%n" +
                "  Characters: %d%n" +
                "  Average words per line: %.2f",
                lineCount, wordCount, characterCount, averageWordsPerLine
            );
        }
    }

    /**
     * Reads the file and returns its lines after performing validation.
     *
     * @param file the file to read
     * @return a list of lines from the file
     * @throws IllegalArgumentException if the file is null
     * @throws IOException if the file does not exist, is not a file, or cannot be read
     */
    public static List<String> readFileWithValidation(File file) throws IOException {
        if (file == null) {
            throw new IllegalArgumentException("File must not be null.");
        }
        if (!file.exists() || !file.isFile() || !file.canRead()) {
            throw new IOException("File does not exist or cannot be read: " + file.getPath());
        }

        List<String> lines = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                lines.add(line);
            }
        }
        return lines;
    }

    /**
     * Analyzes the content of the given file and returns statistics.
     *
     * @param file the file to analyze
     * @return a FileStats object containing the statistics
     * @throws IOException if the file cannot be read
     */
    public static FileStats analyzeFileContent(File file) throws IOException {
        List<String> lines = readFileWithValidation(file);

        int lineCount = lines.size();
        int characterCount = 0;
        for (String line : lines) {
            characterCount += line.length();
        }

        // wordCount and averageWordsPerLine are kept as 0 for now
        return new FileStats(lineCount, 0, characterCount, 0.0);
    }
}

