public class TreePathAnalyzer {

    /** Root of the N‑ary tree */
    private final Node root;

    public TreePathAnalyzer(Node root) {
        this.root = root;
    }

    /**
     * Returns the longest path from the root to any leaf.
     * The path is represented as a list of nodes, starting with the root
     * and ending with the leaf node.
     */
    public List<Node> findLongestPath() {
        List<Node> bestPath = new ArrayList<>();
        if (root == null) {
            return bestPath; // empty tree
        }
        List<Node> currentPath = new ArrayList<>();
        dfs(root, currentPath, bestPath);
        return bestPath;
    }

    /**
     * Depth‑first search that keeps track of the current path.
     * When a leaf is reached, the current path is compared with the best
     * path found so far and updated if it is longer.
     */
    private void dfs(Node node, List<Node> currentPath, List<Node> bestPath) {
        currentPath.add(node);

        if (node.children.isEmpty()) { // leaf
            if (currentPath.size() > bestPath.size()) {
                bestPath.clear();
                bestPath.addAll(new ArrayList<>(currentPath));
            }
        } else {
            for (Node child : node.children) {
                dfs(child, currentPath, bestPath);
            }
        }

        currentPath.remove(currentPath.size() - 1); // backtrack
    }

    /** Nested Node class representing a node in an N‑ary tree */
    public static class Node {
        public final int data;
        public final List<Node> children = new ArrayList<>();

