import java.util.ArrayList;
import java.util.List;

/**
 * TreePathAnalyzer finds the longest path (diameter) in an N‑ary tree.
 * The algorithm runs in O(N) time, visiting each node exactly once.
 */
public class TreePathAnalyzer {

    /** Root of the tree */
    private final Node root;

    /** Best diameter found so far (in edges) */
    private int bestEdges = -1;

    /** Endpoints of the best diameter */
    private Node bestStart = null;
    private Node bestEnd = null;

    public TreePathAnalyzer(Node root) {
        this.root = root;
    }

    /**
     * Returns the longest path in the tree as a list of nodes.
     * If the tree is empty (root == null) an empty list is returned.
     */
    public List<Node> findLongestPath() {
        if (root == null) {
            return new ArrayList<>(); // empty tree
        }

        // Run DFS to compute diameter and endpoints
        dfs(root);

        // Reconstruct the path between bestStart and bestEnd
        return buildPath(bestStart, bestEnd);
    }

    /**
     * Depth‑first search that returns the deepest node from the current node
     * and its depth in edges. While traversing it updates the global best
     * diameter and its endpoints.
     */
    private Result dfs(Node node) {
        // If leaf, depth = 0 edges
        if (node.children.isEmpty()) {
            return new Result(node, 0);
        }

        // Track the two deepest child depths and their deepest nodes
        int depth1 = -1, depth2 = -1;
        Node deepest1 = null, deepest2 = null;

        for (Node child : node.children) {
            Result childRes = dfs(child);

            if (childRes.depth > depth1) {
                depth2 = depth1;
                deepest2 = deepest1;
                depth1 = childRes.depth;
                deepest1 = childRes.deepest;
            } else if (childRes.depth > depth2) {
                depth2 = childRes.depth;
                deepest2 = childRes.deepest;
            }
        }

        // Candidate diameter that passes through this node
        int candidateEdges = depth1 + depth2 + 2; // edges between two deepest leaves
        if (candidateEdges > bestEdges) {
            bestEdges = candidateEdges;
            bestStart = deepest1;
            bestEnd = deepest2;
        }

        // Return deepest node and its depth from this node
        return new Result(deepest1, depth1 + 1);
    }

    /**
     * Builds the path between two nodes using parent pointers.
     */
    private List<Node> buildPath(Node start, Node end) {
        if (start == null || end == null) {
            return new ArrayList<>();
        }

        // Build paths from each node up to the root
        List<Node> pathStart = new ArrayList<>();
        Node cur = start;
        while (cur != null) {
            pathStart.add(cur);
            cur = cur.parent;
        }

        List<Node> pathEnd = new ArrayList<>();
        cur = end;
        while (cur != null) {
            pathEnd.add(cur);
            cur = cur.parent;
        }

        // Find lowest common ancestor (LCA)
        int i = pathStart.size() - 1;
        int j = pathEnd.size() - 1;
        Node lca = null;
        while (i >= 0 && j >= 0 && pathStart.get(i) == pathEnd.get(j)) {
            lca = pathStart.get(i);
            i--;
            j--;
        }

        // Construct the full path: start -> ... -> lca -> ... -> end
        List<Node> result = new ArrayList<>();

        // From start up to but not including LCA
        for (int k = 0; k <= i; k++) {
            result.add(pathStart.get(k));
        }

        // Add LCA
        result.add(lca);

        // From LCA down to end (excluding LCA)
        for (int k = j; k >= 0; k--) {
            result.add(pathEnd.get(k));
        }

        return result;
    }

    /** Helper class to hold DFS results */
    private static class Result {
        final Node deepest;
        final int depth; // depth in edges from the current node to deepest leaf

        Result(Node deepest, int depth) {
            this.deepest = deepest;
            this.depth = depth;
        }
    }

    /** Nested Node class for an N‑ary tree. */
    public static class Node {
        public final int data;
        public final List<Node> children = new ArrayList<>();
        public Node parent = null; // parent pointer for path reconstruction

        public Node(int data) {
            this.data = data;
        }

        public void addChild(Node child) {
            child.parent = this;
            children.add(child);
        }

        @Override
        public String toString() {
            return Integer.toString(data);
        }
    }

