import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.atomic.AtomicInteger;

class PollingQueue<T> {
    private final Queue<T> queue;
    private final AtomicInteger pollingCount;
    private final int maxPollingAttempts;

    public PollingQueue(int maxPollingAttempts) {
        this.queue = new LinkedList<>();
        this.pollingCount = new AtomicInteger(0);
        this.maxPollingAttempts = maxPollingAttempts;
    }

    public synchronized void enqueue(T element) {
        queue.add(element);
    }

    public synchronized T poll() {
        // Increment the counter for this polling attempt
        int attempts = pollingCount.incrementAndGet();

        // Enforce the maximum polling attempts limit
        if (attempts > maxPollingAttempts) {
            throw new IllegalStateException(
                "Maximum polling attempts (" + maxPollingAttempts + ") exceeded."
            );
        }

        // Return the next element (or null if the queue is empty)
        return queue.poll();
    }

    public int getPollingCount() {
        return pollingCount.get();
    }

    public int getMaxPollingAttempts() {
        return maxPollingAttempts;
    }
}

public class Main {
    public static void main(String[] args) {
        PollingQueue<String> pq = new PollingQueue<>(3);

        pq.enqueue("first");
        pq.enqueue("second");
        pq.enqueue("third");

        try {
            // These three polls are allowed
            System.out.println("Polled: " + pq.poll());
            System.out.println("Polled: " + pq.poll());
            System.out.println("Polled: " + pq.poll());

            // This fourth poll exceeds the limit and throws an exception
            System.out.println("Polled: " + pq.poll());
        } catch (IllegalStateException e) {
            System.err.println("Error: " + e.getMessage());
        }

        System.out.println("Total polls performed: " + pq.getPollingCount());
    }
}

