import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

class PollingQueue<T> {
    private final Queue<T> queue;
    private final AtomicInteger pollingCount;
    private final int maxPollingAttempts;

    public PollingQueue(int maxPollingAttempts) {
        this.queue = new LinkedList<>();
        this.pollingCount = new AtomicInteger(0);
        this.maxPollingAttempts = maxPollingAttempts;
    }

    /** Adds an element to the queue and notifies waiting threads. */
    public synchronized void enqueue(T element) {
        queue.add(element);
        notifyAll(); // wake up threads waiting for an element
    }

    /** Retrieves and removes the head of the queue, enforcing the polling limit. */
    public synchronized T poll() {
        int attempts = pollingCount.incrementAndGet();
        if (attempts > maxPollingAttempts) {
            throw new IllegalStateException(
                "Maximum polling attempts (" + maxPollingAttempts + ") exceeded.");
        }
        return queue.poll();
    }

    /**
     * Waits up to {@code timeoutMillis} for an element to become available.
     * Returns the element if it becomes available within the timeout, otherwise {@code null}.
     */
    public synchronized T waitForElement(long timeoutMillis) {
        if (timeoutMillis < 0) {
            throw new IllegalArgumentException("timeoutMillis must be non‑negative");
        }

        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMillis);
        while (queue.isEmpty()) {
            long remainingNanos = deadline - System.nanoTime();
            if (remainingNanos <= 0) {
                return null; // timeout elapsed
            }
            try {
                // Convert nanos to millis for wait, but keep the remaining nanos for the loop
                wait(TimeUnit.NANOSECONDS.toMillis(remainingNanos));
            } catch (InterruptedException e) {
                // Preserve interrupt status and exit
                Thread.currentThread().interrupt();
                return null;
            }
        }
        return queue.poll();
    }

    public int getPollingCount() {
        return pollingCount.get();
    }

    public int getMaxPollingAttempts() {
        return maxPollingAttempts;
    }
}

public class Main {
    public static void main(String[] args) {
        PollingQueue<String> pq = new PollingQueue<>(5);

        // Start a thread that will enqueue an element after a delay
        new Thread(() -> {
            try {
                Thread.sleep(500); // 0.5 second delay
                pq.enqueue("delayed");
                System.out.println("Enqueued delayed element");
            } catch (InterruptedException ignored) {
            }
        }).start();

        // Attempt to wait for an element with a 1 second timeout
        String element = pq.waitForElement(1000);
        System.out.println("waitForElement returned: " + element);

        // Attempt to wait for an element with a 200 ms timeout (should time out)
        element = pq.waitForElement(200);
        System.out.println("waitForElement returned after timeout: " + element);
    }
}

