import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * Manages daemon threads and automatically cleans up dead ones.
 */
public class ThreadResourceManager {

    /** Stores active daemon threads by name. */
    private final Map<String, Thread> threadMap = new ConcurrentHashMap<>();

    /** Scheduler that periodically removes dead threads. */
    private final ScheduledExecutorService monitorExecutor;

    /**
     * Constructs the manager and starts the automatic monitoring task.
     */
    public ThreadResourceManager() {
        // Create a single‑thread scheduler whose thread is a daemon.
        monitorExecutor = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            return t;
        });

        // Run the cleanup task every second.
        monitorExecutor.scheduleAtFixedRate(this::cleanupDeadThreads,
                                            1, 1, TimeUnit.SECONDS);
    }

    /**
     * Creates a daemon thread with the given name and task, starts it,
     * and stores it in the internal map.
     *
     * @param threadName the name of the thread to create
     * @param task       the Runnable task to execute
     * @return true if the thread was successfully created and started;
     *         false if threadName or task is null, or if a thread with the
     *         same name already exists
     */
    public boolean createDaemonThread(String threadName, Runnable task) {
        if (threadName == null || task == null) {
            return false;
        }

        Thread thread = new Thread(task, threadName);
        thread.setDaemon(true);

        // Ensure thread names are unique.
        Thread existing = threadMap.putIfAbsent(threadName, thread);
        if (existing != null) {
            return false; // A thread with this name already exists.
        }

        thread.start();
        return true;
    }

    /**
     * Stops (interrupts) and removes the daemon thread with the given name.
     *
     * @param threadName the name of the thread to stop
     * @return true if the thread was found and stopped; false otherwise
     */
    public boolean stopDaemonThread(String threadName) {
        if (threadName == null) {
            return false;
        }

        Thread thread = threadMap.remove(threadName);
        if (thread != null) {
            thread.interrupt();
            return true;
        }
        return false;
    }

    /**
     * Returns the current number of active threads stored in the internal map.
     *
     * @return the count of active threads
     */
    public int getActiveThreadCount() {
        return threadMap.size();
    }

    /**
     * Retrieves a thread by its name.
     *
     * @param threadName the name of the thread
     * @return the Thread instance, or null if not found
