import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.Collections;
import java.util.List;

public class FileOperationsManager {

    /**
     * Writes a list of strings to a file, each string on a new line.
     *
     * @param path   the file path
     * @param lines  the list of strings to write
     * @param append if true, data will be appended to the file; otherwise the file will be overwritten
     * @return true if the operation succeeded, false otherwise
     */
    public boolean writeToFile(String path, List<String> lines, boolean append) {
        Path filePath = Paths.get(path);
        try {
            // Ensure parent directories exist
            Path parent = filePath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }

            // Determine open options
            StandardOpenOption[] options = append
                    ? new StandardOpenOption[]{StandardOpenOption.CREATE, StandardOpenOption.APPEND}
                    : new StandardOpenOption[]{StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING};

            try (BufferedWriter writer = Files.newBufferedWriter(filePath, StandardCharsets.UTF_8, options)) {
                for (String line : lines) {
                    writer.write(line);
                    writer.newLine();
                }
            }
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    /**
     * Reads all lines from a UTF-8 encoded file.
     *
