import java.util.ArrayList;
import java.util.Collections;

class CargoOptimizer {

    /**
     * Calculates the maximum number of trips a cargo vehicle can make.
     * A trip can be made in two ways:
     * 1. A single item whose weight is at least the vehicle capacity.
     * 2. A group of items where the heaviest item's weight multiplied by the
     *    group size is at least the vehicle capacity.
     *
     * @param weights  List of item weights.
     * @param capacity Vehicle capacity.
     * @return Maximum number of trips.
     */
    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        if (weights == null || capacity <= 0) {
            return 0;
        }

        int soloTrips = 0;
        ArrayList<Integer> remaining = new ArrayList<>();

        // Separate items that can travel alone
        for (int w : weights) {
            if (w >= capacity) {
                soloTrips++;
            } else {
                remaining.add(w);
            }
        }

        // No remaining items – all trips are solo
        if (remaining.isEmpty()) {
            return soloTrips;
        }

        // Sort remaining items to enable greedy grouping
        Collections.sort(remaining);

        int left = 0;                     // index of the smallest remaining item
        int right = remaining.size() - 1;  // index of the largest remaining item
        int groupTrips = 0;

        while (left <= right) {
            int maxWeight = remaining.get(right);
            // Minimum group size needed for this maxWeight
            int requiredSize = (capacity + maxWeight - 1) / maxWeight; // ceil(capacity / maxWeight)

            // Check if we have enough items to form such a group
            if (requiredSize <= (right - left + 1)) {
                // Form the group: use the largest item and the smallest (requiredSize-1) items
                left += requiredSize - 1; // consume smallest items
                right--;                  // consume the largest item
                groupTrips++;
            } else {
                // Not enough items left to satisfy the requirement for this maxWeight
                break;
            }
        }

        return soloTrips + groupTrips;
    }
}

