        for (int w : copy) {
            if (w >= capacity) {
                soloTrips++;
            } else {
                remaining.add(w);
            }
        }

        // No remaining items – all trips are solo
        if (remaining.isEmpty()) {
            return soloTrips;
        }

        // Sort remaining items in descending order
        remaining.sort(Collections.reverseOrder());

        int left = 0;                     // index of the heaviest remaining item
        int right = remaining.size() - 1; // index of the lightest remaining item
        int groupTrips = 0;

        while (left <= right) {
            int maxWeight = remaining.get(left);
            // Minimum group size needed for this maxWeight
            int requiredSize = (capacity + maxWeight - 1) / maxWeight; // ceil(capacity / maxWeight)

            // Check if we have enough items to form such a group
            if (requiredSize <= (right - left + 1)) {
                // Form the group: use the heaviest item and the lightest (requiredSize-1) items
                left++;                     // consume the heaviest item
                right -= (requiredSize - 1); // consume the lightest items
                groupTrips++;
            } else {
                // Not enough items left to satisfy the requirement for this maxWeight
                break;
            }
        }

        return soloTrips + groupTrips;
    }
}

