import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class UserInfoManager {

    /**
     * Represents a phone contact with a name and phone number.
     */
    public static class PhoneContact {
        private String name;
        private String phoneNumber;

        public PhoneContact(String name, String phoneNumber) {
            this.name = name;
            this.phoneNumber = phoneNumber;
        }

        public String getName() {
            return name;
        }

        public String getPhoneNumber() {
            return phoneNumber;
        }

        @Override
        public String toString() {
            return "PhoneContact{name='" + name + "', phoneNumber='" + phoneNumber + "'}";
        }
    }

    /**
     * Represents processed user information.
     */
    public static class UserInfo {
        private String name;
        private String phoneNumber;

        public UserInfo(String name, String phoneNumber) {
            this.name = name;
            this.phoneNumber = phoneNumber;
        }

        public String getName() {
            return name;
        }

        public String getPhoneNumber() {
            return phoneNumber;
        }

        @Override
        public String toString() {
            return "UserInfo{name='" + name + "', phoneNumber='" + phoneNumber + "'}";
        }
    }

    /**
     * Processes a list of PhoneContact objects and returns a map containing
     * a list of successfully processed UserInfo objects under the key "success".
     *
     * @param contacts List of PhoneContact objects to process.
     * @return Map with key "success" mapping to a list of UserInfo objects.
     */
    public Map<String, List<UserInfo>> processContacts(List<PhoneContact> contacts) {
        List<UserInfo> successfulUsers = new ArrayList<>();

        for (PhoneContact contact : contacts) {
            if (isValidPhoneNumber(contact.getPhoneNumber())) {
                UserInfo userInfo = new UserInfo(contact.getName(), contact.getPhoneNumber());
                successfulUsers.add(userInfo);
            }
            // Invalid contacts are ignored as per the requirement.
        }

        Map<String, List<UserInfo>> result = new HashMap<>();
        result.put("success", successfulUsers);
        return result;
    }

    /**
     * Validates that the phone number consists of exactly 10 digits.
     *
     * @param phoneNumber The phone number string to validate.
     * @return true if valid, false otherwise.
     */
    private boolean isValidPhoneNumber(String phoneNumber) {
        return phoneNumber != null && phoneNumber.matches("\\d{10}");
    }
}
