import java.util.HashMap;
import java.util.Map;

class UrlRouter {
    private Map<String, String> routeMap;
    private String defaultRoute;

    public UrlRouter(Map<String, String> routes, String defaultRoute) {
        this.routeMap = new HashMap<>(routes);
        this.defaultRoute = defaultRoute;
    }

    /**
     * Resolve the given path to a route.
     * First checks for an exact static match.
     * If none, attempts to match any parameterized route.
     * If still none, returns the default route.
     */
    public String resolveRoute(String path) {
        // Static route lookup
        if (routeMap.containsKey(path)) {
            return routeMap.get(path);
        }

        // Dynamic route lookup
        for (Map.Entry<String, String> entry : routeMap.entrySet()) {
            String key = entry.getKey();
            if (isParameterizedRoute(key)) {
                // Convert the parameterized key into a regex pattern
                String regex = key.replaceAll("\\{[^/]+\\}", "[^/]+");
                if (path.matches(regex)) {
                    return entry.getValue();
                }
            }
        }

        // No match found – return default
        return defaultRoute;
    }

    /**
     * Determines whether a route string contains a parameter placeholder
     * in the form {paramName}. The placeholder is identified by a pair
     * of curly braces with at least one character inside.
     */
    private boolean isParameterizedRoute(String route) {
        int open = route.indexOf('{');
        int close = route.indexOf('}');
        return open != -1 && close != -1 && open < close;
    }
}

