    String getErrorMessage();
}

/**
 * Manages configuration key‑value pairs with optional required keys and custom validators.
 */
public class ConfigurationManager {
    private final Map<String, Object> configMap;
    private final Set<String> requiredKeys;
    private final Map<String, List<Validator>> validators;

    /**
     * Creates a new ConfigurationManager.
     *
     * @param requiredKeys the set of keys that must be present in the configuration
     * @param validators   a map of configuration keys to lists of validators
     */
    public ConfigurationManager(Set<String> requiredKeys,
                                Map<String, List<Validator>> validators) {
        this.configMap = new HashMap<>();
        this.requiredKeys = new HashSet<>(requiredKeys);
        this.validators = validators != null ? new HashMap<>(validators) : new HashMap<>();
    }

    /**
     * Loads configuration from the supplied properties map.
     *
     * @param properties the map of configuration properties
     * @throws ConfigurationException if any required key is missing or a validator fails
     */
    public void loadConfiguration(Map<String, String> properties) {
        // Check for missing required keys
        Set<String> missing = new HashSet<>();
        for (String key : requiredKeys) {
            if (!properties.containsKey(key)) {
                missing.add(key);
            }
        }
        if (!missing.isEmpty()) {
            throw new ConfigurationException(
                "Missing required keys: " + String.join(", ", missing));
        }

        // Store all properties into the internal map
        for (Map.Entry<String, String> entry : properties.entrySet()) {
            configMap.put(entry.getKey(), entry.getValue());
        }

        // Validate configuration values
        validateConfiguration();
    }

    /**
     * Validates all configuration values against their associated validators.
     *
     * @throws ConfigurationException if any validator fails
     */
    private void validateConfiguration() {
        for (Map.Entry<String, List<Validator>> entry : validators.entrySet()) {
            String key = entry.getKey();
            Object value = configMap.get(key);
            List<Validator> validatorList = entry.getValue();
            if (validatorList == null) {
                continue;
            }
            for (Validator v : validatorList) {
                if (!v.validate(value)) {
                    throw new ConfigurationException(v.getErrorMessage());
                }
            }
        }
    }

    /**
     * Retrieves a configuration value cast to the requested type, performing automatic
     * conversion for Integer, Long, Double, Boolean, String, and TimeUnit.
     *
     * @param key  the configuration key
     * @param type the desired type
     * @param <T>  the type parameter
     * @return the configuration value cast to {@code T}, or {@code null} if the key is absent
     * @throws ConfigurationException if type conversion fails
     */
    @SuppressWarnings("unchecked")
    public <T> T getConfigValue(String key, Class<T> type) {
        Object value = configMap.get(key);
        if (value == null) {
            return null;
        }

        // If the value is already of the requested type, return it directly
        if (type.isInstance(value)) {
            return (T) value;
        }

        // Attempt conversion if the value is a String
        if (value instanceof String) {
            String strVal = (String) value;
            try {
                if (type == Integer.class) {
                    return (T) Integer.valueOf(strVal);
                } else if (type == Long.class) {
                    return (T) Long.valueOf(strVal);
                } else if (type == Double.class) {
                    return (T) Double.valueOf(strVal);
                } else if (type == Boolean.class) {
                    return (T) Boolean.valueOf(strVal);
                } else if (type == String.class) {
                    return (T) strVal;
                } else if (type == TimeUnit.class) {
                    return (T) TimeUnit.valueOf(strVal.toUpperCase());
                }
            } catch (NumberFormatException | IllegalArgumentException e) {
                throw new ConfigurationException(
                    "Failed to convert key '" + key + "' to " + type.getSimpleName() + ": " + e.getMessage());
            }
        }

        // If conversion is not possible, throw an exception
        throw new ConfigurationException(
            "Unsupported conversion for key '" + key + "' to type " + type.getSimpleName());
    }

    /**
     * Stores a configuration value.
     *
     * @param key   the configuration key
     * @param value the value to store
     */
    public void setConfigValue(String key, Object value) {
        configMap.put(key, value);
    }
}

