 */
public class User {
    private String steam32Id;
    private String username;
    private String profileURL;
    private final String avatarMedium;
    private final String avatarFull;

    public User(String steam32Id, String username, String profileURL,
                String avatarMedium, String avatarFull) {
        this.steam32Id = steam32Id;
        this.username = username;
        this.profileURL = profileURL;
        this.avatarMedium = avatarMedium;
        this.avatarFull = avatarFull;
    }

