                "id=" + id +
                ", firstName='" + firstName + '\'' +
                ", lastName='" + lastName + '\'' +
                ", email='" + email + '\'' +
                ", phone='" + phone + '\'' +
                '}';
    }
}

/**
 * Manager responsible for creating and storing clients.
 */
class ClientManager {
    private final Map<Long, ClientTO> clients = new HashMap<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    /**
     * Creates a new client, assigns a unique ID, stores it, and returns the client.
     *
     * @param client the client data (without ID)
     * @return the client with the assigned unique ID
     * @throws IllegalArgumentException if client is null, has a non-null ID,
     *                                  or if firstName, lastName, or email are null/empty,
     *                                  or if email does not contain '@'.
     */
    public ClientTO createClient(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        if (client.getId() != 0) {
            throw new IllegalArgumentException("Client ID must be null or zero before creation.");
        }
        if (isNullOrEmpty(client.getFirstName())) {
            throw new IllegalArgumentException("First name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getLastName())) {
            throw new IllegalArgumentException("Last name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getEmail())) {
            throw new IllegalArgumentException("Email cannot be null or empty.");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'.");
        }

        long id = idGenerator.getAndIncrement();
        client.setId(id);
        clients.put(id, client);
        return client;
    }

    /**
     * Finds a client by its ID.
     *
     * @param id the client ID
     * @return the client if found, otherwise null
     * @throws IllegalArgumentException if id is null
     */
    public ClientTO findClient(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null.");
        }
        return clients.get(id);
    }

    /**
     * Returns all stored clients.
     *
     * @return a collection of all clients
     */
    public Collection<ClientTO> getAllClients() {
        return clients.values();
    }

    private boolean isNullOrEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }
}

/**
 * Demonstrates the usage of ClientManager and ClientTO.
 */
public class Main {
    public static void main(String[] args) {
        ClientManager manager = new ClientManager();

        ClientTO client1 = new ClientTO("Alice", "Smith", "alice@example.com", "555-0101");
        ClientTO client2 = new ClientTO("Bob", "Johnson", "bob@example.com", "555-0202");

        // Create clients
        ClientTO created1 = manager.createClient(client1);
        ClientTO created2 = manager.createClient(client2);

        System.out.println("Created clients:");
        System.out.println(created1);
        System.out.println(created2);

        // Find a client
        ClientTO found = manager.findClient(created1.getId());
        System.out.println("\nFound client:");
        System.out.println(found);

        // Attempt to find a non-existent client
        ClientTO notFound = manager.findClient(999L);
        System.out.println("\nNon-existent client (should be null):");
        System.out.println(notFound);
    }
}

