     * first name, last name, or email contain the filter string (case‑insensitive).
     */
    public Collection<ClientTO> findAllClients(String filter, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to list all clients.");
        }
        if (filter == null || filter.trim().isEmpty()) {
            return clients.values();
        }
        String lower = filter.toLowerCase();
        List<ClientTO> result = new ArrayList<>();
        for (ClientTO c : clients.values()) {
            if (containsIgnoreCase(c.getFirstName(), lower) ||
                containsIgnoreCase(c.getLastName(), lower) ||
                containsIgnoreCase(c.getEmail(), lower)) {
                result.add(c);
            }
        }
        return result;
    }

