     * Searches clients by first or last name (case‑insensitive).
     * @throws IllegalArgumentException if name is null or empty.
     */
    public Collection<ClientTO> findClientsByName(String name, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to search clients by name.");
        }
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty.");
        }
        String lower = name.toLowerCase();
        List<ClientTO> result = new ArrayList<>();
        for (ClientTO c : clients.values()) {
            if (containsIgnoreCase(c.getFirstName(), lower) ||
                containsIgnoreCase(c.getLastName(), lower)) {
                result.add(c);
            }
        }
        return result;
    }

