public class PaginationProcessor<T> {
    private final List<T> dataset;
    private final int defaultPageSize;

    public PaginationProcessor(List<T> dataset, int defaultPageSize) {
        this.dataset = dataset != null ? dataset : Collections.emptyList();
        this.defaultPageSize = defaultPageSize > 0 ? defaultPageSize : 10;
    }

    public PaginationResult<T> getPaginatedData(int pageNumber, int itemsPerPage) {
        int perPage = itemsPerPage > 0 ? itemsPerPage : defaultPageSize;
        int totalItems = dataset.size();
        int totalPages = (int) Math.ceil((double) totalItems / perPage);

        if (pageNumber < 1) pageNumber = 1;
        if (pageNumber > totalPages) pageNumber = totalPages;

        int startIndex = (pageNumber - 1) * perPage;
        int endIndex = Math.min(startIndex + perPage, totalItems);

        List<T> pageData = startIndex < totalItems
                ? dataset.subList(startIndex, endIndex)
                : Collections.emptyList();

        return new PaginationResult<>(pageData, pageNumber, perPage, totalPages, totalItems);
    }

    public static class PaginationResult<T> {
        private final List<T> data;
        private final int currentPage;
        private final int itemsPerPage;
        private final int totalPages;
        private final int totalItems;

        public PaginationResult(List<T> data, int currentPage, int itemsPerPage, int totalPages, int totalItems) {
            this.data = data;
            this.currentPage = currentPage;
            this.itemsPerPage = itemsPerPage;
            this.totalPages = totalPages;
            this.totalItems = totalItems;
        }

        public List<T> getData() {
            return data;
        }

        public int getCurrentPage() {
            return currentPage;
        }

        public int getItemsPerPage() {
            return itemsPerPage;
        }

        public int getTotalPages() {
            return totalPages;
        }

        public int getTotalItems() {
            return totalItems;
        }

        @Override
        public String toString() {
            return "PaginationResult{" +
                    "data=" + data +
                    ", currentPage=" + currentPage +
                    ", itemsPerPage=" + itemsPerPage +
                    ", totalPages=" + totalPages +
                    ", totalItems=" + totalItems +
                    '}';
        }
    }
}

