import java.util.Collections;
import java.util.List;

/**
 * Generic pagination processor that can paginate any type of dataset.
 *
 * @param <T> the type of elements in the dataset
 */
public class PaginationProcessor<T> {

    private final List<T> dataset;
    private final int defaultPageSize;

    /**
     * Creates a new PaginationProcessor.
     *
     * @param dataset        the dataset to paginate; if {@code null} an empty list is used
     * @param defaultPageSize the default number of items per page; must be greater than 0
     * @throws IllegalArgumentException if {@code defaultPageSize} is less than 1
     */
    public PaginationProcessor(List<T> dataset, int defaultPageSize) {
        if (defaultPageSize < 1) {
            throw new IllegalArgumentException("defaultPageSize must be greater than 0");
        }
        this.dataset = dataset != null ? dataset : Collections.emptyList();
        this.defaultPageSize = defaultPageSize;
    }

    /**
     * Returns a paginated view of the dataset.
     *
     * @param pageNumber   the 1‑based page number; must be greater than 0
     * @param itemsPerPage the number of items per page; if {@code null} the default page size is used
     * @return a {@link PaginationResult} containing the page data and metadata
     * @throws IllegalArgumentException if {@code pageNumber} is less than 1 or if {@code itemsPerPage}
     *                                  is not {@code null} and less than 1
     */
    public PaginationResult<T> getPaginatedData(int pageNumber, Integer itemsPerPage) {
        if (pageNumber < 1) {
            throw new IllegalArgumentException("pageNumber must be greater than 0");
        }

        int perPage = (itemsPerPage != null) ? itemsPerPage : defaultPageSize;

        if (itemsPerPage != null && itemsPerPage < 1) {
            throw new IllegalArgumentException("itemsPerPage must be greater than 0");
        }

        int totalItems = dataset.size();
        int totalPages = (int) Math.ceil((double) totalItems / perPage);

        // Clamp pageNumber to the valid range
        int currentPage = Math.min(Math.max(pageNumber, 1), Math.max(totalPages, 1));

        int startIndex = (currentPage - 1) * perPage;
        int endIndex = Math.min(startIndex + perPage, totalItems);

        List<T> pageData = (startIndex < totalItems)
                ? dataset.subList(startIndex, endIndex)
                : Collections.emptyList();

        return new PaginationResult<>(pageData, currentPage, perPage, totalPages, totalItems);
    }

    /**
