        this.outputNormalizationParams = outputNormalizationParams;
    }

    /**
     * Performs a forward pass through a simple feed‑forward neural network with one hidden layer.
     * Input is first normalized to [-1, 1] using min‑max scaling, then passed through the network.
     *
     * @param input double array of length inputSize
     * @return double array of length outputSize
     */
    public double[] calculate(double[] input) {
        if (input == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        if (input.length != inputSize) {
            throw new IllegalArgumentException(
                "Input array length must be " + inputSize + ", but got " + input.length);
        }

        // Normalize input to [-1, 1]
        double[] normInput = normalizeInput(input);

        // Compute hidden layer activations
        double[] hidden = new double[hiddenSize];
        int offset = 0;
        for (int h = 0; h < hiddenSize; h++) {
            double sum = 0.0;
            for (int i = 0; i < inputSize; i++) {
                sum += normInput[i] * weights[offset++];
            }
            hidden[h] = sigmoid(sum);
        }

        // Compute output layer (linear)
        double[] rawOutput = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double sum = 0.0;
            for (int h = 0; h < hiddenSize; h++) {
                sum += hidden[h] * weights[offset++];
            }
            rawOutput[o] = sum;
        }

        // Denormalize output
        double[] output = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double mean = outputNormalizationParams[o][0];
            double std = outputNormalizationParams[o][1];
            output[o] = rawOutput[o] * std + mean;
        }

        return output;
    }

    /**
     * Min‑max normalizes each input value to the range [-1, 1].
     *
     * @param input original input array
     * @return normalized array
     */
    private double[] normalizeInput(double[] input) {
        double[] normalized = new double[inputSize];
        for (int i = 0; i < inputSize; i++) {
            double min = inputNormalizationParams[i][0];
            double max = inputNormalizationParams[i][1];
            if (max == min) {
                normalized[i] = 0.0; // avoid division by zero
            } else {
                normalized[i] = 2.0 * (input[i] - min) / (max - min) - 1.0;
            }
        }
        return normalized;
    }

    private static double sigmoid(double x) {
        return 1.0 / (1.0 + Math.exp(-x));
    }
}

