    private final int inputSize;
    private final int hiddenSize;
    private final int outputSize;
    private final double[] weights;                     // [bias, w1, w2, …] for each hidden neuron, then output weights
    private final double[][] inputNormalizationParams;   // [min, max] for each input feature
    private final double[][] outputNormalizationParams;  // [mean, std] for each output

    public NeuralNetworkCalculator(int inputSize, int hiddenSize, int outputSize,
                                   double[] weights,
                                   double[][] inputNormalizationParams,
                                   double[][] outputNormalizationParams) {
        if (weights == null || inputNormalizationParams == null || outputNormalizationParams == null) {
            throw new IllegalArgumentException("Weights and normalization parameters cannot be null");
        }
        int expectedWeights = hiddenSize * (1 + inputSize) + hiddenSize * outputSize;
        if (weights.length != expectedWeights) {
            throw new IllegalArgumentException(
                "Weights array length must be hiddenSize*(1+inputSize) + hiddenSize*outputSize");
        }
        if (inputNormalizationParams.length != inputSize) {
            throw new IllegalArgumentException("Input normalization params length must match inputSize");
        }
        if (outputNormalizationParams.length != outputSize) {
            throw new IllegalArgumentException("Output normalization params length must match outputSize");
        }
        this.inputSize = inputSize;
        this.hiddenSize = hiddenSize;
        this.outputSize = outputSize;
        this.weights = weights;
        this.inputNormalizationParams = inputNormalizationParams;
        this.outputNormalizationParams = outputNormalizationParams;
    }

    /**
     * Forward pass through the network.
     *
     * @param input double array of length inputSize
     * @return double array of length outputSize
     */
    public double[] calculate(double[] input) {
        if (input == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        if (input.length != inputSize) {
            throw new IllegalArgumentException(
                "Input array length must be " + inputSize + ", but got " + input.length);
        }

        // Normalize input to [-1, 1]
        double[] normInput = normalizeInput(input);

        // Compute hidden layer outputs with tanh activation
        double[] hidden = new double[hiddenSize];
        int offset = 0;
        for (int h = 0; h < hiddenSize; h++) {
            double sum = weights[offset++]; // bias
            for (int i = 0; i < inputSize; i++) {
                sum += normInput[i] * weights[offset++];
            }
            hidden[h] = tanhActivation(sum);
        }

        // Compute output layer (linear)
        double[] rawOutput = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double sum = 0.0;
            for (int h = 0; h < hiddenSize; h++) {
                sum += hidden[h] * weights[offset++];
            }
            rawOutput[o] = sum;
        }

        // Denormalize output
        double[] output = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double mean = outputNormalizationParams[o][0];
            double std = outputNormalizationParams[o][1];
            output[o] = rawOutput[o] * std + mean;
        }

        return output;
    }

    /**
     * Min‑max normalizes each input value to the range [-1, 1].
     *
     * @param input original input array
     * @return normalized array
     */
    private double[] normalizeInput(double[] input) {
        double[] normalized = new double[inputSize];
        for (int i = 0; i < inputSize; i++) {
            double min = inputNormalizationParams[i][0];
            double max = inputNormalizationParams[i][1];
            if (max == min) {
                normalized[i] = 0.0; // avoid division by zero
            } else {
                normalized[i] = 2.0 * (input[i] - min) / (max - min) - 1.0;
            }
        }
        return normalized;
    }

    /**
     * Hyperbolic tangent activation function.
     *
     * @param x weighted sum
     * @return tanh(x)
     */
    private double tanhActivation(double x) {
        return Math.tanh(x);
    }
}

