import java.util.*;

class MinesweeperSolver {
    private char[][] map;
    private boolean[][] visited;
    private final int[] dirR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private final int[] dirC = {-1, 0, 1, -1, 1, -1, 0, 1};

    /**
     * Calculates the minimum number of clicks required to reveal all safe cells.
     * Each safe cell must be clicked individually (no auto‑reveal).
     *
     * @param boardSize     the size of the board (boardSize x boardSize)
     * @param minePositions a list of strings in the form "row,column" indicating mine locations
     * @return the number of safe cells
     */
    public int solveMinesweeper(int boardSize, List<String> minePositions) {
        // Create a padded board to avoid boundary checks
        map = new char[boardSize + 2][boardSize + 2];
        visited = new boolean[boardSize + 2][boardSize + 2];

        // Initialize all cells as safe
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                map[i][j] = '.';
            }
        }

        // Place mines
        for (String pos : minePositions) {
            String[] parts = pos.split(",");
            int r = Integer.parseInt(parts[0].trim());
            int c = Integer.parseInt(parts[1].trim());
            if (r >= 1 && r <= boardSize && c >= 1 && c <= boardSize) {
                map[r][c] = '*';
            }
        }

        // Count safe cells
        int safeCells = 0;
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] != '*') {
                    safeCells++;
                }
            }
        }
        return safeCells;
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int boardSize = sc.nextInt();      // board size
        int mineCount = sc.nextInt();      // number of mines
        List<String> mines = new ArrayList<>();
        for (int i = 0; i < mineCount; i++) {
            int r = sc.nextInt();
            int c = sc.nextInt();
            mines.add(r + "," + c);
        }
        MinesweeperSolver solver = new MinesweeperSolver();
        int result = solver.solveMinesweeper(boardSize, mines);
        System.out.println(result);
    }
}

