import java.math.BigDecimal;
import java.math.RoundingMode;

class TaxPriceCalculator {

    public static BigDecimal[] calculatePriceAndTax(BigDecimal totalAmount, BigDecimal taxRate, boolean isTaxIncluded) {
        BigDecimal price;
        BigDecimal tax;

        // Convert tax rate to a decimal fraction (e.g., 10% -> 0.10)
        BigDecimal taxFraction = taxRate.divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP);

        if (isTaxIncluded) {
            // When tax is already included in the total amount
            BigDecimal divisor = BigDecimal.ONE.add(taxFraction);
            price = totalAmount.divide(divisor, 10, RoundingMode.HALF_UP);
            tax = totalAmount.subtract(price);
        } else {
            // When tax is not included in the total amount
            price = totalAmount;
            tax = totalAmount.multiply(taxFraction);
        }

        return new BigDecimal[]{price, tax};
    }
}

