class TaxPriceCalculator {

    /**
     * Calculates the price and tax amounts based on the total amount, tax rate, and whether the tax is already included.
     *
     * @param totalAmount   The total amount (price + tax if tax is included, otherwise just the price).
     * @param taxRate       The tax rate as a percentage (e.g., 10 for 10%).
     * @param isTaxIncluded If true, the totalAmount already contains tax; otherwise, tax is added on top.
     * @return A BigDecimal array where index 0 is the price amount and index 1 is the tax amount,
     *         both rounded to exactly 2 decimal places using HALF_UP rounding.
     * @throws IllegalArgumentException if totalAmount or taxRate is null, or if either is negative.
     */
    public static BigDecimal[] calculatePriceAndTax(BigDecimal totalAmount, BigDecimal taxRate, boolean isTaxIncluded) {
        // Input validation
        if (totalAmount == null) {
            throw new IllegalArgumentException("totalAmount must not be null");
        }
        if (taxRate == null) {
            throw new IllegalArgumentException("taxRate must not be null");
        }
        if (totalAmount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("totalAmount must not be negative");
        }
        if (taxRate.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("taxRate must not be negative");
        }

        // Convert tax rate to a decimal fraction (e.g., 10% -> 0.10) with 10 decimal places.
        BigDecimal taxFraction = taxRate.divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);

        BigDecimal price;
        BigDecimal tax;

        if (isTaxIncluded) {
            // When tax is already included in the total amount.
            BigDecimal divisor = BigDecimal.ONE.add(taxFraction); // 1 + taxFraction
            price = totalAmount.divide(divisor, 10, RoundingMode.HALF_UP);
            tax = totalAmount.subtract(price); // tax = total - price
        } else {
            // When tax is not included in the total amount.
            price = totalAmount;
            tax = totalAmount.multiply(taxFraction).setScale(10, RoundingMode.HALF_UP);
        }

        // Round final results to exactly 2 decimal places.
        price = price.setScale(2, RoundingMode.HALF_UP);
        tax = tax.setScale(2, RoundingMode.HALF_UP);

        return new BigDecimal[]{price, tax};
    }
}

