/**
 * Simple 3D vector class with x, y, z components and basic vector operations.
 */
class Vector3 {

    private double x;
    private double y;
    private double z;

    /** Default constructor initializes to (0,0,0) */
    public Vector3() {
        this.x = 0.0;
        this.y = 0.0;
        this.z = 0.0;
    }

    /** Parameterized constructor */
    public Vector3(double x, double y, double z) {
        this.x = x;
        this.y = y;
        this.z = z;
    }

    /** Get X component */
    public double getX() {
        return x;
    }

    /** Set X component */
    public void setX(double x) {
        this.x = x;
    }

    /** Get Y component */
    public double getY() {
        return y;
    }

    /** Set Y component */
    public void setY(double y) {
        this.y = y;
    }

    /** Get Z component */
    public double getZ() {
        return z;
    }

    /** Set Z component */
    public void setZ(double z) {
        this.z = z;
    }

    /**
     * Returns the length (magnitude) of the vector.
     *
     * @return Euclidean length of the vector.
     */
    public double length() {
        return Math.sqrt(x * x + y * y + z * z);
    }

    /**
     * Returns a new vector that is the normalized (unit) vector of this vector.
     *
     * @return Normalized vector.
     */
    public Vector3 normalized() {
        double len = length();
        if (len == 0) {
            return new Vector3(0, 0, 0);
        }
        return new Vector3(x / len, y / len, z / len);
    }

    /**
     * Computes the dot product of this vector with another vector.
     *
     * @param other The other vector.
     * @return Dot product.
     */
    public double dot(Vector3 other) {
        return this.x * other.x + this.y * other.y + this.z * other.z;
    }

    /**
     * Subtracts another vector from this vector and returns the result.
     *
     * @param other The vector to subtract.
     * @return Resulting vector after subtraction.
     */
    public Vector3 sub(Vector3 other) {
        return new Vector3(this.x - other.x, this.y - other.y, this.z - other.z);
    }
}

