public class EnhancedSpotLight {

    private PointLight pointLight;
    private Vector3 direction;
    private double cutoff;          // in degrees, 0 <= cutoff <= 90
    private double outerCutoff;     // in degrees, 0 <= outerCutoff <= 90, outerCutoff > cutoff
    private double falloffExponent; // must be > 0

    /** Default constructor with valid default values */
    public EnhancedSpotLight() {
        this.pointLight = new PointLight();
        this.direction = new Vector3();
        this.cutoff = 0.0;
        this.outerCutoff = 90.0;
        this.falloffExponent = 1.0;
    }

    /** Parameterized constructor with validation */
    public EnhancedSpotLight(PointLight pointLight, Vector3 direction,
                             double cutoff, double outerCutoff, double falloffExponent) {
        setPointLight(pointLight);
        setDirection(direction);
        setCutoff(cutoff);
        setOuterCutoff(outerCutoff);
        setFalloffExponent(falloffExponent);
    }

    /** Get the underlying point light */
    public PointLight getPointLight() {
        return pointLight;
    }

    /** Set the underlying point light (must not be null) */
    public void setPointLight(PointLight pointLight) {
        if (pointLight == null) {
            throw new IllegalArgumentException("pointLight cannot be null");
        }
        this.pointLight = pointLight;
    }

    /** Get the direction of the spotlight */
    public Vector3 getDirection() {
        return direction;
    }

    /** Set the direction of the spotlight (must not be null) */
    public void setDirection(Vector3 direction) {
        if (direction == null) {
            throw new IllegalArgumentException("direction cannot be null");
        }
        this.direction = direction;
    }

    /** Get the cutoff angle of the spotlight */
    public double getCutoff() {
        return cutoff;
    }

    /** Set the cutoff angle (must be between 0 and 90 degrees) */
    public void setCutoff(double cutoff) {
        if (cutoff < 0.0 || cutoff > 90.0) {
            throw new IllegalArgumentException("cutoff must be between 0 and 90 degrees");
        }
        if (this.outerCutoff > 0 && cutoff >= this.outerCutoff) {
            throw new IllegalArgumentException("cutoff must be less than outerCutoff");
        }
        this.cutoff = cutoff;
    }

    /** Get the outer cutoff angle of the spotlight */
    public double getOuterCutoff() {
        return outerCutoff;
    }

    /** Set the outer cutoff angle (must be between 0 and 90 degrees and greater than cutoff) */
    public void setOuterCutoff(double outerCutoff) {
        if (outerCutoff < 0.0 || outerCutoff > 90.0) {
            throw new IllegalArgumentException("outerCutoff must be between 0 and 90 degrees");
        }
        if (outerCutoff <= this.cutoff) {
            throw new IllegalArgumentException("outerCutoff must be greater than cutoff");
        }
        this.outerCutoff = outerCutoff;
    }

    /** Get the falloff exponent of the spotlight */
    public double getFalloffExponent() {
        return falloffExponent;
    }

    /** Set the falloff exponent (must be positive) */
    public void setFalloffExponent(double falloffExponent) {
        if (falloffExponent <= 0.0) {
            throw new IllegalArgumentException("falloffExponent must be positive");
        }
        this.falloffExponent = falloffExponent;
    }

    /**
     * Calculates the intensity of the light at a given point.
     * This basic implementation ignores the point and always returns 1.0.
     *
     * @param point The point at which to calculate intensity.
     * @return Fixed intensity value 1.0.
     */
    public double calculateIntensity(Vector3 point) {
        return 1.0;
    }
}

