    /**
     * Calculates the intensity of the light at a given point.
     * Uses angular attenuation based on the spotlight's direction,
     * inner and outer cutoff angles, and a smooth transition defined
     * by the falloff exponent. Distance attenuation is also applied
     * using the point light's constant, linear, and exponent coefficients.
     *
     * @param point The point at which to calculate intensity.
     * @return The attenuated intensity value.
     */
    public double calculateIntensity(Vector3 point) {
        // Vector from light position to the point
        Vector3 lightPos = pointLight.getPosition();
        Vector3 toPoint = point.sub(lightPos);
        double distance = toPoint.length();
        Vector3 toPointNorm = toPoint.normalized();

        // Normalized spotlight direction
        Vector3 dirNorm = direction.normalized();

        // Cosine of the angle between direction and toPoint
        double cosTheta = toPointNorm.dot(dirNorm);

        // Convert cutoff angles to radians and compute their cosines
        double cutoffRad = Math.toRadians(cutoff);
        double outerCutoffRad = Math.toRadians(outerCutoff);
        double cosCutoff = Math.cos(cutoffRad);
        double cosOuter = Math.cos(outerCutoffRad);

        double angularAttenuation;
        if (cosTheta >= cosCutoff) {
            angularAttenuation = 1.0;
        } else if (cosTheta <= cosOuter) {
            angularAttenuation = 0.0;
        } else {
            double factor = (cosTheta - cosOuter) / (cosCutoff - cosOuter);
            angularAttenuation = Math.pow(factor, falloffExponent);
        }

        // Distance attenuation using constant, linear, and exponent coefficients
        double denom = pointLight.getConstantAttenuation()
                + pointLight.getLinearAttenuation() * distance
                + pointLight.getExponentAttenuation() * distance * distance;
        double distanceAttenuation = denom > 0.0 ? 1.0 / denom : 0.0;

        // Final intensity is the base intensity multiplied by both attenuations
        return pointLight.getIntensity() * angularAttenuation * distanceAttenuation;
    }
