/**
 * Stores basic information about a player.
 */
class PlayerInfo {
    private final String id;
    private int score;

    public PlayerInfo(String id, int score) {
        this.id = id;
        this.score = score;
    }

    public String getId() {
        return id;
    }

    public int getScore() {
        return score;
    }

    public void setScore(int score) {
        this.score = score;
    }

    @Override
    public String toString() {
        return "PlayerInfo{id='" + id + "', score=" + score + '}';
    }
}

/**
 * Manages player registrations using a map to ensure unique IDs.
 */
class PlayerManager {
    private final Map<String, PlayerInfo> players = new HashMap<>();

    /**
     * Registers a new player.
     *
     * @param id    the unique player ID
     * @param score the initial score
     * @return true if registration succeeded, false if the ID already exists
     */
    public boolean registerPlayer(String id, int score) {
        if (players.containsKey(id)) {
            return false; // Duplicate ID, reject registration
        }
        players.put(id, new PlayerInfo(id, score));
        return true;
    }

    /**
     * Retrieves a player by ID.
     *
     * @param id the player ID
     * @return the PlayerInfo object, or null if not found
     */
    public PlayerInfo getPlayer(String id) {
        return players.get(id);
    }

    /**
     * Returns the total number of registered players.
     *
     * @return the size of the player map
     */
    public int getPlayerCount() {
        return players.size();
    }
}

/**
 * Demonstrates the player management system.
 */
public class Main {
    public static void main(String[] args) {
        PlayerManager manager = new PlayerManager();

        // Successful registration
        boolean first = manager.registerPlayer("player1", 150);
        System.out.println("Register player1: " + first); // true

        // Attempt to register the same ID again
        boolean second = manager.registerPlayer("player1", 200);
        System.out.println("Register player1 again: " + second); // false

        // Register another unique player
        boolean third = manager.registerPlayer("player2", 300);
        System.out.println("Register player2: " + third); // true

        // Display registered players
        System.out.println("Total players: " + manager.getPlayerCount());
        System.out.println(manager.getPlayer("player1"));
        System.out.println(manager.getPlayer("player2"));
    }
}

