import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * Stores basic information about a player.
 */
class PlayerInfo {
    private final String id;
    private int score;
    private boolean active;

    public PlayerInfo(String id, int score) {
        this.id = id;
        this.score = score;
        this.active = true;
    }

    public String getId() {
        return id;
    }

    public int getScore() {
        return score;
    }

    public boolean isActive() {
        return active;
    }

    public void setScore(int score) {
        this.score = score;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    @Override
    public String toString() {
        return "PlayerInfo{id='" + id + "', score=" + score + ", active=" + active + '}';
    }
}

/**
 * Manages player registrations using a thread‑safe map and queue.
 */
class PlayerManager {
    // Thread‑safe map for storing players
    private final ConcurrentMap<String, PlayerInfo> players = new ConcurrentHashMap<>();
    // Queue of active player IDs
    private final ConcurrentLinkedQueue<String> activeQueue = new ConcurrentLinkedQueue<>();

    /**
     * Registers a new player.
     *
     * @param id    the unique player ID
     * @param score the initial score
     * @return true if registration succeeded, false if the ID already exists
     */
    public synchronized boolean registerPlayer(String id, int score) {
        if (players.containsKey(id)) {
            return false; // Duplicate ID, reject registration
        }
        PlayerInfo p = new PlayerInfo(id, score);
        players.put(id, p);
        activeQueue.add(id);
        return true;
    }

    /**
     * Removes a player by marking them inactive and removing from the queue.
     *
     * @param id the player ID
     * @return true if removal succeeded, false if player does not exist or already inactive
     */
    public synchronized boolean removePlayer(String id) {
        PlayerInfo p = players.get(id);
        if (p == null || !p.isActive()) {
            return false;
        }
        p.setActive(false);
        activeQueue.remove(id); // O(n) but acceptable for small queues
        return true;
    }

    /**
     * Updates the score of an existing active player.
     *
     * @param id    the player ID
     * @param delta the amount to add (can be negative)
     * @return true if update succeeded, false if player does not exist or is inactive
     */
    public synchronized boolean updateScore(String id, int delta) {
        PlayerInfo p = players.get(id);
        if (p == null || !p.isActive()) {
            return false;
        }
        p.setScore(p.getScore() + delta);
        return true;
    }

    /**
     * Retrieves a player by ID.
     *
     * @param id the player ID
     * @return the PlayerInfo object, or null if not found
     */
    public PlayerInfo getPlayer(String id) {
        return players.get(id);
    }

    /**
     * Returns the total number of registered players.
     *
     * @return the size of the player map
     */
    public int getPlayerCount() {
        return players.size();
    }

    /**
     * Returns the number of active players.
     *
     * @return the size of the active queue
     */
    public int getActivePlayerCount() {
        return activeQueue.size();
    }
}

/**
 * Demonstrates the thread‑safe player management system.
 */
public class Main {
    public static void main(String[] args) {
        PlayerManager manager = new PlayerManager();

        // Register players
        manager.registerPlayer("player1", 150);
        manager.registerPlayer("player2", 200);
        manager.registerPlayer("player3", 300);

        System.out.println("Total players: " + manager.getPlayerCount());          // 3
        System.out.println("Active players: " + manager.getActivePlayerCount());   // 3

        // Update scores
        manager.updateScore("player1", 50);   // +50
        manager.updateScore("player2", -30);  // -30

        System.out.println(manager.getPlayer("player1")); // score 200
        System.out.println(manager.getPlayer("player2")); // score 170

        // Remove a player
        manager.removePlayer("player2");

        System.out.println("After removal:");
        System.out.println("Active players: " + manager.getActivePlayerCount());   // 2
        System.out.println(manager.getPlayer("player2")); // still exists but inactive

        // Attempt to update removed player
        boolean updated = manager.updateScore("player2", 10);
        System.out.println("Update removed player: " + updated); // false
    }
}

