    private void checkForDuplicates(List<T> data) {
        Set<T> seen = new HashSet<>();
        for (T element : data) {
            if (!seen.add(element)) {
                throw new IllegalArgumentException("Duplicate elements found: " + element);
            }
        }
    }
}
