     *
     * @param username the desired username
     * @param password the desired password
     * @return RegistrationResult indicating success or failure with a message
     */
    public RegistrationResult registerUser(String username, String password) {
        if (username == null || password == null) {
            return new RegistrationResult(false, "Username and password must not be null.");
        }

        // Validate password length
        PasswordValidator validator = new PasswordValidator();
        if (!validator.validate(password)) {
            return new RegistrationResult(false, "Password must be at least 8 characters long.");
        }

        if (userCredentials.containsKey(username)) {
            return new RegistrationResult(false, "Username already exists.");
        }

        userCredentials.put(username, password);
        return new RegistrationResult(true, "User registered successfully.");
    }

    /**
     * Authenticates an existing user.
     *
     * @param username the username to authenticate
     * @param password the password to verify
     * @return AuthenticationResult indicating success or failure with a message
