import java.util.*;

/**
 * A simple deterministic finite automaton (DFA) implementation.
 *
 * <p>Usage example:
 * <pre>
 *     DFA dfa = new DFA();
 *     State q0 = new State("q0");
 *     State q1 = new State("q1");
 *     dfa.addState(q0);          // first added state becomes the initial state
 *     dfa.addState(q1);
 *     dfa.addTransition(q0, 'a', q1);
 *     dfa.addTransition(q1, 'b', q0);
 *     dfa.setFinalState(q1);
 *
 *     System.out.println(dfa.accepts("ab"));   // true
 *     System.out.println(dfa.accepts("a"));    // false
 * </pre>
 */
public class DFA {

    /** All states in the DFA, indexed by name for quick lookup. */
    private final Map<String, State> states = new LinkedHashMap<>();

    /** The initial state (the first state added). */
    private State initialState = null;

    /**
     * Adds a state to the DFA. The first state added becomes the initial state.
     *
     * @param state the state to add
     */
    public void addState(State state) {
        if (state == null) throw new IllegalArgumentException("State cannot be null");
        if (states.containsKey(state.getName())) {
            throw new IllegalArgumentException("State with name '" + state.getName() + "' already exists");
        }
        states.put(state.getName(), state);
        if (initialState == null) {
            initialState = state;
        }
    }

    /**
     * Adds a transition from one state to another on a given input symbol.
     *
     * @param from   the source state
     * @param symbol the input symbol
     * @param to     the target state
     */
    public void addTransition(State from, char symbol, State to) {
        if (from == null || to == null) {
            throw new IllegalArgumentException("States cannot be null");
        }
        from.addTransition(symbol, to);
    }

    /**
     * Marks a state as an accepting (final) state.
     *
     * @param state the state to mark
     */
    public void setFinalState(State state) {
        if (state == null) throw new IllegalArgumentException("State cannot be null");
        state.setFinal(true);
    }

    /**
     * Simulates the DFA on the given input string.
     *
     * @param input the input string
     * @return true if the DFA accepts the string, false otherwise
     */
    public boolean accepts(String input) {
        if (initialState == null) {
            throw new IllegalStateException("DFA has no states");
        }
        State current = initialState;
        for (char c : input.toCharArray()) {
            current = current.getNextState(c);
            if (current == null) {
                return false; // no valid transition
            }
        }
        return current.isFinal();
    }

    /**
     * Retrieves a state by its name.
     *
     * @param name the state's name
     * @return the state, or null if not found
     */
    public State getState(String name) {
        return states.get(name);
    }

    /**
     * Simple representation of a DFA state.
     */
    public static class State {
        private final String name;
        private final Map<Character, State> transitions = new HashMap<>();
        private boolean isFinal = false;

        public State(String name) {
            if (name == null || name.isEmpty()) {
                throw new IllegalArgumentException("State name cannot be null or empty");
            }
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public void addTransition(char symbol, State target) {
            if (target == null) {
                throw new IllegalArgumentException("Target state cannot be null");
            }
            transitions.put(symbol, target);
        }

        public State getNextState(char symbol) {
            return transitions.get(symbol);
        }

        public boolean isFinal() {
            return isFinal;
        }

        public void setFinal(boolean isFinal) {
            this.isFinal = isFinal;
        }

        @Override
        public String toString() {
            return "State{" +
                    "name='" + name + '\'' +
                    ", isFinal=" + isFinal +
                    '}';
        }
    }

    // Example usage
    public static void main(String[] args) {
        DFA dfa = new DFA();

        State q0 = new State("q0");
        State q1 = new State("q1");
        State q2 = new State("q2");

        dfa.addState(q0);
        dfa.addState(q1);
        dfa.addState(q2);

        dfa.addTransition(q0, 'a', q1);
        dfa.addTransition(q1, 'b', q2);
        dfa.addTransition(q2, 'c', q0);

        dfa.setFinalState(q2);

        String[] tests = {"abc", "ab", "abcabc", "a", "abcabcabc"};
        for (String test : tests) {
            System.out.printf("Input \"%s\" accepted? %b%n", test, dfa.accepts(test));
        }
    }
}

