import java.util.HashMap;
import java.util.Map;
import java.util.Set;

class RegionTextureManager {
    private Map<String, TexturePack> regionPacks = new HashMap<>();
    private TexturePack defaultPack;

    public RegionTextureManager(TexturePack defaultPack) {
        this.defaultPack = defaultPack;
    }

    /** Associate a texture pack with a region. */
    public void addRegionPack(String regionId, TexturePack pack) {
        regionPacks.put(regionId, pack);
    }

    /** Remove the association for a region. */
    public void removeRegionPack(String regionId) {
        regionPacks.remove(regionId);
    }

    /** Retrieve the texture pack for a region, falling back to the default pack if none is set. */
    public TexturePack getPackForRegion(String regionId) {
        return regionPacks.getOrDefault(regionId, defaultPack);
    }

    /** Get all region identifiers that have a custom pack. */
    public Set<String> getAllRegionIds() {
        return regionPacks.keySet();
    }

    /** Get a copy of the mapping from region IDs to texture packs. */
    public Map<String, TexturePack> getAllRegionPacks() {
        return new HashMap<>(regionPacks);
    }
}

class TexturePack {
    private String name;
    private boolean isCustom;

    public TexturePack(String name, boolean isCustom) {
        this.name = name;
        this.isCustom = isCustom;
    }

    public String getName() {
        return name;
    }

    public boolean isCustom() {
        return isCustom;
    }

    @Override
    public String toString() {
        return "TexturePack{name='" + name + "', isCustom=" + isCustom + '}';
    }
}

public class Main {
    public static void main(String[] args) {
        TexturePack defaultPack = new TexturePack("Default", false);
        RegionTextureManager manager = new RegionTextureManager(defaultPack);

        TexturePack desertPack = new TexturePack("Desert", true);
        TexturePack forestPack = new TexturePack("Forest", true);

        manager.addRegionPack("region_desert", desertPack);
        manager.addRegionPack("region_forest", forestPack);

        System.out.println("Pack for region_desert: " + manager.getPackForRegion("region_desert"));
        System.out.println("Pack for region_mountain (no custom): " + manager.getPackForRegion("region_mountain"));

        manager.removeRegionPack("region_forest");
        System.out.println("After removal, pack for region_forest: " + manager.getPackForRegion("region_forest"));
    }
}

