    private final TexturePack defaultPack;
    private final Set<String> excludedPlayers = new HashSet<>();
    private final Map<String, String> playerRegions = new HashMap<>();

    public RegionTextureManager(TexturePack defaultPack) {
        this.defaultPack = defaultPack;
    }

    /** Associate a texture pack with a region. */
    public void addRegionPack(String regionId, TexturePack pack) {
        regionPacks.put(regionId, pack);
    }

    /** Remove the association for a region. */
    public void removeRegionPack(String regionId) {
