        regionPacks.remove(regionId);
    }

    /** Retrieve the texture pack for a region, falling back to the default pack if none is set. */
    public TexturePack getPackForRegion(String regionId) {
        return regionPacks.getOrDefault(regionId, defaultPack);
    }

    /** Get all region identifiers that have a custom pack. */
    public Set<String> getAllRegionIds() {
        return regionPacks.keySet();
    }

    /** Get a copy of the mapping from region IDs to texture packs. */
    public Map<String, TexturePack> getAllRegionPacks() {
        return new HashMap<>(regionPacks);
    }

    /** Mark or unmark a player as excluded from automatic texture changes. */
    public void setPlayerExcluded(String playerId, boolean excluded) {
        if (excluded) {
            excludedPlayers.add(playerId);
        } else {
            excludedPlayers.remove(playerId);
        }
    }

    /** Check whether a player is excluded. */
    private boolean isExcluded(String playerId) {
        return excludedPlayers.contains(playerId);
    }

    /**
     * Handle a player's movement into a region.
     *
     * @param playerId the identifier of the player
     * @param regionId the identifier of the region the player moves into; may be null
     * @return a message indicating the result of the movement
     */
    public String handlePlayerMovement(String playerId, String regionId) {
        // Resolve previous and new packs
        String prevRegionId = playerRegions.get(playerId); // may be null
        TexturePack prevPack = (prevRegionId == null || !regionPacks.containsKey(prevRegionId))
                ? defaultPack
                : regionPacks.get(prevRegionId);

        TexturePack newPack = (regionId == null || !regionPacks.containsKey(regionId))
                ? defaultPack
                : regionPacks.get(regionId);

        // Detect entering or leaving a custom region
        boolean enteringCustom = !prevPack.isCustom() && newPack.isCustom();
        boolean leavingCustom = prevPack.isCustom() && !newPack.isCustom();

        // Handle exclusion logic
        if (enteringCustom) {
            setPlayerExcluded(playerId, true);
            playerRegions.put(playerId, regionId);
            return String.format("NOTE: Player %s entered custom region and is excluded from automatic changes", playerId);
        }

        if (leavingCustom) {
            // Player remains excluded; no automatic changes are applied
            playerRegions.put(playerId, regionId);
            return String.format("Player %s left custom region - use command to re-enable auto changes", playerId);
        }

        // If player is excluded, no automatic changes are applied
        if (isExcluded(playerId)) {
            playerRegions.put(playerId, regionId);
            return String.format("Player %s is excluded from automatic texture changes", playerId);
        }

        // No change needed if packs are identical
        if (prevPack == newPack) {
            playerRegions.put(playerId, regionId);
            return "No texture change needed - same pack in both regions";
        }

        // Apply new pack
        playerRegions.put(playerId, regionId);
        if (newPack == defaultPack) {
            return String.format("Applied default texture pack to player %s", playerId);
        } else {
            return String.format("Applied texture pack %s to player %s", newPack.getName(), playerId);
        }
    }
}

class TexturePack {
    private final String name;
    private final boolean isCustom;

    public TexturePack(String name, boolean isCustom) {
        this.name = name;
        this.isCustom = isCustom;
    }

    public String getName() {
        return name;
    }

    public boolean isCustom() {
        return isCustom;
    }

    @Override
    public String toString() {
        return "TexturePack{name='" + name + "', isCustom=" + isCustom + '}';
    }
}

public class Main {
    public static void main(String[] args) {
        TexturePack defaultPack = new TexturePack("Default", false);
        RegionTextureManager manager = new RegionTextureManager(defaultPack);

        TexturePack desertPack = new TexturePack("Desert", true);
        TexturePack forestPack = new TexturePack("Forest", true);

        manager.addRegionPack("region_desert", desertPack);
        manager.addRegionPack("region_forest", forestPack);

        // Simulate player movements
        System.out.println(manager.handlePlayerMovement("player1", "region_desert"));   // entering custom region
        System.out.println(manager.handlePlayerMovement("player1", "region_forest"));   // leaving custom region
        System.out.println(manager.handlePlayerMovement("player1", null));             // leaving custom region to default
        System.out.println(manager.handlePlayerMovement("player1", "region_desert"));   // entering custom region again
        System.out.println(manager.handlePlayerMovement("player1", "region_desert"));   // no change
        System.out.println(manager.handlePlayerMovement("player1", null));             // leaving custom region

        // Player not excluded
        System.out.println(manager.handlePlayerMovement("player2", "region_forest"));   // entering custom region
        System.out.println(manager.handlePlayerMovement("player2", "region_forest"));   // no change
        System.out.println(manager.handlePlayerMovement("player2", "region_desert"));   // leaving custom region
        System.out.println(manager.handlePlayerMovement("player2", null));             // leaving custom region

        // Excluded player manually
        manager.setPlayerExcluded("player3", true);
        System.out.println(manager.handlePlayerMovement("player3", "region_desert"));   // excluded
        System.out.println(manager.handlePlayerMovement("player3", null));             // excluded
        manager.setPlayerExcluded("player3", false);
        System.out.println(manager.handlePlayerMovement("player3", "region_desert"));   // entering custom region
    }
}
