        public final int mathResult;
        public final long mathTimeNano;
        public final int binaryResult;
        public final long binaryTimeNano;

        public Result(int dpResult, long dpTimeNano,
                      int mathResult, long mathTimeNano,
                      int binaryResult, long binaryTimeNano) {
            this.dpResult = dpResult;
            this.dpTimeNano = dpTimeNano;
            this.mathResult = mathResult;
            this.mathTimeNano = mathTimeNano;
            this.binaryResult = binaryResult;
            this.binaryTimeNano = binaryTimeNano;
        }
    }

    /**
     * Computes the minimum number of attempts needed to find the critical floor
     * using three different approaches: dynamic programming, mathematical
     * binomial‑coefficient, and binary search with memoization.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return Result object containing all three solutions and their times
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static Result solveEggDrop(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }

        long dpStart = System.nanoTime();
        int dpResult = solveEggDropDP(k, n);
        long dpEnd = System.nanoTime();

        long mathStart = System.nanoTime();
        int mathResult = solveEggDropMath(k, n);
        long mathEnd = System.nanoTime();

        long binaryStart = System.nanoTime();
        int binaryResult = solveEggDropBinary(k, n);
        long binaryEnd = System.nanoTime();

        return new Result(dpResult, dpEnd - dpStart,
                          mathResult, mathEnd - mathStart,
                          binaryResult, binaryEnd - binaryStart);
    }

    /* ---------- Dynamic‑Programming implementation ---------- */

    private static int solveEggDropDP(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        long[] dp = new long[k + 1];
        int moves = 0;

        while (dp[k] < n) {
            moves++;
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
            }
        }
        return moves;
    }

    /* ---------- Mathematical (binomial coefficient) implementation ---------- */

    private static int solveEggDropMath(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        int moves = 0;
        long sum = 0;

        while (sum < n) {
            moves++;
            long binom = 1; // C(moves, 0)
            sum = 0;
            for (int i = 1; i <= k; i++) {
                binom = binom * (moves - i + 1) / i;
                sum += binom;
                if (sum >= n) break;
            }
        }
        return moves;
    }

    /* ---------- Binary search with memoization implementation ---------- */

    private static int solveEggDropBinary(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        Map<Long, Long> memo = new HashMap<>();
        int low = 1;
        int high = n; // worst case: one egg per floor

        while (low < high) {
            int mid = (low + high) >>> 1;
            long floors = computeFloors(k, mid, n, memo);
            if (floors >= n) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    /**
     * Recursively computes the maximum number of floors that can be tested
     * with {@code eggs} eggs and {@code moves} attempts, using memoization.
     * The result is capped at {@code limit} to avoid overflow.
     */
    private static long computeFloors(int eggs, int moves, int limit, Map<Long, Long> memo) {
        if (moves == 0) return 0;
        if (eggs == 1) return moves;

        long key = (((long) eggs) << 32) | moves;
        Long cached = memo.get(key);
        if (cached != null) return cached;

        long res = computeFloors(eggs - 1, moves - 1, limit, memo)
                 + computeFloors(eggs, moves - 1, limit, memo) + 1;

        if (res > limit) res = limit + 1; // cap to avoid overflow
        memo.put(key, res);
        return res;
    }
}

