public class EnhancedTrie {

    private static class TrieNode {
        char value;
        boolean isWord;
        TrieNode[] children;

        TrieNode(char value) {
            this.value = value;
            this.isWord = false;
            this.children = new TrieNode[26]; // supports 'a' to 'z'
        }
    }

    private final TrieNode root;

    public EnhancedTrie() {
        root = new TrieNode('\0'); // root has no character
    }

    /**
     * Inserts a word into the trie.
     *
     * @param item the word to add
     */
    public void add(String item) {
        if (item == null || item.isEmpty()) {
            return;
        }
        TrieNode current = root;
        for (char ch : item.toCharArray()) {
            int idx = ch - 'a';
            if (idx < 0 || idx >= 26) {
                throw new IllegalArgumentException("Only lowercase a-z characters are supported.");
            }
            if (current.children[idx] == null) {
                current.children[idx] = new TrieNode(ch);
            }
            current = current.children[idx];
        }
        current.isWord = true;
    }

    /**
     * Checks whether a word exists in the trie.
     *
     * @param item the word to search for
     * @return true if the word exists, false otherwise
     */
    public boolean contains(String item) {
        if (item == null || item.isEmpty()) {
            return false;
        }
        TrieNode current = root;
        for (char ch : item.toCharArray()) {
            int idx = ch - 'a';
            if (idx < 0 || idx >= 26) {
                return false; // unsupported character
            }
            if (current.children[idx] == null) {
                return false;
            }
            current = current.children[idx];
        }
        return current.isWord;
    }
}

