     */
    public void add(String item) {
        if (item == null || item.isEmpty()) {
            return;
        }
        TrieNode current = root;
        for (char ch : item.toCharArray()) {
            if (!isLowerCaseLetter(ch)) {
                throw new IllegalArgumentException(
                        "Only lowercase a-z characters are supported.");
            }
            TrieNode child = current.getChild(ch);
            if (child == null) {
                child = new TrieNode(ch);
                current.addChild(child);
            }
            current = child;
        }
        current.isWord = true;
    }

    /**
     * Checks whether a word exists in the trie.
     *
     * @param item the word to search for
     * @return true if the word exists, false otherwise
     */
    public boolean contains(String item) {
        if (item == null || item.isEmpty()) {
            return false;
        }
        TrieNode current = root;
        for (char ch : item.toCharArray()) {
            if (!isLowerCaseLetter(ch)) {
                return false; // unsupported character
            }
            TrieNode child = current.getChild(ch);
            if (child == null) {
                return false;
            }
            current = child;
        }
        return current.isWord;
    }

    /** Helper to check if a character is a lowercase letter a-z. */
    private static boolean isLowerCaseLetter(char ch) {
        return ch >= 'a' && ch <= 'z';
    }

    /**
     * Inserts a TrieNode into a sorted array of TrieNodes.
     *
     * @param array   the original sorted array
     * @param element the node to insert
     * @return a new array containing all elements of {@code array} plus {@code element}
     *         in sorted order by {@code value}
     */
    private static TrieNode[] insert(TrieNode[] array, TrieNode element) {
        int idx = 0;
        while (idx < array.length && array[idx].value < element.value) {
            idx++;
        }
        TrieNode[] newArray = new TrieNode[array.length + 1];
        System.arraycopy(array, 0, newArray, 0, idx);
        newArray[idx] = element;
        System.arraycopy(array, idx, newArray, idx + 1, array.length - idx);
        return newArray;
    }
}

