        list.add(new Emoji("😀", "Grinning Face"));
        list.add(new Emoji("😢", "Crying Face"));
        list.add(new Emoji("👍", "Thumbs Up"));
        list.add(new Emoji("❤️", "Red Heart"));
        list.add(new Emoji("🎉", "Party Popper"));
