import java.io.IOException;
import java.nio.file.*;
import java.util.List;

public class FileHandler {

    /**
     * Handles file operations based on the provided operation type.
     *
     * @param operationType the type of operation to perform (e.g., "upload")
     * @param files         the list of files to process
     * @param targetDir     the directory where files should be uploaded
     * @return a message indicating the result of the operation
     */
    public static String handleFileOperation(
            String operationType,
            List<Path> files,
            Path targetDir) {

        if ("upload".equalsIgnoreCase(operationType)) {
            try {
                // Create target directory if it does not exist
                if (!Files.exists(targetDir)) {
                    Files.createDirectories(targetDir);
                }

                int uploadedCount = 0;
                for (Path file : files) {
                    if (Files.isRegularFile(file)) {
                        Path destination = targetDir.resolve(file.getFileName());
                        Files.copy(file, destination, StandardCopyOption.REPLACE_EXISTING);
                        uploadedCount++;
                    }
                }
                return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s") + ".";
            } catch (IOException e) {
                return "Error during upload: " + e.getMessage();
            }
        }

        // For now, only 'upload' is supported
        return "Unsupported operation: " + operationType;
    }

    // Example usage
    public static void main(String[] args) {
        // Example files (replace with actual paths on your system)
        List<Path> files = List.of(
                Paths.get("example1.txt"),
                Paths.get("example2.txt")
        );
        Path targetDir = Paths.get("uploads");

        String result = handleFileOperation("upload", files, targetDir);
        System.out.println(result);
    }
}

