import java.io.IOException;
import java.nio.file.*;
import java.util.List;

public class FileHandler {

    /**
     * Handles file operations based on the provided operation type.
     *
     * @param operationType the type of operation to perform (e.g., "upload" or "download")
     * @param files         the list of files to upload (ignored for download)
     * @param targetDir     the directory where files should be uploaded or from which to download
     * @param fileName      the name of the file to download (ignored for upload)
     * @return a message indicating the result of the operation for upload,
     *         or the file contents as a byte array for download.
     */
    public static Object handleFileOperation(
            String operationType,
            List<Path> files,
            Path targetDir,
            String fileName) {

        if ("upload".equalsIgnoreCase(operationType)) {
            try {
                // Create target directory if it does not exist
                if (!Files.exists(targetDir)) {
                    Files.createDirectories(targetDir);
                }

                int uploadedCount = 0;
                for (Path file : files) {
                    if (Files.isRegularFile(file)) {
                        Path destination = targetDir.resolve(file.getFileName());
                        Files.copy(file, destination, StandardCopyOption.REPLACE_EXISTING);
                        uploadedCount++;
                    }
                }
                return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s") + ".";
            } catch (IOException e) {
                return "Error during upload: " + e.getMessage();
            }
        } else if ("download".equalsIgnoreCase(operationType)) {
            try {
                Path fileToDownload = targetDir.resolve(fileName);
                return Files.readAllBytes(fileToDownload);
            } catch (IOException e) {
                return "Error during download: " + e.getMessage();
            }
        }

        // Unsupported operation
        return "Unsupported operation: " + operationType;
    }

    // Example usage
    public static void main(String[] args) {
        // Example files for upload (replace with actual paths on your system)
        List<Path> filesToUpload = List.of(
                Paths.get("example1.txt"),
                Paths.get("example2.txt")
        );
        Path uploadDir = Paths.get("uploads");

        // Upload operation
        Object uploadResult = handleFileOperation("upload", filesToUpload, uploadDir, null);
        System.out.println(uploadResult); // e.g., "Uploaded 2 files."

        // Download operation
        Object downloadResult = handleFileOperation("download", null, uploadDir, "example1.txt");
        if (downloadResult instanceof byte[]) {
            byte[] content = (byte[]) downloadResult;
            System.out.println("Downloaded file size: " + content.length + " bytes");
        } else {
            System.out.println(downloadResult); // error message if any
        }
    }
}

