import java.nio.file.*;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/**
 * Utility class for handling file operations such as upload, download, and zip.
 */
public class FileHandler {

    /**
     * Routes the requested operation to the appropriate helper method.
     *
     * @param operationType the type of operation ("upload", "download", or "zip")
     * @param files         the list of files to upload or zip (ignored for download)
     * @param targetDir     the directory where files should be uploaded or from which to download
     * @param fileName      the name of the file to download (ignored for upload and zip)
     * @return the result of the operation: a message for upload, a byte array for download or zip
     * @throws IOException              if an I/O error occurs during the operation
     * @throws IllegalArgumentException if the operation type is unsupported
     */
    public static Object handleFileOperation(
            String operationType,
            List<Path> files,
            Path targetDir,
            String fileName) throws IOException {

        switch (operationType.toLowerCase()) {
            case "upload":
                return uploadFiles(files, targetDir);
            case "download":
                return downloadFile(targetDir, fileName);
            case "zip":
                return zipFiles(files);
            default:
                throw new IllegalArgumentException("Unsupported operation: " + operationType);
        }
    }

    // --------------------------------------------------------------------- //
    // Private helper methods
    // --------------------------------------------------------------------- //

    /**
     * Uploads the given files to the target directory.
     *
     * @param files     the files to upload
     * @param targetDir the destination directory
     * @return a message indicating how many files were uploaded
     * @throws IOException if an I/O error occurs
     */
    private static String uploadFiles(List<Path> files, Path targetDir) throws IOException {
        if (!Files.exists(targetDir)) {
            Files.createDirectories(targetDir);
        }

        int uploadedCount = 0;
        for (Path file : files) {
            if (Files.isRegularFile(file)) {
                Path destination = targetDir.resolve(file.getFileName());
                Files.copy(file, destination, StandardCopyOption.REPLACE_EXISTING);
                uploadedCount++;
            }
        }
        return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s") + ".";
    }

    /**
     * Downloads the specified file from the target directory.
     *
     * @param targetDir the directory containing the file
     * @param fileName  the name of the file to download
     * @return the file contents as a byte array
     * @throws IOException if an I/O error occurs
     */
    private static byte[] downloadFile(Path targetDir, String fileName) throws IOException {
        Path fileToDownload = targetDir.resolve(fileName);
        return Files.readAllBytes(fileToDownload);
    }

    /**
     * Creates an in‑memory ZIP archive containing the given files.
     *
     * @param files the files to include in the ZIP
     * @return the ZIP data as a byte array
     * @throws IOException if an I/O error occurs
     */
    private static byte[] zipFiles(List<Path> files) throws IOException {
        if (files == null || files.isEmpty()) {
            throw new IllegalArgumentException("No files to zip.");
        }

        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ZipOutputStream zos = new ZipOutputStream(baos)) {

            for (Path file : files) {
                if (Files.isRegularFile(file)) {
                    ZipEntry entry = new ZipEntry(file.getFileName().toString());
                    zos.putNextEntry(entry);
                    Files.copy(file, zos);
                    zos.closeEntry();
                }
            }
            zos.finish();
            return baos.toByteArray();
        }
    }

    // --------------------------------------------------------------------- //
    // Example usage
    // --------------------------------------------------------------------- //

    public static void main(String[] args) {
        // Replace these paths with actual files on your system
        List<Path> files = List.of(
                Paths.get("example1.txt"),
                Paths.get("example2.txt")
        );
        Path uploadDir = Paths.get("uploads");

        try {
            // Upload operation
            Object uploadResult = handleFileOperation("upload", files, uploadDir, null);
            System.out.println(uploadResult);

            // Download operation
            Object downloadResult = handleFileOperation("download", null, uploadDir, "example1.txt");
            if (downloadResult instanceof byte[]) {
                byte[] content = (byte[]) downloadResult;
                System.out.println("Downloaded file size: " + content.length + " bytes");
            } else {
                System.out.println(downloadResult);
            }

            // Zip operation
            Object zipResult = handleFileOperation("zip", files, null, null);
            if (zipResult instanceof byte[]) {
                byte[] zipData = (byte[]) zipResult;
                System.out.println("Created zip archive of size: " + zipData.length + " bytes");
            } else {
                System.out.println(zipResult);
            }
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        } catch (IllegalArgumentException e) {
            System.err.println("Invalid operation: " + e.getMessage());
        }
    }
}

