/**
 * Interface that all unit tests must implement.
 */
interface UnitTest {
    /**
     * Executes the test logic.
     *
     * @throws Exception if the test fails.
     */
    void runTest() throws Exception;

    /**
     * Returns a human‑readable name for the test.
     *
     * @return the test name.
     */
    String getTestName();
}

/**
 * A simple test runner that keeps a list of UnitTest instances,
 * executes each one, and returns the number of tests that were run.
 */
class UnitTestRunner {
    private final List<UnitTest> tests = new ArrayList<>();

    /**
     * Adds a test to the runner.
     *
     * @param test the UnitTest to add.
     */
    public void addTest(UnitTest test) {
        tests.add(test);
    }

    /**
     * Runs all added tests. Each test's runTest method is invoked.
     * If a test throws an exception, the exception is caught and
     * a message is printed, but the runner continues with the next test.
     *
     * @return the number of tests that were executed.
     */
    public int runAll() {
        int count = 0;
        for (UnitTest test : tests) {
            try {
                test.runTest();
                System.out.println("Test " + test.getTestName() + " passed.");
            } catch (Exception e) {
                System.out.println("Test " + test.getTestName() + " failed: " + e.getMessage());
            }
            count++;
        }
        return count;
    }
}

/**
 * Example test implementation.
 */
class SampleTest implements UnitTest {
    @Override
    public void runTest() throws Exception {
        // Simple assertion: 2 + 2 should equal 4
        if (2 + 2 != 4) {
            throw new Exception("Math error: 2 + 2 != 4");
        }
    }

    @Override
    public String getTestName() {
        return "SampleTest";
    }
}

/**
 * Demonstration of the UnitTestRunner in action.
 */
public class Main {
    public static void main(String[] args) {
        UnitTestRunner runner = new UnitTestRunner();
        runner.addTest(new SampleTest());

        int runCount = runner.runAll();
        System.out.println("Ran " + runCount + " test(s).");
    }
}

