import java.util.*;

public class EnhancedTariffManager {
    private final Map<Integer, Tariff> tariffs = new HashMap<>();
    private final Map<Integer, List<Contract>> contractsByTariff = new HashMap<>();

    /** Adds a new tariff to the system. */
    public void addTariff(Tariff tariff) {
        tariffs.put(tariff.getId(), tariff);
        contractsByTariff.putIfAbsent(tariff.getId(), new ArrayList<>());
    }

    /** Subscribes a contract to an existing tariff. */
    public void subscribeContractToTariff(int tariffId, Contract contract) {
        if (!tariffs.containsKey(tariffId)) {
            System.out.println("Tariff with ID " + tariffId + " does not exist.");
            return;
        }
        contractsByTariff.get(tariffId).add(contract);
    }

    /** Retrieves a tariff by its ID. */
    public Tariff getTariff(int id) {
        return tariffs.get(id);
    }

    /** Retrieves all contracts subscribed to a specific tariff. */
    public List<Contract> getContractsForTariff(int tariffId) {
        return contractsByTariff.getOrDefault(tariffId, Collections.emptyList());
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Tariff tariff : tariffs.values()) {
            sb.append(tariff).append("\n");
            List<Contract> contracts = contractsByTariff.get(tariff.getId());
            if (contracts != null && !contracts.isEmpty()) {
                sb.append("  Contracts:\n");
                for (Contract c : contracts) {
                    sb.append("    ").append(c).append("\n");
                }
            }
        }
        return sb.toString();
    }
}

class Tariff {
    private final int id;
    private final String name;
    private final double monthlyFee;

    public Tariff(int id, String name, double monthlyFee) {
        this.id = id;
        this.name = name;
        this.monthlyFee = monthlyFee;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public double getMonthlyFee() { return monthlyFee; }

    @Override
    public String toString() {
        return "Tariff{id=" + id + ", name='" + name + "', monthlyFee=" + monthlyFee + "}";
    }
}

class Contract {
    private final int id;
    private final String clientName;

    public Contract(int id, String clientName) {
        this.id = id;
        this.clientName = clientName;
    }

    public int getId() { return id; }
    public String getClientName() { return clientName; }

    @Override
    public String toString() {
        return "Contract{id=" + id + ", clientName='" + clientName + "'}";
    }
}

class Main {
    public static void main(String[] args) {
        EnhancedTariffManager manager = new EnhancedTariffManager();

        Tariff t1 = new Tariff(1, "Basic Plan", 9.99);
        Tariff t2 = new Tariff(2, "Premium Plan", 19.99);

        manager.addTariff(t1);
        manager.addTariff(t2);

        Contract c1 = new Contract(101, "Alice");
        Contract c2 = new Contract(102, "Bob");
        Contract c3 = new Contract(103, "Charlie");

        manager.subscribeContractToTariff(1, c1);
        manager.subscribeContractToTariff(1, c2);
        manager.subscribeContractToTariff(2, c3);

        System.out.println(manager);
    }
}

