        if (set == null) {
            throw new IllegalArgumentException("Tariff ID not found: " + tariffId);
        }
        return new HashSet<>(set); // return a copy
    }

    /**
     * Returns the tariff with the highest number of subscribed contracts.
     * @return the most popular tariff, or null if no tariffs exist.
     */
    public Tariff getMostPopularTariff() {
        if (tariffs.isEmpty()) {
            return null;
        }
        Tariff mostPopular = null;
        int maxCount = -1;
        for (Map.Entry<Integer, Tariff> entry : tariffs.entrySet()) {
            int id = entry.getKey();
            int count = contractsByTariff.getOrDefault(id, Collections.emptySet()).size();
            if (count > maxCount) {
                maxCount = count;
                mostPopular = entry.getValue();
