import java.util.*;

public class EnhancedTariffManager {
    // Map of tariff ID to Tariff
    private final Map<Integer, Tariff> tariffs = new HashMap<>();
    // Map of tariff ID to the set of contracts subscribed to that tariff
    private final Map<Integer, Set<Contract>> contractsByTariff = new HashMap<>();

    /** Adds a new tariff to the system. */
    public void addTariff(Tariff tariff) {
        if (tariff == null) {
            throw new IllegalArgumentException("Tariff cannot be null.");
        }
        int id = tariff.getId();
        if (tariffs.containsKey(id)) {
            throw new IllegalArgumentException("Tariff with ID " + id + " already exists.");
        }
        tariffs.put(id, tariff);
        contractsByTariff.put(id, new HashSet<>());
    }

    /** Subscribes a contract to an existing tariff. */
    public void subscribeContractToTariff(int tariffId, Contract contract) {
        if (contract == null) {
            throw new IllegalArgumentException("Contract cannot be null");
        }
        Set<Contract> set = contractsByTariff.get(tariffId);
        if (set == null) {
            throw new IllegalArgumentException("Tariff ID not found: " + tariffId);
        }
        set.add(contract);
    }

    /** Retrieves a tariff by its ID. */
    public Tariff getTariff(int id) {
        return tariffs.get(id);
    }

    /**
     * Returns a copy of the set of contracts associated with the given tariff ID.
     * @throws IllegalArgumentException if the tariff ID does not exist.
     */
    public Set<Contract> getContractsByTariff(int tariffId) {
        Set<Contract> set = contractsByTariff.get(tariffId);
        if (set == null) {
            throw new IllegalArgumentException("Tariff ID not found: " + tariffId);
        }
        return new HashSet<>(set); // return a copy
    }

    /**
     * Returns the tariff with the highest number of subscribed contracts.
     * @return the most popular tariff, or null if no tariffs exist.
     */
    public Tariff getMostPopularTariff() {
        if (tariffs.isEmpty()) {
            return null;
        }
        Tariff mostPopular = null;
        int maxCount = -1;
        for (Map.Entry<Integer, Tariff> entry : tariffs.entrySet()) {
            int id = entry.getKey();
            int count = contractsByTariff.getOrDefault(id, Collections.emptySet()).size();
            if (count > maxCount) {
                maxCount = count;
                mostPopular = entry.getValue();
            }
        }
        return mostPopular;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Tariff tariff : tariffs.values()) {
