public class Company {
    // Singleton instance
    private static Company instance;

    // List of all employees
    private final List<Employee> employees;

    // Counter for assigning unique employee IDs
    private int employeeCounter;

    // The CEO of the company
    private Manager ceo;

    /**
     * Private constructor to prevent external instantiation.
     */
    private Company() {
        this.employees = new ArrayList<>();
        this.employeeCounter = 1;
    }

    /**
     * Returns the single instance of Company.
     *
     * @return the Company instance
     */
    public static synchronized Company getInstance() {
        if (instance == null) {
            instance = new Company();
        }
        return instance;
    }

    /**
     * Adds an employee to the company and increments the counter.
     *
     * @param employee the employee to add
     */
    public void addEmployee(Employee employee) {
        if (employee != null) {
            employees.add(employee);
            employeeCounter++;
        }
    }

    /**
     * Returns a copy of the list of all employees.
     *
     * @return list of employees
     */
    public List<Employee> getEmployees() {
        return new ArrayList<>(employees);
    }

    /**
     * Returns the current employee counter value.
     *
     * @return employee counter
     */
    public int getEmployeeCounter() {
        return employeeCounter;
    }

    /**
     * Hires a CEO for the company. The CEO can only be hired once.
     *
     * @param manager the manager to be hired as CEO
     * @throws IllegalArgumentException if the manager is null
     * @throws IllegalStateException    if a CEO already exists
     */
    public void hireCEO(Manager manager) {
        if (manager == null) {
            throw new IllegalArgumentException("CEO cannot be null");
        }
        if (ceo != null) {
            throw new IllegalStateException("CEO already exists");
        }
        // Assign unique ID
        manager.setId("EMP-" + employeeCounter);
        employeeCounter++;
        // Add to employee list
        employees.add(manager);
        // Set as CEO
        ceo = manager;
    }

    /**
     * Returns the current CEO of the company.
     *
     * @return the CEO manager, or null if none has been hired
     */
    public Manager getCEO() {
        return ceo;
    }
}

