import java.util.HashMap;
import java.util.Map;

/**
 * A simple alerting service that tracks the number of alerts per severity level
 * and stores the most recent alert message for each level.
 */
public class AlertingService {

    /** Map of severity level to the number of alerts triggered. */
    private final Map<String, Integer> alertCounts = new HashMap<>();

    /** Map of severity level to the most recent alert message. */
    private final Map<String, String> lastAlertMessages = new HashMap<>();

    /**
     * Triggers an alert for the given severity level with the provided message.
     * The alert count for the level is incremented and the message is stored as the
     * most recent alert for that level.
     *
     * @param level   the severity level (e.g., "INFO", "WARN", "ERROR")
     * @param message the alert message
     */
    public void triggerAlert(String level, String message) {
        if (level == null || message == null) {
            throw new IllegalArgumentException("Level and message must not be null");
        }

        // Increment the count for this level
        alertCounts.merge(level, 1, Integer::sum);

        // Store the most recent message
        lastAlertMessages.put(level, message);
    }

    /**
     * Returns the number of alerts that have been triggered for the specified level.
     *
     * @param level the severity level
     * @return the alert count, or 0 if no alerts have been recorded for this level
     */
    public int getAlertCount(String level) {
        if (level == null) {
            throw new IllegalArgumentException("Level must not be null");
        }
        return alertCounts.getOrDefault(level, 0);
    }

    /**
     * Retrieves the most recent alert message for the specified level.
     *
     * @param level the severity level
     * @return the last alert message, or {@code null} if no alert has been recorded for this level
     */
    public String getLastAlertMessage(String level) {
        if (level == null) {
            throw new IllegalArgumentException("Level must not be null");
        }
        return lastAlertMessages.get(level);
    }

    /**
     * Resets all alert statistics, clearing both counts and last messages.
     */
    public void resetStatistics() {
        alertCounts.clear();
        lastAlertMessages.clear();
    }
}

