import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        // Default result for invalid or missing data
        Map<String, Object> defaultResult = new HashMap<>();
        defaultResult.put("categoryCount", 0);
        defaultResult.put("totalCartItems", 0);
        defaultResult.put("categoryNames", new ArrayList<String>());
        defaultResult.put("hasEmptyCategories", false);
        defaultResult.put("categoryNameLengths", new ArrayList<Integer>());

        // Treat null or empty input as no data
        if (isNullOrEmpty(categoriesJson) || isNullOrEmpty(cartJson)) {
            return defaultResult;
        }

        // Validate success flag in both JSON strings
        if (!hasSuccessOne(categoriesJson) || !hasSuccessOne(cartJson)) {
            return defaultResult;
        }

        // Parse categories
        List<String> categoryNames = parseCategoryNames(categoriesJson);
        int categoryCount = categoryNames.size();
        boolean hasEmptyCategories = categoryNames.stream().anyMatch(String::isEmpty);
        List<Integer> categoryNameLengths = new ArrayList<>();
        for (String name : categoryNames) {
            categoryNameLengths.add(name.length());
        }

        // Parse cart quantities
        List<Integer> quantities = parseQuantities(cartJson);
        int totalCartItems = quantities.stream().mapToInt(Integer::intValue).sum();

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryCount);
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }

    // Helper: check if string is null or empty after trimming
    private static boolean isNullOrEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }

    // Helper: check if JSON contains "success" : 1
    private static boolean hasSuccessOne(String json) {
        Pattern pattern = Pattern.compile("\"success\"\\s*:\\s*1\\b");
        Matcher matcher = pattern.matcher(json);
        return matcher.find();
    }

    // Helper: parse category names, treating missing or null as empty string
    private static List<String> parseCategoryNames(String json) {
        List<String> names = new ArrayList<>();
        Pattern objPattern = Pattern.compile("\\{[^}]*\\}");
        Matcher objMatcher = objPattern.matcher(json);
        while (objMatcher.find()) {
            String objStr = objMatcher.group();
            Map<String, String> kv = parseKeyValuePairs(objStr);
            String nameVal = kv.get("name");
            if (nameVal == null || nameVal.equals("null")) {
                names.add("");
            } else {
                names.add(nameVal);
            }
        }
        return names;
    }

    // Helper: parse quantities, treating missing or null as 0
    private static List<Integer> parseQuantities(String json) {
        List<Integer> qtys = new ArrayList<>();
        Pattern objPattern = Pattern.compile("\\{[^}]*\\}");
        Matcher objMatcher = objPattern.matcher(json);
        while (objMatcher.find()) {
            String objStr = objMatcher.group();
            Map<String, String> kv = parseKeyValuePairs(objStr);
            String qtyVal = kv.get("quantity");
            int qty = 0;
            if (qtyVal != null && !qtyVal.equals("null")) {
                try {
                    qty = Integer.parseInt(qtyVal);
                } catch (NumberFormatException e) {
                    qty = 0; // fallback to 0 if parsing fails
                }
            }
            qtys.add(qty);
        }
        return qtys;
    }

    // Helper: parse key-value pairs inside a JSON object string
    private static Map<String, String> parseKeyValuePairs(String objStr) {
        Map<String, String> map = new HashMap<>();
        // Remove surrounding braces
        String content = objStr.substring(1, objStr.length() - 1).trim();
        if (content.isEmpty()) {
            return map;
        }
        // Split by commas not inside quotes (simple split assuming no commas in values)
        String[] pairs = content.split(",(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)");
        for (String pair : pairs) {
            String[] kv = pair.split(":", 2);
            if (kv.length != 2) continue;
            String key = stripQuotes(kv[0].trim());
            String value = stripQuotes(kv[1].trim());
            map.put(key, value);
        }
        return map;
    }

    // Helper: remove surrounding double quotes if present
    private static String stripQuotes(String s) {
        if (s.startsWith("\"") && s.endsWith("\"") && s.length() >= 2) {
            return s.substring(1, s.length() - 1);
        }
        return s;
    }
}

