import java.util.regex.Pattern;
import java.util.regex.Matcher;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        // Default result for invalid or missing data
        Map<String, Object> defaultResult = new HashMap<>();
        defaultResult.put("categoryCount", 0);
        defaultResult.put("totalCartItems", 0);
        defaultResult.put("categoryNames", new ArrayList<String>());
        defaultResult.put("hasEmptyCategories", false);
        defaultResult.put("categoryNameLengths", new ArrayList<Integer>());

        // Treat null or empty input as no data
        if (isNullOrEmpty(categoriesJson) || isNullOrEmpty(cartJson)) {
            return defaultResult;
        }

        // Validate success flag in both JSON strings
        if (!hasSuccessOne(categoriesJson) || !hasSuccessOne(cartJson)) {
            return defaultResult;
        }

        // Validate that the JSON strings are arrays
        if (!isArrayJson(categoriesJson)) {
            throw new IllegalArgumentException("Invalid JSON format for categoriesJson");
        }
        if (!isArrayJson(cartJson)) {
            throw new IllegalArgumentException("Invalid JSON format for cartJson");
        }

        // Parse categories
        List<String> categoryNames = parseCategoryNames(categoriesJson);
        int categoryCount = categoryNames.size();
        boolean hasEmptyCategories = categoryNames.isEmpty() || categoryNames.stream().anyMatch(String::isEmpty);
        List<Integer> categoryNameLengths = new ArrayList<>();
        for (String name : categoryNames) {
            categoryNameLengths.add(name.length());
        }

        // Parse cart quantities
        List<Integer> quantities = parseQuantities(cartJson);
        int totalCartItems = quantities.stream().mapToInt(Integer::intValue).sum();

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryCount);
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }

    // Helper: check if string is null or empty after trimming
    private static boolean isNullOrEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }

    // Helper: check if JSON contains "success" : 1
    private static boolean hasSuccessOne(String json) {
        Pattern pattern = Pattern.compile("\"success\"\\s*:\\s*1\\b");
        Matcher matcher = pattern.matcher(json);
        return matcher.find();
    }

    // Helper: check if JSON string represents an array (starts with '[' and ends with ']')
    private static boolean isArrayJson(String json) {
