    private static List<Integer> parseQuantities(String json) {
        List<Integer> qtys = new ArrayList<>();
        Pattern objPattern = Pattern.compile("\\{[^}]*\\}");
        Matcher objMatcher = objPattern.matcher(json);
        while (objMatcher.find()) {
            String objStr = objMatcher.group();
            Map<String, String> kv = parseKeyValuePairs(objStr);
            String qtyVal = kv.get("quantity");
            int qty = 0;
            if (qtyVal != null && !qtyVal.equals("null")) {
                try {
                    qty = Integer.parseInt(qtyVal);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid quantity value: " + qtyVal);
                }
            }
            qtys.add(qty);
        }
        return qtys;
    }

    // Helper: parse key-value pairs inside a JSON object string
