import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class KeyValueStore<K, V> {
    // Stores the key-value pairs
    private final ConcurrentHashMap<K, V> store = new ConcurrentHashMap<>();

    // Tracks how many times each key has been accessed
    private final ConcurrentHashMap<K, AtomicInteger> accessCounts = new ConcurrentHashMap<>();

    // Tracks the last access time (in ms since epoch) for each key
    private final ConcurrentHashMap<K, Long> lastAccessTimes = new ConcurrentHashMap<>();

    /**
     * Stores a key-value pair.
     *
     * @param key   the key to store (must not be null)
     * @param value the value to associate with the key
     * @throws IllegalArgumentException if key is null
     */
    public void put(K key, V value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        store.put(key, value);
    }

    /**
     * Retrieves the value associated with the given key.
     * Increments the access count and updates the last access time.
     *
     * @param key the key to look up (must not be null)
     * @return the value associated with the key, or null if none
     * @throws IllegalArgumentException if key is null
     */
    public V get(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        // Increment access count atomically
        accessCounts.computeIfAbsent(key, k -> new AtomicInteger(0)).incrementAndGet();

        // Update last access time
        lastAccessTimes.put(key, System.currentTimeMillis());

        return store.get(key);
    }

    /**
     * Returns how many times the specified key has been accessed.
     *
     * @param key the key to query (must not be null)
     * @return the access count, or 0 if the key has never been accessed
     * @throws IllegalArgumentException if key is null
     */
    public int getAccessCount(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        AtomicInteger counter = accessCounts.get(key);
        return counter == null ? 0 : counter.get();
    }

    /**
     * Returns the last access time for the specified key in milliseconds
     * since the epoch. If the key has never been accessed, returns 0.
     *
     * @param key the key to query (must not be null)
     * @return the last access time in ms, or 0 if never accessed
     * @throws IllegalArgumentException if key is null
     */
    public long getLastAccessTime(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        Long time = lastAccessTimes.get(key);
        return time == null ? 0L : time;
    }

    // Example usage
    public static void main(String[] args) throws InterruptedException {
        KeyValueStore<String, Integer> kv = new KeyValueStore<>();

        kv.put("one", 1);
        kv.put("two", 2);

        System.out.println("Get 'one': " + kv.get("one")); // 1
        Thread.sleep(10);
        System.out.println("Get 'one' again: " + kv.get("one")); // 1
        Thread.sleep(10);
        System.out.println("Get 'two': " + kv.get("two")); // 2

        System.out.println("Access count 'one': " + kv.getAccessCount("one")); // 2
        System.out.println("Access count 'two': " + kv.getAccessCount("two")); // 1
        System.out.println("Access count 'three': " + kv.getAccessCount("three")); // 0

        System.out.println("Last access time 'one': " + kv.getLastAccessTime("one")); // recent ms
        System.out.println("Last access time 'two': " + kv.getLastAccessTime("two")); // recent ms
        System.out.println("Last access time 'three': " + kv.getLastAccessTime("three")); // 0
    }
}

