import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.HashSet;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class KeyValueStore<K, V> {

    // Core storage
    private final ConcurrentHashMap<K, V> store = new ConcurrentHashMap<>();

    // Access statistics
    private final ConcurrentHashMap<K, AtomicInteger> accessCounts = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, Long> lastAccessTimes = new ConcurrentHashMap<>();

    // Type distribution
    private final ConcurrentHashMap<Class<?>, AtomicInteger> typeCounts = new ConcurrentHashMap<>();

    /* --------------------- Basic Operations --------------------- */

    public void put(K key, V value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        V oldValue = store.put(key, value);

        // Update type counts
        if (oldValue != null) {
            Class<?> oldClass = oldValue.getClass();
            typeCounts.computeIfPresent(oldClass, (cls, counter) -> {
                counter.decrementAndGet();
                return counter;
            });
        }

        if (value != null) {
            Class<?> newClass = value.getClass();
            typeCounts.computeIfAbsent(newClass, cls -> new AtomicInteger(0)).incrementAndGet();
        }
    }

    public V get(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        // Increment access count
        accessCounts.computeIfAbsent(key, k -> new AtomicInteger(0)).incrementAndGet();

        // Update last access time
        lastAccessTimes.put(key, System.currentTimeMillis());

        return store.get(key);
    }

    public int getAccessCount(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        AtomicInteger counter = accessCounts.get(key);
        return counter == null ? 0 : counter.get();
    }

    public long getLastAccessTime(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        Long time = lastAccessTimes.get(key);
        return time == null ? 0L : time;
    }

    public int getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        AtomicInteger counter = typeCounts.get(type);
        return counter == null ? 0 : counter.get();
    }

    /* --------------------- Bulk Operations --------------------- */

    public void putAll(Map<? extends K, ? extends V> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries map cannot be null");
        }
        for (Map.Entry<? extends K, ? extends V> e : entries.entrySet()) {
            put(e.getKey(), e.getValue());
        }
    }

    /* --------------------- Statistics --------------------- */

    public Statistics<K> computeStatistics() {
        int totalEntries = store.size();

        K keyWithMaxAccess = null;
        int maxAccess = -1;
        for (Map.Entry<K, AtomicInteger> e : accessCounts.entrySet()) {
            int count = e.getValue().get();
            if (count > maxAccess) {
                maxAccess = count;
                keyWithMaxAccess = e.getKey();
            }
        }

        Map<Class<?>, Integer> typeDistribution = new HashMap<>();
        for (Map.Entry<Class<?>, AtomicInteger> e : typeCounts.entrySet()) {
            typeDistribution.put(e.getKey(), e.getValue().get());
        }

        long estimatedMemoryUsage = totalEntries * 64L; // Rough estimate

        return new Statistics<>(totalEntries, keyWithMaxAccess, typeDistribution, estimatedMemoryUsage);
    }

    /* --------------------- Type-Based Key Retrieval --------------------- */

    public Set<K> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        Set<K> result = new HashSet<>();
        for (Map.Entry<K, V> e : store.entrySet()) {
            V value = e.getValue();
            if (value != null && type.isInstance(value)) {
                result.add(e.getKey());
            }
        }
        return result;
    }

    /* --------------------- Clear Store --------------------- */

    public void clear() {
        store.clear();
        accessCounts.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    /* --------------------- Statistics Data Class --------------------- */

    public static class Statistics<K> {
        private final int totalEntries;
        private final K keyWithMaxAccess;
        private final Map<Class<?>, Integer> typeDistribution;
        private final long estimatedMemoryUsage;

        public Statistics(int totalEntries, K keyWithMaxAccess,
                          Map<Class<?>, Integer> typeDistribution,
                          long estimatedMemoryUsage) {
            this.totalEntries = totalEntries;
            this.keyWithMaxAccess = keyWithMaxAccess;
            this.typeDistribution = typeDistribution;
            this.estimatedMemoryUsage = estimatedMemoryUsage;
        }

        public int getTotalEntries() {
            return totalEntries;
        }

        public K getKeyWithMaxAccess() {
            return keyWithMaxAccess;
        }

        public Map<Class<?>, Integer> getTypeDistribution() {
            return typeDistribution;
        }

        public long getEstimatedMemoryUsage() {
            return estimatedMemoryUsage;
        }
    }

    /* --------------------- Example Usage --------------------- */

    public static void main(String[] args) throws InterruptedException {
        KeyValueStore<String, Object> kv = new KeyValueStore<>();

        kv.put("one", 1);          // Integer
        kv.put("two", 2.5);        // Double
        kv.put("three", "hello");  // String

        kv.putAll(Map.of("four", 4L, "five", 5.0f));

        System.out.println("Get 'one': " + kv.get("one")); // 1
        Thread.sleep(10);
        System.out.println("Get 'one' again: " + kv.get("one")); // 1
        Thread.sleep(10);
        System.out.println("Get 'two': " + kv.get("two")); // 2.5

        System.out.println("\nAccess counts:");
        System.out.println("Access count 'one': " + kv.getAccessCount("one"));   // 2
        System.out.println("Access count 'two': " + kv.getAccessCount("two"));   // 1
        System.out.println("Access count 'three': " + kv.getAccessCount("three")); // 0

        System.out.println("\nLast access times:");
        System.out.println("Last access time 'one': " + kv.getLastAccessTime("one"));   // recent ms
        System.out.println("Last access time 'two': " + kv.getLastAccessTime("two"));   // recent ms
        System.out.println("Last access time 'three': " + kv.getLastAccessTime("three")); // 0

        System.out.println("\nType counts:");
        System.out.println("Integer count: " + kv.getTypeCount(Integer.class)); // 1
        System.out.println("Double count: " + kv.getTypeCount(Double.class));   // 1
        System.out.println("String count: " + kv.getTypeCount(String.class));   // 1
        System.out.println("Long count: " + kv.getTypeCount(Long.class));       // 1
        System.out.println("Float count: " + kv.getTypeCount(Float.class));     // 1

        System.out.println("\nFind keys by type:");
        System.out.println("Keys with Integer values: " + kv.findKeysByType(Integer.class));
        System.out.println("Keys with Number values: " + kv.findKeysByType(Number.class));

        System.out.println("\nStatistics:");
        KeyValueStore.Statistics<String> stats = kv.computeStatistics();
        System.out.println("Total entries: " + stats.getTotalEntries());
        System.out.println("Key with max access: " + stats.getKeyWithMaxAccess());
        System.out.println("Type distribution: " + stats.getTypeDistribution());
        System.out.println("Estimated memory usage: " + stats.getEstimatedMemoryUsage() + " bytes");

        System.out.println("\nClear store");
        kv.clear();
        System.out.println("Total entries after clear: " + kv.computeStatistics().getTotalEntries());
    }
}

