    private int nodeCount;

    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();
        if (root == null) {
            result.put("maxDiff", 0);
            result.put("minDiff", 0);
            result.put("avgDiff", 0);
            result.put("nodeCount", 0);
            return result;
        }

        globalMinDiff = Integer.MAX_VALUE;
        globalMaxDiff = 0;
        sumDiffTotal = 0;
        nodeCount = 0;

        TreeSet<Integer> ancestorsSet = new TreeSet<>();
        ArrayList<Integer> ancestorsList = new ArrayList<>();

        dfs(root, root.val, root.val, ancestorsSet, ancestorsList);

        int minDiff = (globalMinDiff == Integer.MAX_VALUE) ? 0 : globalMinDiff;
        int maxDiff = globalMaxDiff;
        int avgDiff = nodeCount == 0 ? 0 : (int)(sumDiffTotal / nodeCount);

        result.put("maxDiff", maxDiff);
        result.put("minDiff", minDiff);
        result.put("avgDiff", avgDiff);
        result.put("nodeCount", nodeCount);
        return result;
    }

    private void dfs(TreeNode node, int currentMin, int currentMax,
                     TreeSet<Integer> ancestorsSet, ArrayList<Integer> ancestorsList) {
        if (node == null) return;

        // Update min difference using nearest ancestors
        Integer floor = ancestorsSet.floor(node.val);
        Integer ceil = ancestorsSet.ceiling(node.val);
        if (floor != null) globalMinDiff = Math.min(globalMinDiff, Math.abs(node.val - floor));
        if (ceil != null) globalMinDiff = Math.min(globalMinDiff, Math.abs(node.val - ceil));

        // Sum differences between this node and all its ancestors
        long sumDiffNode = 0;
        for (int a : ancestorsList) {
            sumDiffNode += Math.abs(node.val - a);
        }
        sumDiffTotal += sumDiffNode;

        // Count this node
        nodeCount++;

        // Update max difference using path min/max
        int newMin = Math.min(currentMin, node.val);
        int newMax = Math.max(currentMax, node.val);
        int localMaxDiff = Math.max(node.val - newMin, newMax - node.val);
        globalMaxDiff = Math.max(globalMaxDiff, localMaxDiff);

        // Add current node to ancestor structures
        ancestorsSet.add(node.val);
        ancestorsList.add(node.val);

        // Recurse on children
        dfs(node.left, newMin, newMax, ancestorsSet, ancestorsList);
        dfs(node.right, newMin, newMax, ancestorsSet, ancestorsList);

        // Remove current node from ancestor structures
        ancestorsSet.remove(node.val);
        ancestorsList.remove(ancestorsList.size() - 1);
    }
}

