public class EnhancedBinaryHeap<T extends Comparable<T>> {

    private static final int DEFAULT_CAPACITY = 10;
    private T[] heap;
    private int size;

    @SuppressWarnings("unchecked")
    public EnhancedBinaryHeap() {
        heap = (T[]) new Comparable[DEFAULT_CAPACITY];
        size = 0;
    }

    @SuppressWarnings("unchecked")
    public EnhancedBinaryHeap(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        heap = (T[]) new Comparable[capacity];
        size = 0;
    }

    /** Inserts an element into the heap. */
    public void insert(T element) {
        if (element == null) {
            throw new IllegalArgumentException("Null elements not allowed");
        }
        ensureCapacity();
        heap[size] = element;
        bubbleUp(size);
        size++;
    }

    /** Removes and returns the root element (minimum). Returns null if the heap is empty. */
    public T deleteRoot() {
        if (isEmpty()) {
            return null;
        }
        T root = heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            bubbleDown(0);
        }
        heap[size] = null; // Help GC
        return root;
    }

    /** Returns the root element without removing it. Returns null if the heap is empty. */
    public T peekRoot() {
        return isEmpty() ? null : heap[0];
    }

    /** Returns true if the heap contains no elements. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Returns the number of elements in the heap. */
    public int size() {
        return size;
    }

    /** Removes all elements from the heap. */
    public void makeEmpty() {
        for (int i = 0; i < size; i++) {
            heap[i] = null;
        }
        size = 0;
    }

    /* ----------------- Internal helper methods ----------------- */

    private void ensureCapacity() {
        if (size >= heap.length) {
            int newCapacity = heap.length * 2;
            @SuppressWarnings("unchecked")
            T[] newHeap = (T[]) new Comparable[newCapacity];
            System.arraycopy(heap, 0, newHeap, 0, heap.length);
            heap = newHeap;
        }
    }

    private void bubbleUp(int index) {
        T element = heap[index];
        while (index > 0) {
            int parentIndex = (index - 1) >>> 1;
            T parent = heap[parentIndex];
            if (element.compareTo(parent) >= 0) {
                break;
            }
            heap[index] = parent;
            index = parentIndex;
        }
        heap[index] = element;
    }

    private void bubbleDown(int index) {
        T element = heap[index];
        int half = size >>> 1; // Nodes with children
        while (index < half) {
            int leftChild = (index << 1) + 1;
            int rightChild = leftChild + 1;
            int smallestChild = leftChild;
            if (rightChild < size && heap[rightChild].compareTo(heap[leftChild]) < 0) {
                smallestChild = rightChild;
            }
            if (heap[smallestChild].compareTo(element) >= 0) {
                break;
            }
            heap[index] = heap[smallestChild];
            index = smallestChild;
        }
        heap[index] = element;
    }

    @Override
    public String toString() {
        if (isEmpty()) {
            return "[]";
        }
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < size; i++) {
            sb.append(heap[i]);
            if (i < size - 1) sb.append(", ");
        }
        sb.append(']');
        return sb.toString();
    }
}

