    private T[] heap;
    private int size;
    private final boolean isMinHeap;

    /* ----------------- Constructors ----------------- */

    /** Default constructor creates a min‑heap with default capacity. */
    public EnhancedBinaryHeap() {
        this(true, DEFAULT_CAPACITY);
    }

    /** Creates a heap with the specified type and capacity. */
    public EnhancedBinaryHeap(boolean isMinHeap, int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        @SuppressWarnings("unchecked")
        T[] temp = (T[]) new Comparable[capacity];
        heap = temp;
        size = 0;
        this.isMinHeap = isMinHeap;
    }

    /** Creates a heap with the specified type and default capacity. */
    public EnhancedBinaryHeap(boolean isMinHeap) {
        this(isMinHeap, DEFAULT_CAPACITY);
    }

    /* ----------------- Public API ----------------- */

    /** Inserts an element into the heap. */
    public void insert(T element) {
        if (element == null) {
            throw new IllegalArgumentException("Null elements not allowed");
        }
        ensureCapacity();
        heap[size] = element;
        bubbleUp(size);
        size++;
    }

    /** Removes and returns the root element (minimum or maximum). Returns null if the heap is empty. */
    public T deleteRoot() {
        if (isEmpty()) {
            return null;
        }
        T root = heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            bubbleDown(0);
        }
        heap[size] = null; // Help GC
        return root;
    }

    /** Returns the root element without removing it. Returns null if the heap is empty. */
    public T peekRoot() {
        return isEmpty() ? null : heap[0];
    }

    /** Returns true if the heap contains no elements. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Returns the number of elements in the heap. */
    public int size() {
        return size;
    }

    /** Removes all elements from the heap. */
    public void makeEmpty() {
        for (int i = 0; i < size; i++) {
            heap[i] = null;
        }
        size = 0;
    }

    /* ----------------- Internal helper methods ----------------- */

    /** Ensures the internal array has enough capacity to store new elements. */
    @SuppressWarnings("unchecked")
    private void ensureCapacity() {
        if (size >= heap.length) {
            int newCapacity = heap.length * 2;
            T[] newHeap = (T[]) new Comparable[newCapacity];
            System.arraycopy(heap, 0, newHeap, 0, heap.length);
            heap = newHeap;
        }
    }

    /** Restores heap property by moving the element at index up. */
    private void bubbleUp(int index) {
        T element = heap[index];
        while (index > 0) {
            int parentIndex = (index - 1) >>> 1;
            T parent = heap[parentIndex];
            if (compare(element, parent) >= 0) {
                break;
            }
            heap[index] = parent;
            index = parentIndex;
        }
        heap[index] = element;
    }

    /** Restores heap property by moving the element at index down. */
    private void bubbleDown(int index) {
        T element = heap[index];
        int half = size >>> 1; // Nodes with at least one child
        while (index < half) {
            int leftChild = (index << 1) + 1;
            int rightChild = leftChild + 1;
            int bestChild = leftChild;

            if (rightChild < size && compare(heap[rightChild], heap[leftChild]) < 0) {
                bestChild = rightChild;
            }

            if (compare(heap[bestChild], element) >= 0) {
                break;
            }

            heap[index] = heap[bestChild];
            index = bestChild;
        }
        heap[index] = element;
    }

    /**
     * Compares two elements according to the heap type.
     * For a min‑heap, returns a negative value if a < b.
     * For a max‑heap, returns a negative value if a > b.
     */
    private int compare(T a, T b) {
        int cmp = a.compareTo(b);
        return isMinHeap ? cmp : -cmp;
    }

    @Override
    public String toString() {
        if (isEmpty()) {
            return "[]";
        }
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < size; i++) {
            sb.append(heap[i]);
            if (i < size - 1) sb.append(", ");
        }
        sb.append(']');
        return sb.toString();
    }
