 * Represents a category with an id, name and parent id.
 */
class Category {
    private final int id;
    private final String name;
    private final int parentId;

    public Category(int id, String name, int parentId) {
        this.id = id;
        this.name = name;
        this.parentId = parentId;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public int getParentId() { return parentId; }
}

/**
 * Node used in the category tree. Each node holds its id, name and a list of child nodes.
 */
class CategoryNode {
    private final int id;
    private final String name;
    private final List<CategoryNode> children = new ArrayList<>();

    public CategoryNode(int id, String name) {
        this.id = id;
        this.name = name;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public List<CategoryNode> getChildren() { return children; }

    public void addChild(CategoryNode child) {
        children.add(child);
    }
}

/**
 * Result wrapper for the list of root category nodes.
 */
class CatResult {
    private final List<CategoryNode> categories;

    public CatResult(List<CategoryNode> categories) {
        this.categories = categories;
    }

    public List<CategoryNode> getCategories() { return categories; }
}

/**
 * Service that manages categories and builds the tree structure.
 */
class ItemCatService {
    // Stores all categories by their id.
    private final Map<Integer, Category> categoriesById = new HashMap<>();
    // Maps parent id to its direct child categories.
    private final Map<Integer, List<Category>> childrenMap = new HashMap<>();

    /**
     * Adds a new category. Assumes that the parent category (if any) has already been added.
     */
    public void addCategory(int id, String name, int parentId) {
        Category cat = new Category(id, name, parentId);
        categoriesById.put(id, cat);
        childrenMap.computeIfAbsent(parentId, k -> new ArrayList<>()).add(cat);
    }

    /**
     * Builds and returns the category tree. If no categories exist, returns an empty CatResult.
     */
    public CatResult getItemCatList() {
        if (categoriesById.isEmpty()) {
            return new CatResult(Collections.emptyList());
        }

        List<CategoryNode> roots = new ArrayList<>();
        for (Category cat : categoriesById.values()) {
            if (cat.getParentId() == 0) {
                CategoryNode rootNode = buildNode(cat);
                roots.add(rootNode);
            }
        }
        return new CatResult(roots);
    }

    /**
     * Recursively builds a CategoryNode and its children from a Category.
     */
    private CategoryNode buildNode(Category cat) {
        CategoryNode node = new CategoryNode(cat.getId(), cat.getName());
        List<Category> childCats = childrenMap.get(cat.getId());
        if (childCats != null) {
            for (Category child : childCats) {
                node.addChild(buildNode(child));
            }
        }
        return node;
    }
}
