import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

class UserManager {
    private Map<String, User> userDatabase;
    private Map<String, String> activeSessions; // username -> session token

    public UserManager() {
        this.userDatabase = new HashMap<>();
        this.activeSessions = new HashMap<>();
    }

    /**
     * Registers a new user.
     *
     * @param username Desired username (must be unique)
     * @param password Password for the account
     * @param email    Email address
     * @return true if registration succeeded, false if username already exists
     */
    public boolean register(String username, String password, String email) {
        if (userDatabase.containsKey(username)) {
            return false; // username already taken
        }
        User newUser = new User(username, password, email);
        userDatabase.put(username, newUser);
        return true;
    }

    /**
     * Logs in a user.
     *
     * @param username Username
     * @param password Password
     * @return a session token if login is successful, null otherwise
     */
    public String login(String username, String password) {
        User user = userDatabase.get(username);
        if (user == null) {
            return null; // user does not exist
        }
        if (!user.getPassword().equals(password)) {
            return null; // incorrect password
        }
        // Generate a simple session token
        String token = UUID.randomUUID().toString();
        activeSessions.put(username, token);
        return token;
    }

    /**
     * Logs out a user.
     *
     * @param username Username to log out
     * @return true if logout succeeded, false if user was not logged in
     */
    public boolean logout(String username) {
        if (activeSessions.containsKey(username)) {
            activeSessions.remove(username);
            return true;
        }
        return false; // user was not logged in
    }

    /**
     * Checks if a user is currently logged in.
     *
     * @param username Username to check
     * @return true if the user has an active session
     */
    public boolean isLoggedIn(String username) {
        return activeSessions.containsKey(username);
    }

    /**
     * Retrieves the active session token for a user.
     *
     * @param username Username
     * @return session token or null if not logged in
     */
    public String getSessionToken(String username) {
        return activeSessions.get(username);
    }

    /**
     * Retrieves a user by username.
     *
     * @param username Username
     * @return User object or null if not found
     */
    public User getUser(String username) {
        return userDatabase.get(username);
    }
}

class User {
    private String username;
    private String password;
    private String email;

    public User(String username, String password, String email) {
        this.username = username;
        this.password = password;
        this.email = email;
    }

    public String getUsername() {
        return username;
    }

    // For security reasons, we usually wouldn't expose the password,
    // but for this simple example we provide a getter.
    public String getPassword() {
        return password;
    }

    public String getEmail() {
        return email;
    }
}

