/**
 * Represents a simple message with an identifier and content.
 */
class Message {
    private final String id;
    private final String content;

    public Message(String id, String content) {
        this.id = id;
        this.content = content;
    }

    public String getId() {
        return id;
    }

    public String getContent() {
        return content;
    }
