/**
 * Enumeration of possible processing statuses.
 */
enum Status {
    SUCCESS,
    FAILURE
}

/**
 * Result of processing a message.
 */
class ProcessingResult {
    private final Status status;
    private final String messageId;

    public ProcessingResult(Status status, String messageId) {
        this.status = status;
        this.messageId = messageId;
    }

    public Status getStatus() {
        return status;
    }

    public String getMessageId() {
        return messageId;
    }
}

/**
 * Processor that stores messages and returns a processing result.
 */
public class EnhancedMessageProcessor {
    // Stores messages keyed by destination.
    private final Map<String, Message> storage = new HashMap<>();

    /**
     * Stores the given message for the specified destination and returns a success result.
     *
     * @param message     the message to store
     * @param destination the destination identifier
     * @return a ProcessingResult indicating success
     */
    public ProcessingResult postMessage(Message message, String destination) {
        storage.put(destination, message);
        return new ProcessingResult(Status.SUCCESS, message.getId());
    }

    // Optional: method to retrieve a stored message (not required by the problem statement)
    public Message getMessage(String destination) {
        return storage.get(destination);
    }
}

