/**
 * Processor that stores messages, tracks counts per destination,
 * and returns a processing result with total message count metadata.
 * All public methods are synchronized to ensure thread safety.
 */
public class EnhancedMessageProcessor {
    // Stores lists of messages keyed by destination.
    // LinkedHashMap preserves insertion order of destinations.
    private final Map<String, List<Message>> storage = new LinkedHashMap<>();

    // Tracks the number of messages per destination.
    private final Map<String, Integer> destinationCounts = new LinkedHashMap<>();

    // Total number of messages processed across all destinations.
    private long totalMessages = 0;

    /**
     * Stores the given message for the specified destination and returns a success result.
     *
     * @param message     the message to store
     * @param destination the destination identifier
     * @return a ProcessingResult indicating success and containing totalMessages metadata
     */
    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Store the message
        storage.computeIfAbsent(destination, k -> new ArrayList<>()).add(message);

        // Update destination-specific count
        destinationCounts.merge(destination, 1, Integer::sum);

        // Update total message count
        totalMessages++;

        // Prepare metadata
        Map<String, Object> metadata = new LinkedHashMap<>();
        metadata.put("totalMessages", totalMessages);

        return new ProcessingResult(Status.SUCCESS, message.getId(), metadata);
    }

    /**
     * Retrieves the latest message for the specified destination.
     *
     * @param destination the destination identifier
     * @return the most recently stored Message for that destination, or null if none exists
     */
    public synchronized Message getMessage(String destination) {
        List<Message> messages = storage.get(destination);
        if (messages == null || messages.isEmpty()) {
            return null;
        }
        // Return the last (most recent) message
        return messages.get(messages.size() - 1);
    }

    /**
     * Retrieves all messages that match the given content type.
     * The returned map preserves the insertion order of destinations.
     *
     * @param contentType the content type to match
     * @return a map of destination -> list of matching messages
     */
    public synchronized Map<String, List<Message>> getMessagesByType(String contentType) {
        Map<String, List<Message>> result = new LinkedHashMap<>();
        for (Map.Entry<String, List<Message>> entry : storage.entrySet()) {
            List<Message> matched = new ArrayList<>();
            for (Message msg : entry.getValue()) {
                if (msg.getContent().equals(contentType)) {
                    matched.add(msg);
                }
            }
            if (!matched.isEmpty()) {
                result.put(entry.getKey(), matched);
            }
        }
        return result;
    }

    /**
     * Clears all messages for the specified destination.
     *
     * @param destination the destination identifier
     * @return Status.SUCCESS if messages were removed, Status.FAILURE if no such destination existed
     */
    public synchronized Status clearMessages(String destination) {
        List<Message> removed = storage.remove(destination);
        if (removed == null) {
            return Status.FAILURE;
        }
        // Update counts
        Integer removedCount = destinationCounts.remove(destination);
        if (removedCount != null) {
            totalMessages -= removedCount;
        }
        return Status.SUCCESS;
    }

