import java.util.HashMap;
import java.util.Map;

public class UserAuthenticator {
    private final Map<String, String> userDatabase;
    private final Map<String, String> verificationCodes;

    public UserAuthenticator() {
        userDatabase = new HashMap<>();
        // Hardcoded users: phone number -> password
        userDatabase.put("1234567890", "password123");
        userDatabase.put("0987654321", "pass456");

        verificationCodes = new HashMap<>();
    }

    /**
     * Authenticates a user based on phone number and password.
     *
     * @param phoneNumber the user's phone number (must be exactly 10 digits)
     * @param password    the user's password (must not be null or empty)
     * @return an {@link AuthenticationResult} describing the outcome
     * @throws IllegalArgumentException if input validation fails
     */
    public AuthenticationResult authenticate(String phoneNumber, String password) {
        // Input validation
        if (phoneNumber == null || phoneNumber.isEmpty()) {
            throw new IllegalArgumentException("Phone number cannot be null or empty.");
        }
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be null or empty.");
        }
        if (phoneNumber.length() != 10) {
            throw new IllegalArgumentException("Phone number must be exactly 10 digits long.");
        }

        // Authentication logic
        if (!userDatabase.containsKey(phoneNumber)) {
            return new AuthenticationResult(404, "User not found.", null);
        }
        String storedPassword = userDatabase.get(phoneNumber);
        if (!storedPassword.equals(password)) {
            return new AuthenticationResult(401, "Invalid password.", null);
        }

        // Successful password check – initiate two‑factor
        String code = generateVerificationCode();
        verificationCodes.put(phoneNumber, code);
        return new AuthenticationResult(250, "Verification required.", phoneNumber);
    }

    /**
     * Verifies the two‑factor authentication code for a user.
     *
     * @param phoneNumber the user's phone number
     * @param code        the verification code to validate
     * @return an {@link AuthenticationResult} indicating success or failure
     * @throws IllegalArgumentException if input validation fails
     */
    public AuthenticationResult verifyCode(String phoneNumber, String code) {
        // Input validation
        if (phoneNumber == null || phoneNumber.isEmpty()) {
            throw new IllegalArgumentException("Phone number cannot be null or empty.");
        }
        if (code == null || code.isEmpty()) {
            throw new IllegalArgumentException("Verification code cannot be null or empty.");
        }

        String storedCode = verificationCodes.get(phoneNumber);
        if (storedCode != null && storedCode.equals(code)) {
            verificationCodes.remove(phoneNumber); // consume the code
            return new AuthenticationResult(200, "Verification successful.", phoneNumber);
        } else {
            return new AuthenticationResult(401, "Invalid verification code.", null);
        }
    }

    /**
     * Generates a verification code for two‑factor authentication.
     * In a real system this would be random; here it is hard‑coded.
     *
     * @return the verification code
     */
    private String generateVerificationCode() {
        return "123456";
    }

    /**
     * Structured result of an authentication attempt.
     */
    public static class AuthenticationResult {
        private final int statusCode;
        private final String message;
        private final String user; // phone number of the authenticated user, if any

        public AuthenticationResult(int statusCode, String message, String user) {
            this.statusCode = statusCode;
            this.message = message;
            this.user = user;
        }

        public int getStatusCode() {
            return statusCode;
        }

        public String getMessage() {
            return message;
        }

        public String getUser() {
            return user;
        }

        @Override
        public String toString() {
            return "AuthenticationResult{" +
                    "statusCode=" + statusCode +
                    ", message='" + message + '\'' +
                    ", user='" + user + '\'' +
                    '}';
        }
    }

    // Example usage
    public static void main(String[] args) {
        UserAuthenticator authenticator = new UserAuthenticator();

        // Successful login – triggers two‑factor
        AuthenticationResult authResult = authenticator.authenticate("1234567890", "password123");
        System.out.println(authResult); // status 250, verification required

        // Attempt to verify with wrong code
        AuthenticationResult verifyFail = authenticator.verifyCode("1234567890", "000000");
        System.out.println(verifyFail); // status 401

        // Verify with correct code
        AuthenticationResult verifySuccess = authenticator.verifyCode("1234567890", "123456");
