import java.util.*;

public class DivisionUtil {
    public static List<Integer> elementWiseDivide(List<Integer> numerators, List<Integer> denominators) {
        if (numerators == null || denominators == null) {
            throw new IllegalArgumentException("Input lists cannot be null");
        }
        if (numerators.size() != denominators.size()) {
            throw new IllegalArgumentException("Lists must have the same size");
        }

        List<Integer> result = new ArrayList<>(numerators.size());
        for (int i = 0; i < numerators.size(); i++) {
            try {
                result.add(numerators.get(i) / denominators.get(i));
            } catch (ArithmeticException e) {
                System.out.println("ArithmeticException at index " + i + ": Division by zero");
                result.add(-1);
            } catch (NullPointerException e) {
                System.out.println("NullPointerException at index " + i);
                result.add(-2);
            }
        }
        return result;
