/**
 * Analyzes a scenario tree, assigning breadth‑first indices to nodes
 * and detecting synchronous request‑response pairs.
 */
public class ScenarioAnalyzer {

    /**
     * Assigns unique indices to each node in the tree in breadth‑first order
     * starting from 0 for the root, and returns a map with:
     *   - 'nodeIndices': mapping node names to their indices
     *   - 'syncPairs':   mapping request node indices to response node indices
     *
     * @param root the root node of the scenario tree
     * @return a map containing 'nodeIndices' and 'syncPairs'
     */
    public Map<String, Object> analyzeScenario(Node root) {
        if (root == null) {
            throw new IllegalArgumentException("Root node cannot be null");
        }

        Map<String, Integer> nodeIndices = new LinkedHashMap<>();
        Map<Node, String> parentServerNameMap = new HashMap<>();
        List<Node> allNodes = new ArrayList<>();

        Queue<Node> queue = new LinkedList<>();
        queue.add(root);
        parentServerNameMap.put(root, null); // root has no parent

        int index = 0;
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            nodeIndices.put(current.getName(), index++);
            allNodes.add(current);

            for (Node child : current.getChildren()) {
                parentServerNameMap.put(child, current.getServerName());
                queue.add(child);
            }
        }

        // Detect synchronous request‑response pairs
        Map<Integer, Integer> syncPairs = new LinkedHashMap<>();
        for (Node node : allNodes) {
            if (!node.isSync()) {
                continue;
            }
            String parentServerName = parentServerNameMap.get(node);
            if (parentServerName == null) {
                continue; // root or no parent server name
            }
            for (Node child : node.getChildren()) {
                if (parentServerName.equals(child.getServerName())) {
                    int requestIdx = nodeIndices.get(node.getName());
                    int responseIdx = nodeIndices.get(child.getName());
                    syncPairs.put(requestIdx, responseIdx);
                    break; // assume at most one matching child
                }
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("nodeIndices", nodeIndices);
        result.put("syncPairs", syncPairs);
        return result;
    }
