public class FactorySimulation {

    public static void main(String[] args) {
        // Initialize input stock with sample items
        Queue<Integer> inputStock = new LinkedList<>();
        for (int i = 1; i <= 10; i++) {
            inputStock.add(i);
        }

        // Output stock where processed items will be moved
        List<Integer> outputStock = new ArrayList<>();

        // Fixed number of items the workshop should process
        int itemsToProcess = 5;

        int processedCount = 0;

        // Process items until the limit is reached or input stock is empty
        while (processedCount < itemsToProcess && !inputStock.isEmpty()) {
            int item = inputStock.poll();   // take item from input stock
            // Simulate processing (here we just move it to output stock)
            outputStock.add(item);
            processedCount++;
        }

        // Output the results
        System.out.println("Processed items: " + processedCount);
        System.out.println("Remaining items in input stock: " + inputStock.size());
    }
}

