import java.util.*;

/**
 * A simple factory simulation that supports four different factory versions.
 * Each version has a predefined sequence of workshops.
 *
 * Input format (from standard input):
 *   line 1: factory version (1-4)
 *   line 2: number of items to process
 *   line 3: number of items in the input stock
 *   line 4: space‑separated list of item identifiers (integers)
 *
 * Output:
 *   Processed items: <count>
 *   Remaining items in input stock: <count>
 *   Output stock items: <comma separated list>
 */
public class FactorySimulation {

    /* Workshop represents a single processing step in the factory. */
    private static class Workshop {
        private final String name;

        Workshop(String name) {
            this.name = name;
        }

        /* Simulate processing of an item. */
        void process(int item) {
            // In a real simulation we might add delays or transformations.
            // Here we simply print a debug message.
            System.out.println("Workshop '" + name + "' processed item " + item);
        }
    }

    /* Factory holds the sequence of workshops for a given version. */
    private static class Factory {
        private final List<Workshop> workshops;

        Factory(int version) {
            workshops = new ArrayList<>();
            switch (version) {
                case 1:
                    workshops.add(new Workshop("Cutting"));
                    break;
                case 2:
                    workshops.add(new Workshop("Cutting"));
                    workshops.add(new Workshop("Welding"));
                    break;
                case 3:
                    workshops.add(new Workshop("Cutting"));
                    workshops.add(new Workshop("Welding"));
                    workshops.add(new Workshop("Painting"));
                    break;
                case 4:
                    workshops.add(new Workshop("Cutting"));
                    workshops.add(new Workshop("Welding"));
                    workshops.add(new Workshop("Painting"));
                    workshops.add(new Workshop("Packaging"));
                    break;
                default:
                    throw new IllegalArgumentException("Unsupported factory version: " + version);
            }
        }

        /* Process items from inputStock to outputStock. */
        int processItems(Queue<Integer> inputStock, List<Integer> outputStock, int itemsToProcess) {
            int processedCount = 0;
            while (processedCount < itemsToProcess && !inputStock.isEmpty()) {
                int item = inputStock.poll();
                // Pass the item through each workshop in order.
                for (Workshop w : workshops) {
                    w.process(item);
                }
                outputStock.add(item);
                processedCount++;
            }
            return processedCount;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Read factory version
        if (!sc.hasNextInt()) {
            System.err.println("Missing factory version input.");
            return;
        }
        int version = sc.nextInt();

        // Read number of items to process
        if (!sc.hasNextInt()) {
            System.err.println("Missing number of items to process.");
            return;
        }
        int itemsToProcess = sc.nextInt();

        // Read number of items in input stock
        if (!sc.hasNextInt()) {
            System.err.println("Missing number of items in input stock.");
            return;
        }
        int stockSize = sc.nextInt();

        // Read the items
        Queue<Integer> inputStock = new LinkedList<>();
        for (int i = 0; i < stockSize && sc.hasNextInt(); i++) {
            inputStock.add(sc.nextInt());
        }

        // Prepare output stock
        List<Integer> outputStock = new ArrayList<>();

        // Create factory with the specified version
        Factory factory;
        try {
            factory = new Factory(version);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
            return;
        }

        // Process items
        int processedCount = factory.processItems(inputStock, outputStock, itemsToProcess);

        // Output results
        System.out.println("\nProcessed items: " + processedCount);
        System.out.println("Remaining items in input stock: " + inputStock.size());
        System.out.print("Output stock items: ");
        if (outputStock.isEmpty()) {
            System.out.println("none");
        } else {
            System.out.println(String.join(", ", outputStock.stream()
                    .map(String::valueOf)
                    .toArray(String[]::new)));
        }
    }
}

