import java.util.*;
import java.util.concurrent.*;

/**
 * Factory simulation with multiple versions and concurrent workshops.
 * Each workshop runs in its own thread and processes items from an input
 * stock to an output stock. All stock operations are synchronized.
 */
public class FactorySimulation {

    private static final int SENTINEL = Integer.MIN_VALUE;

    /* Thread‑safe stock implementation */
    static class Stock {
        private final LinkedList<Integer> items = new LinkedList<>();

        public synchronized void put(int item) {
            items.add(item);
            notifyAll();
        }

        public synchronized int take() throws InterruptedException {
            while (items.isEmpty()) {
                wait();
            }
            return items.removeFirst();
        }

        public synchronized int size() {
            return items.size();
        }

        public synchronized boolean isEmpty() {
            return items.isEmpty();
        }
    }

    /* Workshop thread that processes items */
    static class Workshop extends Thread {
        private final Stock input;
        private final Stock output;
        private final boolean isLast;
        private final CountDownLatch latch;

        Workshop(String name, Stock input, Stock output, boolean isLast, CountDownLatch latch) {
            super(name);
            this.input = input;
            this.output = output;
            this.isLast = isLast;
            this.latch = latch;
        }

        @Override
        public void run() {
            try {
                while (true) {
                    int item = input.take();
                    if (item == SENTINEL) {
                        output.put(SENTINEL);
                        break;
                    }
                    // Simulate processing
                    System.out.println(getName() + " processed item " + item);
                    if (isLast) {
                        latch.countDown();
                    }
                    output.put(item);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            System.err.println("Missing factory version input.");
            return;
        }
        int version = sc.nextInt();

        if (!sc.hasNextInt()) {
            System.err.println("Missing number of items to process.");
            return;
        }
        int itemsToProcess = sc.nextInt();

        if (!sc.hasNextInt()) {
            System.err.println("Missing number of items in input stock.");
            return;
        }
        int stockSize = sc.nextInt();

        Stock inputStock = new Stock();
        Stock outputStock = new Stock();

        for (int i = 0; i < stockSize && sc.hasNextInt(); i++) {
            inputStock.put(sc.nextInt());
        }

        /* Build workshop chain according to the selected version */
        List<Workshop> workshops = new ArrayList<>();
        CountDownLatch latch = new CountDownLatch(itemsToProcess);

        Stock prevOutput = inputStock;
        for (int i = 1; i <= version; i++) {
            Stock nextOutput = (i == version) ? outputStock : new Stock();
            boolean isLast = (i == version);
            Workshop w = new Workshop("Workshop" + i, prevOutput, nextOutput, isLast, latch);
            workshops.add(w);
            prevOutput = nextOutput;
        }

        /* Start all workshop threads */
        for (Workshop w : workshops) {
            w.start();
        }

        /* Wait until all items are processed */
        latch.await();

        /* Signal termination to the first workshop */
        inputStock.put(SENTINEL);

        /* Wait for all workshops to finish */
        for (Workshop w : workshops) {
            w.join();
        }

        /* Compute remaining items in input stock (excluding sentinel) */
        int remainingCount = inputStock.size() - 1; // sentinel present

        /* Collect processed items from the output stock */
        List<Integer> outputItems = new ArrayList<>();
        while (!outputStock.isEmpty()) {
            int item = outputStock.take();
            if (item != SENTINEL) {
                outputItems.add(item);
            }
        }

        /* Output results */
        System.out.println("\nProcessed items: " + itemsToProcess);
        System.out.println("Remaining items in input stock: " + remainingCount);
        System.out.print("Output stock items: ");
        if (outputItems.isEmpty()) {
            System.out.println("none");
        } else {
            System.out.println(outputItems.stream()
                    .map(String::valueOf)
                    .reduce((a, b) -> a + ", " + b).orElse(""));
        }
    }
}

