class EnhancedFactory {
    private static final int SENTINEL = Integer.MIN_VALUE;

    /**
     * Runs the factory simulation.
     *
     * @param version          factory version (1‑4)
     * @param itemsToProcess   number of items to process
     * @param inputItems       list of item identifiers in the input stock
     * @return FactoryPerformance containing all simulation results
     * @throws InterruptedException if thread execution is interrupted
     */
    public FactoryPerformance runSimulation(int version, int itemsToProcess,
                                            List<Integer> inputItems) throws InterruptedException {
        // Create stocks
        Stock inputStock = new Stock();
        Stock outputStock = new Stock();

        // Load input stock
        for (int item : inputItems) {
            inputStock.put(item);
        }

        // Counters and synchronization primitives
        AtomicInteger processedCount = new AtomicInteger(0);
        AtomicInteger errorCount = new AtomicInteger(0);
        CountDownLatch latch = new CountDownLatch(itemsToProcess);

        // Build workshop chain
        List<Workshop> workshops = new ArrayList<>();
        List<Stock> intermediateStocks = new ArrayList<>();

        Stock prevOutput = inputStock;
        for (int i = 1; i <= version; i++) {
            Stock nextOutput = (i == version) ? outputStock : new Stock();
            boolean isLast = (i == version);
            Workshop w = new Workshop("Workshop" + i, prevOutput, nextOutput,
                    isLast, latch, processedCount, errorCount);
            workshops.add(w);
            if (!isLast) {
                intermediateStocks.add(nextOutput);
            }
            prevOutput = nextOutput;
        }

        // Start all workshops
        long startTime = System.nanoTime();
        for (Workshop w : workshops) {
            w.start();
        }

        // Wait until all items are processed
        latch.await();

        // Signal termination to the first workshop
        inputStock.put(SENTINEL);

        // Wait for all workshops to finish
        for (Workshop w : workshops) {
            w.join();
        }
        long endTime = System.nanoTime();

        // Compute final stock levels (excluding sentinel)
        int inputFinal = countNonSentinel(inputStock);
        List<Integer> intermediateFinal = new ArrayList<>();
        for (Stock s : intermediateStocks) {
            intermediateFinal.add(countNonSentinel(s));
        }
        int outputFinal = countNonSentinel(outputStock);

        // Collect processed items from the output stock
        List<Integer> outputItems = new ArrayList<>();
        while (!outputStock.isEmpty()) {
            int item = outputStock.take();
            if (item != SENTINEL) {
                outputItems.add(item);
            }
        }

        // Build performance result
        return new FactoryPerformance(
                processedCount.get(),
                errorCount.get(),
                (endTime - startTime) / 1_000_000,
                inputFinal,
                intermediateFinal,
                outputFinal,
                outputItems
        );
    }

    /** Helper to count non‑sentinel items in a stock. */
    private static int countNonSentinel(Stock stock) {
        int count = 0;
        while (!stock.isEmpty()) {
            int item = stock.take();
            if (item != SENTINEL) {
                count++;
            }
        }
        return count;
    }
}

