import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

class P2PAddressServer {
    private final ConcurrentHashMap<String, PeerInfo> peerRegistry;
    private final int maxPeers;
    private final AtomicInteger currentPeers;

    public P2PAddressServer() {
        this(100);
    }

    public P2PAddressServer(int maxPeers) {
        if (maxPeers < 1 || maxPeers > 10000) {
            throw new IllegalArgumentException("maxPeers must be between 1 and 10000");
        }
        this.maxPeers = maxPeers;
        this.peerRegistry = new ConcurrentHashMap<>();
        this.currentPeers = new AtomicInteger(0);
    }

    public boolean registerPeer(String peerId, String address, int port) {
        // Reserve a slot if capacity allows
        while (true) {
            int current = currentPeers.get();
            if (current >= maxPeers) {
                return false; // capacity reached
            }
            if (currentPeers.compareAndSet(current, current + 1)) {
                // Successfully reserved a slot
                PeerInfo info = new PeerInfo(address, port, System.currentTimeMillis());
                PeerInfo existing = peerRegistry.putIfAbsent(peerId, info);
                if (existing == null) {
                    return true; // registration succeeded
                } else {
                    // Duplicate ID, rollback reservation
                    currentPeers.decrementAndGet();
                    return false;
                }
            }
            // If compareAndSet failed, retry
        }
    }

    public static class PeerInfo {
        private final String address;
        private final int port;
        private final long registrationTime;

        public PeerInfo(String address, int port, long registrationTime) {
            this.address = address;
            this.port = port;
            this.registrationTime = registrationTime;
        }

        public String getAddress() {
            return address;
        }

        public int getPort() {
            return port;
        }

        public long getRegistrationTime() {
            return registrationTime;
        }

        @Override
        public String toString() {
            return address + ":" + port + " (registered at " + registrationTime + ")";
        }
    }
}

