import java.util.*;

public class ChatMessageProcessor {
    // Map to store messages for each user
    private final Map<String, List<String>> userMessages = new HashMap<>();

    // List to maintain active users
    private final List<String> activeUsers = new ArrayList<>();

    /**
     * Adds a user to the active users list.
     *
     * @param username the name of the user joining
     * @return an empty list of notifications since no other users exist yet
     */
    public List<String> userJoins(String username) {
        if (!activeUsers.contains(username)) {
            activeUsers.add(username);
            userMessages.putIfAbsent(username, new ArrayList<>());
        }
        return Collections.emptyList();
    }

    // Optional: getters for testing or further functionality
    public Map<String, List<String>> getUserMessages() {
        return userMessages;
    }

    public List<String> getActiveUsers() {
        return activeUsers;
    }
}

