import java.util.*;
import java.util.concurrent.*;

class MessageProducer {
    private final BlockingQueue<String> messageQueue;
    private final List<String> sentMessages;
    private final int maxRetries;
    private final long retryDelayMs;

    /**
     * Custom constructor that accepts a queue, max retries, and retry delay.
     *
     * @param queue            the BlockingQueue to use for messages
     * @param maxRetries       maximum number of retry attempts
     * @param retryDelayMillis delay between retries in milliseconds
     */
    public MessageProducer(BlockingQueue<String> queue, int maxRetries, long retryDelayMillis) {
        this.messageQueue = queue;
        this.sentMessages = new ArrayList<>();
        this.maxRetries = maxRetries;
        this.retryDelayMs = retryDelayMillis;
    }

    /**
     * Default constructor that uses a new LinkedBlockingQueue,
     * 3 max retries, and 100ms retry delay.
     */
    public MessageProducer() {
        this(new LinkedBlockingQueue<>(), 3, 100L);
    }

    /**
     * Generates messages with the given prefix and count, then attempts to
     * add each message to the queue using offer with a 100 ms timeout.
     * If the offer fails, it retries up to {@code maxRetries} times,
     * waiting {@code retryDelayMs} between attempts.
     *
     * @param prefix the prefix for each message
     * @param count  the number of messages to generate
     */
    public void sendMessages(String prefix, int count) {
        for (int i = 1; i <= count; i++) {
            String message = prefix + " " + i;
            boolean offered = false;
            int attempts = 0;

            while (!offered && attempts <= maxRetries) {
                try {
                    offered = messageQueue.offer(message, 100, TimeUnit.MILLISECONDS);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    // If interrupted, stop retrying for this message
                    break;
                }

                if (!offered) {
                    attempts++;
                    if (attempts > maxRetries) {
                        // Give up after maxRetries attempts
                        break;
                    }
                    try {
                        Thread.sleep(retryDelayMs);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            }

            if (offered) {
                sentMessages.add(message);
            }
        }
    }

    /**
     * Returns the internal message queue.
     *
     * @return the BlockingQueue containing the messages
     */
    public BlockingQueue<String> getMessageQueue() {
        return messageQueue;
    }

    public int getMaxRetries() {
        return maxRetries;
    }

    public long getRetryDelayMs() {
        return retryDelayMs;
    }

    public List<String> getSentMessages() {
        return Collections.unmodifiableList(sentMessages);
    }
}

