import java.util.*;
import java.util.regex.Pattern;

class UserManager {
    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[A-Za-z0-9+_.-]+@(.+)$");
    private final Map<String, User> usersByEmail = new HashMap<>();
    private final Map<Integer, User> usersById = new HashMap<>();
    private int nextUserId = 1;

    public static class User {
        private final int id;
        private final String email;
        private final String name;
        private boolean active;

        public User(int id, String email, String name) {
            this.id = id;
            this.email = email;
            this.name = name;
            this.active = true;
        }

        public int getId() { return id; }
        public String getEmail() { return email; }
        public String getName() { return name; }
        public boolean isActive() { return active; }
        public void setActive(boolean active) { this.active = active; }
    }

    /**
     * Validates that the provided email is non‑null and matches the EMAIL_PATTERN.
     *
     * @param email the email to validate
     * @return true if the email is valid, false otherwise
     */
    private boolean isValidEmail(String email) {
        return email != null && EMAIL_PATTERN.matcher(email).matches();
    }

    /**
     * Adds a new user with the given email and name.
     *
     * @param email the user's email address
     * @param name  the user's name
     * @return the created User object
     * @throws IllegalArgumentException if the email is invalid, the name is empty, or the email already exists
     */
    public User addUser(String email, String name) {
        if (!isValidEmail(email)) {
            throw new IllegalArgumentException("Invalid email format");
        }
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be empty");
        }
        if (usersByEmail.containsKey(email)) {
            throw new IllegalArgumentException("Email already exists");
        }
        User newUser = new User(nextUserId++, email, name);
        usersByEmail.put(email, newUser);
        usersById.put(newUser.getId(), newUser);
        return newUser;
    }

    /**
     * Finds a user by their email address.
     *
     * @param email the email to search for
     * @return the User if found
     * @throws IllegalArgumentException if the email is null or no user with that email exists
     */
    public User findUserByEmail(String email) {
        if (email == null) {
            throw new IllegalArgumentException("Email cannot be null");
        }
        User user = usersByEmail.get(email);
        if (user == null) {
            throw new IllegalArgumentException("User not found");
        }
        return user;
    }

    /**
     * Returns a list of all active users.
     *
     * @return list of active User objects
     */
    public List<User> getActiveUsers() {
        List<User> activeUsers = new ArrayList<>();
        for (User user : usersByEmail.values()) {
            if (user.isActive()) {
                activeUsers.add(user);
            }
        }
        return activeUsers;
    }
}
